  /* ─── (B) KPI strip — 5 cols → 2 cols on mobile, with proper row borders ─── */
  .rh-kpi-strip {
    grid-template-columns: 1fr 1fr !important;
  }
  /* The inline border-right separators get awkward at 2-col → use border-bottom
     and last-row-trim. Each kpi cell is just an unclassed div; target via :nth-child. */
  .rh-kpi-strip > div {
    padding: 10px 8px !important;
    border-right: none !important;
    border-bottom: 1px solid var(--border-light) !important;
  }
  .rh-kpi-strip > div:nth-child(odd) {
    border-right: 1px solid var(--border-light) !important;
  }
  /* Hide bottom border on the last row (4th + 5th cells when 5 items in 2 cols) */
  .rh-kpi-strip > div:nth-last-child(-n+2) { border-bottom: none !important; }
  .rh-kpi-strip > div > div:first-child { font-size: 9px !important; }
  .rh-kpi-strip > div > div:last-child { font-size: 17px !important; }

  /* ─── Strip empty spacer divs in the result-history surfaces ─── */
  .rh-card > div:empty,
  .rh-profile-card > div:empty,
  .rh-kpi-strip > div:empty { display: none !important; }

  /* ═══════ RESULT HISTORY — student DETAIL VIEW inner sections ═══════
     Sections inside the .rh-two-col layout (lines 2001–2208):
       Left column:
         .rh-history-card     — exam history list
           .rh-history-head   — title + count
           .rh-timeline-row   — each exam row
         .rh-trend-card       — performance trend bars chart
           .rh-trend-scroll   — horizontal scroll container
           .rh-trend-bars     — bars wrapper
             .rh-trend-item   — each bar (.rh-trend-pct + .rh-trend-track + .rh-trend-lbl)
       Right column:
         .rh-side-card        — generic side panel
           .rh-subj-row       — subject performance row
             .rh-subj-name + .rh-subj-bar
           .rh-insight        — insight badge (--good, --warn, --bad)
             .rh-insight-title + .rh-insight-sub
           .rh-report-card    — download report card
             .rh-report-btn   — download button                          */

  /* ─── Two-column layout collapses to single column already at 980px ─── */
  .rh-two-col {
    grid-template-columns: 1fr !important;
    gap: 12px !important;
  }

  /* ─── Exam History card ─── */
  .rh-history-card { border-radius: 12px !important; margin-bottom: 12px !important; }
  .rh-history-head {
    flex-wrap: wrap !important;
    gap: 6px !important;
    padding: 10px 12px !important;
  }

  /* Timeline row — stack into compact card layout */
  .rh-timeline-row {
    flex-wrap: wrap !important;
    gap: 8px !important;
    padding: 12px !important;
    align-items: flex-start !important;
  }
  /* Timeline dot — stays at top-left */
  .rh-timeline-row > div:first-child { margin-top: 4px !important; }
  /* Exam name + meta block — full width on its own line */
  .rh-timeline-row > div:nth-child(2) {
    flex: 1 1 calc(100% - 22px) !important;
    min-width: 0;
  }
  /* Score bar wrapper — full width on its own line */
  .rh-timeline-row > div:nth-child(3) {
    flex: 1 1 100% !important;
    width: 100% !important;
    min-width: 0 !important;
    max-width: 100% !important;
    margin: 0 !important;
  }
  /* Grade letter + Position — sit side by side */
  .rh-timeline-row > div:nth-child(4),
  .rh-timeline-row > div:nth-child(5) {
    flex: 0 0 auto !important;
    width: auto !important;
    padding: 0 8px !important;
    text-align: center !important;
  }
  /* Actions cluster — push to right end of last visual row */
  .rh-timeline-row > div:last-child {
    flex: 1 1 auto !important;
    justify-content: flex-end !important;
    align-items: center !important;
    margin-left: auto;
  }
  .rh-timeline-row .res-action-btn,
  .rh-timeline-row .res-action-btn.view {
    padding: 6px 10px !important;
    font-size: 11px !important;
  }

  /* ─── Performance Trends chart — auto-fit (no horizontal scroll) ─── */
  .rh-trend-card {
    border-radius: 12px !important;
    padding: 12px !important;
    margin-bottom: 12px !important;
    overflow: hidden !important;
  }
  .rh-trend-scroll {
    overflow-x: hidden !important;
    overflow-y: visible !important;
    width: 100% !important;
  }
  .rh-trend-bars {
    min-width: 0 !important;
    width: 100% !important;
    display: flex !important;
    flex-wrap: nowrap !important;
    gap: 4px !important;
    align-items: flex-end !important;
  }
  .rh-trend-item {
    flex: 1 1 0 !important;
    min-width: 0 !important;
    max-width: none !important;
    padding: 0 !important;
  }
  .rh-trend-pct {
    font-size: 9.5px !important;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
    max-width: 100%;
  }
  .rh-trend-track {
    width: 100% !important;
    min-width: 0 !important;
  }
  .rh-trend-lbl {
    font-size: 8.5px !important;
    max-width: 100%;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
    padding: 0 1px;
  }

  /* ─── Right column side cards (Subject Performance / Insights / Downloads) ─── */
  .rh-side-card {
    border-radius: 12px !important;
    padding: 12px !important;
    margin-bottom: 0 !important;
  }

  /* Subject Performance rows */
  .rh-subj-row {
    gap: 8px !important;
    padding: 7px 0 !important;
  }
  .rh-subj-name {
    flex: 0 0 90px !important;
    min-width: 0;
    font-size: 11.5px !important;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
  }
  .rh-subj-bar {
    flex: 1 1 auto !important;
    min-width: 0;
  }

  /* Academic Insight chips */
  .rh-insight {
    padding: 10px 12px !important;
    gap: 9px !important;
    align-items: flex-start !important;
    margin-bottom: 8px !important;
  }
  .rh-insight i { font-size: 14px !important; margin-top: 1px; }
  .rh-insight-title { font-size: 12px !important; }
  .rh-insight-sub {
    font-size: 11px !important;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
  }

  /* Download report cards */
  .rh-report-card {
    padding: 10px 12px !important;
  }
  .rh-report-btn {
    width: 100% !important;
    justify-content: center !important;
    padding: 8px 12px !important;
    font-size: 12px !important;
    box-sizing: border-box;
  }

  /* Empty spacers inside detail view sections */
  .rh-history-card > div:empty,
  .rh-trend-card > div:empty,
  .rh-side-card > div:empty,
  .rh-timeline-row > div:empty { display: none !important; }

  /* ─── Subject tab strip inside Syllabus editor ─── */
  .syl-subj-tabs {
    overflow-x: auto;
    -webkit-overflow-scrolling: touch;
    scrollbar-width: none;
    flex-wrap: nowrap !important;
  }
  .syl-subj-tabs::-webkit-scrollbar { display: none; }
  .syl-subj-tab { flex: 0 0 auto; }

  /* ─── RESULTS SUB-TAB BAR (Result Setup / Single / Combined / History) ─── */
  .res-sub-tabs {
    overflow-x: auto;
    -webkit-overflow-scrolling: touch;
    scrollbar-width: none;
    flex-wrap: nowrap !important;
    white-space: nowrap;
  }
  .res-sub-tabs::-webkit-scrollbar { display: none; }
  .res-sub-tab {
    flex: 0 0 auto;
    min-width: 140px;
    padding: 10px 14px;
    font-size: 12.5px;
  }

  /* ─── Term filter pills — wrap (short pills) ─── */
  .rh-term-pills,
  .res-term-pills,
  .rh-filter-pills,
  .res-filter-bar {
    flex-wrap: wrap;
    gap: 6px;
  }

  /* ─── RESULT HISTORY CARDS (.rh-card) ─── */
  .rh-grid {
    grid-template-columns: 1fr !important;
    gap: 10px;
  }
  .rh-card { padding: 12px 14px; }
  .rh-card-head { gap: 10px; }
  .rh-name { font-size: 14px; }
  .rh-father { font-size: 11px; }
  .rh-cls { font-size: 11px; }
  .rh-kpis { grid-template-columns: repeat(3, 1fr); gap: 6px; }
  .rh-kpi { padding: 8px 6px; }
  .rh-foot { flex-wrap: wrap; gap: 6px 12px; }

  /* ─── RH KPI strip / sections ─── */
  .rh-kpi-strip {
    grid-template-columns: 1fr 1fr !important;
    gap: 8px;
  }
  .rh-two-col,
  .rco-grid,
  .rct-grid {
    grid-template-columns: 1fr !important;
    gap: 10px;
  }

  /* ─── STUDENT STATS (Avg / Best / Worst / Attend) ─── */
  .stu-stats,
  .student-stats {
    grid-template-columns: 1fr 1fr !important;
    gap: 10px;
    padding: 12px;
  }
  .stu-stats .stat-item,
  .student-stats .stat-item {
    text-align: center;
    padding: 8px;
    border-radius: 8px;
  }

  /* ─── Result student tables — keep horizontal scroll w/ sticky col ─── */
  .res-student-scroll,
  .cbr-table-wrap {
    overflow-x: auto;
    -webkit-overflow-scrolling: touch;
  }
  .res-student-table,
  .cbr-student-table { min-width: 760px; }

  /* ─── Result trend bars chart — horizontal scroll ─── */
  .rh-trend-bars {
    overflow-x: auto;
    -webkit-overflow-scrolling: touch;
    min-width: 520px;
  }

  /* ─── CBR group head/body — stack ─── */
  .cbr-group-head {
    flex-direction: column;
    align-items: stretch;
    gap: 10px;
    padding: 12px 14px;
  }
  .cbr-group-side { justify-content: flex-start !important; gap: 8px; }

  /* ─── Modals (exam-modal, rs-modal, syl-edit-modal, ds-edit-modal, etc.) ─── */
  .exam-modal,
  .exam-modal.ds-edit-modal,
  .exam-modal.syl-edit-modal,
  .exam-modal.rs-modal,
  .report-picker,
  .rc-preview-shell {
    max-width: 95vw !important;
    max-height: 90vh !important;
    border-radius: 12px;
  }
  .exam-modal-head,
  .exam-modal-body,
  .exam-modal-foot { padding-left: 14px !important; padding-right: 14px !important; }
  .exam-modal-foot {
    flex-direction: column;
    gap: 8px;
    align-items: stretch;
  }
  .exam-modal-foot > button { width: 100%; }

  /* ─── Edit form grids — 1 col ─── */
  .ds-edit-fields,
  .ds-edit-fields-row,
  .exam-form-grid {
    grid-template-columns: 1fr !important;
    gap: 10px;
  }

  /* ─── Result setup config grids ─── */
  .rs-cfg-grid,
  .rs-grade-grid { grid-template-columns: 1fr !important; gap: 10px; }

  /* ─── Confirm delete dialog (.confirm-overlay / .confirm-dialog) ─── */
  .confirm-dialog { max-width: 95vw !important; }
  .confirm-footer { flex-direction: column; gap: 8px; }
  .confirm-footer .confirm-btn { width: 100%; }
}

/* ═══════════════════════════════════════════════════════════════════
   TABLET RESPONSIVE — Examination (768px – 1023px)
   ═══════════════════════════════════════════════════════════════════ */
@media (min-width: 768px) and (max-width: 1023px) {
  .rh-grid { grid-template-columns: repeat(2, 1fr); }
  .rh-kpi-strip { grid-template-columns: repeat(2, 1fr); }
  .stu-stats,
  .student-stats { grid-template-columns: repeat(2, 1fr); }
  .rco-grid,
  .rct-grid { grid-template-columns: repeat(2, 1fr); }
}


/* ═══════════════════════════════════════════════════════════════
   ERP DESIGN SYSTEM ALIGNMENT — Examination
   Canonical references: Fee / Attendance / Inventory
   ═══════════════════════════════════════════════════════════════ */
.exam-tabs-row,
.res-sub-tabs {
  display:flex;
  gap:6px;
  background:var(--bg-card);
  border:1.5px solid var(--border-light);
  border-radius:var(--radius-lg);
  padding:5px;
  margin-bottom:18px;
  box-shadow:var(--shadow-sm);
  overflow-x:auto;
  flex-wrap:nowrap;
  -webkit-overflow-scrolling:touch;
}
.exam-tab,
.res-sub-tab {
  flex:1;
  display:flex;
  align-items:center;
  justify-content:center;
  gap:8px;
  padding:11px 18px;
  border:none;
  border-radius:var(--radius-md);
  background:transparent;
  color:var(--text-muted);
  font-family:var(--font-body);
  font-size:13px;
  font-weight:600;
  cursor:pointer;
  transition:var(--tr);
  white-space:nowrap;
}
.exam-tab:hover:not(.active),
.res-sub-tab:hover:not(.active) {
  background:var(--bg-muted);
  color:var(--text-primary);
}
.exam-tab.active,
.res-sub-tab.active {
  background:linear-gradient(135deg,#1E3A8A 0%,#1E40AF 60%,#2563EB 100%);
  color:#fff;
  border-color:transparent;
  box-shadow:0 6px 20px rgba(30,58,138,.4),inset 0 1px 0 rgba(255,255,255,.2);
}

/* Secondary/tertiary sub-navigation uses canonical ERP pill segments */
.exam-term-chips,
.rs-modal-tabs,
.syl-subj-tabs {
  display:flex;
  width:100%;
  gap:4px;
  background:var(--bg-card);
  border:1.5px solid var(--border-light);
  border-radius:var(--radius-full);
  padding:5px;
  margin-bottom:18px;
  box-shadow:var(--shadow-sm);
  overflow-x:auto;
  flex-wrap:nowrap;
}
.exam-term-chip,
.rs-modal-tab,
.syl-subj-tab {
  flex:1;
  display:flex;
  align-items:center;
  justify-content:center;
  gap:7px;
  padding:9px 14px;
  margin:0;
  border:none;
  border-radius:var(--radius-full);
  background:transparent;
  color:var(--text-muted);
  font-family:var(--font-body);
  font-size:12.5px;
  font-weight:600;
  cursor:pointer;
  transition:var(--tr);
  white-space:nowrap;
}
.exam-term-chip:hover:not(.active),
.rs-modal-tab:hover:not(.active),
.syl-subj-tab:hover:not(.active) {
  background:var(--bg-muted);
  color:var(--text-primary);
  border-color:transparent;
}
.exam-term-chip.active,
.rs-modal-tab.active,
.syl-subj-tab.active {
  background:linear-gradient(135deg,#1E3A8A,#1E40AF);
  color:#fff;
  border-color:transparent;
  font-weight:600;
  box-shadow:0 4px 12px rgba(30,58,138,.3);
}

/* Exam-specific selector buttons now follow the same tertiary control theme */
.cbr-tab,
.ds-exam-btn {
  min-height:38px;
  padding:8px 14px;
  border:1.5px solid var(--border-light);
  border-radius:var(--radius-md);
  background:var(--bg-card);
  color:var(--text-muted);
  font-family:var(--font-body);
  font-size:12.5px;
  font-weight:600;
  box-shadow:none;
  transition:var(--tr);
}
.cbr-tab:hover:not(.active),
.ds-exam-btn:hover:not(.active) {
  background:var(--bg-muted);
  border-color:var(--border-med);
  color:var(--text-primary);
  transform:none;
  box-shadow:none;
}
.cbr-tab.active,
.ds-exam-btn.active {
  background:linear-gradient(135deg,#1E3A8A,#1E40AF);
  color:#fff;
  border-color:transparent;
  box-shadow:0 4px 12px rgba(30,58,138,.3);
}

/* Canonical ERP primary/secondary action buttons */
.exam-submit-btn,
.exam-add-btn {
  height:40px;
  padding:0 20px;
  border:none;
  border-radius:var(--radius-md);
  background:linear-gradient(135deg,#1E40AF,#1E3A8A);
  color:#fff;
  font-family:var(--font-body);
  font-size:13px;
  font-weight:600;
  display:inline-flex;
  align-items:center;
  justify-content:center;
  gap:7px;
  box-shadow:0 4px 14px rgba(30,58,138,.28);
  transition:var(--tr);
}
.exam-submit-btn:hover,
.exam-add-btn:hover {
  transform:translateY(-1px);
  box-shadow:0 8px 20px rgba(30,58,138,.38);
}
.exam-cancel-btn {
  height:40px;
  padding:0 20px;
  border:1.5px solid var(--border-light);
  border-radius:var(--radius-md);
  background:var(--bg-card);
  color:var(--text-secondary);
  font-family:var(--font-body);
  font-size:13px;
  font-weight:600;
}
.exam-cancel-btn:hover {
  background:var(--bg-muted);
  border-color:var(--border-med);
  color:var(--text-primary);
}

.bmu-mode-card {
  display:flex; flex-direction:column; align-items:flex-start; gap:6px; text-align:left;
  padding:14px; border:1.5px solid var(--border-light); border-radius:var(--radius-md, 10px);
  background:var(--bg-card); cursor:pointer; font-family:inherit;
}
.bmu-mode-card:hover { border-color: var(--brand-primary); background: var(--bg-muted); }
.bmu-mode-card.selected { border-color: var(--brand-primary); background: rgba(30,64,175,.06); box-shadow: 0 0 0 2px rgba(30,64,175,.12); }
.bmu-mode-icon { width: 36px; height: 36px; border-radius: 10px; display: flex; align-items: center; justify-content: center; font-size: 15px; margin-bottom: 2px; }
.bmu-mode-title { font-size: 13px; font-weight: 800; color: var(--text-primary); }
.bmu-mode-desc { font-size: 11.5px; color: var(--text-muted); line-height: 1.5; }
.bmu-guide-box { background: rgba(30,64,175,.05); border: 1.5px solid var(--border-light); border-radius: var(--radius-md, 10px); padding: 14px 16px; margin-bottom: 16px; }
.bmu-guide-title { font-size: 12px; font-weight: 800; color: #1E40AF; display: flex; align-items: center; gap: 6px; margin-bottom: 8px; }
.bmu-guide-list { margin: 0; padding-left: 18px; font-size: 12px; color: var(--text-secondary); line-height: 1.7; }
.bmu-upload-drop {
  display:flex; flex-direction:column; align-items:center; justify-content:center; text-align:center;
  border:1.5px dashed var(--border-med, #CBD5E1); border-radius:var(--radius-md, 10px);
  padding:22px 16px; cursor:pointer; background:var(--bg-muted); width:100%;
}
.bmu-upload-drop:hover { border-color: var(--brand-primary); background: rgba(30,64,175,.05); }
.bmu-issue-box { border-radius: var(--radius-md, 10px); padding: 12px 14px; margin-bottom: 12px; border: 1.5px solid; }
.bmu-issue-box.error { background: rgba(220,38,38,.06); border-color: rgba(220,38,38,.25); }
.bmu-issue-box.warn { background: rgba(217,119,6,.06); border-color: rgba(217,119,6,.25); }
.bmu-issue-box.ok { background: rgba(22,163,74,.06); border-color: rgba(22,163,74,.25); }
.bmu-issue-title { font-size: 12.5px; font-weight: 800; display: flex; align-items: center; gap: 7px; }
.bmu-issue-box.error .bmu-issue-title { color: #DC2626; }
.bmu-issue-box.warn .bmu-issue-title { color: #D97706; }
.bmu-issue-box.ok .bmu-issue-title { color: #16A34A; }
.bmu-issue-list { margin: 8px 0 0; padding-left: 18px; font-size: 11.5px; color: var(--text-secondary); line-height: 1.7; max-height: 160px; overflow-y: auto; }
.bmu-preview-wrap { max-height: 260px; overflow-y: auto; border: 1px solid var(--border-light); border-radius: var(--radius-md, 10px); }
.bmu-preview-table { width: 100%; border-collapse: collapse; font-size: 12px; }
.bmu-preview-table th { position: sticky; top: 0; background: var(--bg-muted); color: var(--text-secondary); font-weight: 800; font-size: 10.5px; text-transform: uppercase; letter-spacing: .4px; padding: 8px 10px; text-align: left; border-bottom: 1.5px solid var(--border-light); }
.bmu-preview-table td { padding: 7px 10px; border-bottom: 1px solid var(--border-light); color: var(--text-primary); }
.bmu-preview-table tbody tr:last-child td { border-bottom: none; }
[data-theme="dark"] .bmu-mode-card { background: var(--bg-card); }
[data-theme="dark"] .bmu-upload-drop { background: rgba(255,255,255,.03); }

@media (max-width:768px) {
  .exam-tabs-row,.res-sub-tabs { padding:4px; gap:3px; margin-bottom:14px; }
  .exam-tab,.res-sub-tab { flex:0 0 auto; padding:9px 12px; font-size:11.5px; gap:5px; }
  .exam-term-chips,.rs-modal-tabs,.syl-subj-tabs { padding:4px; gap:3px; border-radius:14px; }
  .exam-term-chip,.rs-modal-tab,.syl-subj-tab { flex:0 0 auto; padding:8px 11px; font-size:11.5px; }
  .exam-submit-btn,.exam-add-btn,.exam-cancel-btn { height:38px; padding:0 14px; font-size:12px; }
}
