import React, { useEffect, useRef, useState } from 'react';
import { createPortal } from 'react-dom';
import ExcelJS from 'exceljs';
import Tooltip from './Tooltip';
import TutorialModal from './TutorialModal';
import * as cbrApi from '../services/combinedAssessmentService';
import { buildUrl, resolveMediaUrl, activeSessionName, storeSwitchedSession, readStoredActiveSession, hasStoredActiveSessionCheck } from '../../utils/apiConfig';
import { formatAcademicYearLabel, resolveAcademicSession } from '../../utils/pdfReports';
import { deliverReport } from './reportDelivery';
import {
  StandardReportPicker, buildStandardReportHtml, buildReportTableHtml,
  downloadReportExcel, downloadReportHtmlAsExcel, reportFileName,
  reportPalette, reportStatusPill, reportAcademicYear,
} from '../reports/reportKit';
import { useModuleReadOnly, validateSessionDateFromStorage } from '../pages/Settings/settingsStore';
import { getActiveSessionID } from '../services/attendanceService';
import { usePermissions } from '../context/PermissionsContext';
import { studentMatchRank } from '../utils/studentSearch';
import useUiPref from '../hooks/useUiPref';
import useAsync from '../hooks/useAsync';
import * as preschoolService from '../services/preschoolService';
import {
  pProgressForStudent,
  pTemplateForExam,
  PreschoolResultSetup,
  PreschoolLevelPickModal,
  PreschoolAssessmentModal,
  PreschoolResultCardViewer,
  PreschoolTemplatePreviewModal,
} from './PreschoolExam';

/* ── Shared report-kit glue: header / footer / toolbar come from reportKit.
   School name + academic year stay LIVE — they come from the /report-header
   branch (branchSchool) this module already loads; when that is missing the
   kit falls back to the current branch on its own. ── */
const examKitEsc = s => String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
const examKitSchool = bs => (bs && bs.name ? examKitEsc(bs.name) : undefined);
const examKitYear = bs => formatAcademicYearLabel(resolveAcademicSession(bs || {})) || reportAcademicYear();
/* Kit subtitle line — "<Academic Year> · <report context>" (the old in-body headers showed the year). */
const examKitSub = (bs, ...parts) => [examKitEsc(examKitYear(bs)), ...parts].filter(Boolean).join(' &middot; ');
/* Table rules the old per-report <head> CSS applied — the kit's page shell has none. */
const EXAM_KIT_TABLE_CSS = '<style>table{width:100%;table-layout:fixed}td,th{overflow-wrap:anywhere;word-break:break-word}</style>';
/* PDF / Word keep going through deliverReport (print-safe + MathLive CSS and the
   real .docx "Save as Word" preview); Excel saves the same report HTML as .xls. */
function examDeliverReport(name, format, html, opts = {}) {
  if (format === 'excel') {
    if (opts.win) { try { opts.win.close(); } catch (e) { /* ignore */ } }
    downloadReportHtmlAsExcel(html, `${reportFileName(String(name || 'Report').replace(/\s*-\s*/g, ' '))}.xls`);
    return;
  }
  deliverReport(name, format, html, opts);
}
/* ═══════════════════════════════════════════════════════════════════
   EXAMINATION — port of the HTML #module-exam (only Exam Setup is
   functional; other tabs show Coming Soon).
   Source: ~/Desktop/ERP-HTML/Final_Submissions_with_Examination_3 (43).html
   ═══════════════════════════════════════════════════════════════════ */

/* Term chips har tab par API se aate hain (POST /api/termscrud, getTerms()) —
   `terms` khali array se shuru hoti hai aur error par bhi khali hi rehti hai,
   yani screen par kabhi banaya hua term nahi dikhta.

   Yahan pehle EXAM_TERMS ki ek list padi thi ('2nd', '3rd Term', '5th Term',
   'testing', 'combined'). Wo kahin istemal nahi hoti thi — kisi ne API ka
   jawab copy kar ke rakh diya tha — magar dekhne me lagta tha ke chips isi
   se ban rahe hain. Hata di gayi hai. */

const ALL_CLASSES = [
  'class 1A (B)', 'class 1A (C)', 'class 1A (D)', 'class 1A (Green f)',
  'class 1A (New)', 'II-Pre (A)', 'III-Pre (2)', 'Marketing Class (A)',
  'Class IV', 'Class V', 'Class VI', 'Class VII', 'Class VIII',
  'Class 1', 'Class 2', 'Class 3', 'Class 4', 'Class 5',
  'Class 6', 'Class 7', 'Class 8', 'Class 9', 'Class 10',
  'Grade 1 - Section A', 'Grade 2 - Section A', 'Grade 3 - Section A',
  'Grade 4 - Section A', 'Grade 5 - Section A',
];

/* Exams now load via examService (src/services/examService.js). Add/edit/delete
   are still in-memory until backend wires the mutation endpoints. */

/* ── Date Sheet subject vocabulary + seed ── */
const ALL_SUBJECTS = [
  'English', 'Urdu', 'Mathematics', 'Science', 'Islamiyat',
  'Social Studies', 'Physics', 'Chemistry', 'Biology', 'Computer Science',
  'Pak Studies', 'Arabic', 'History', 'Geography', 'Art & Drawing',
];
/* ── Syllabus seed (HTML #syllabusData) ── */
/* Syllabus poora API se aata hai — koi seed nahi. */
function sylClassStatus(data) {
  if (!data || !data.length) return { label:'Not Added', cls:'notadded', icon:'fa-circle-xmark' };
  const withContent = data.filter(s => s.content && s.content.replace(/<[^>]+>/g,'').trim().length > 0);
  if (withContent.length === 0)            return { label:'Not Added',       cls:'notadded', icon:'fa-circle-xmark' };
  if (withContent.length === data.length)  return { label:'Added',           cls:'added',    icon:'fa-circle-check' };
  return                                          { label:'Partially Added', cls:'partial',  icon:'fa-circle-half-stroke' };
}

/* Date sheets poori API se aati hain — koi seed nahi. */

/* ── Helpers ── */
function parseDDMMYYYY(s) {
  if (!s) return null;
  
  // If it's already a Date object
  if (s instanceof Date) return s;
  
  // Handle ISO format (YYYY-MM-DD)
  if (s.includes('-')) {
    const [y, m, d] = s.split('T')[0].split('-');
    return new Date(parseInt(y), parseInt(m) - 1, parseInt(d));
  }
  
  // Handle DD/MM/YYYY format
  const [d, m, y] = s.split('/');
  return new Date(parseInt(y), parseInt(m) - 1, parseInt(d));
}


function inputToDDMMYYYY(s) {
  if (!s) return '';
  const [y, m, d] = s.split('-');
  return `${d}/${m}/${y}`;
}
function ddmmyyyyToInput(s) {
  if (!s) return '';
  const [d, m, y] = s.split('/');
  return `${y}-${m}-${d}`;
}
function getExamStatus(ex) {
  const today = new Date(); today.setHours(0, 0, 0, 0);
  const start = parseDDMMYYYY(ex.from);
  const end   = parseDDMMYYYY(ex.to);
  if (!start) return { label: 'Upcoming', cls: 'upcoming', icon: 'fa-clock' };
  if (today < start) return { label: 'Upcoming', cls: 'upcoming', icon: 'fa-clock' };
  if (!end || today <= end) return { label: 'Current', cls: 'current', icon: 'fa-circle-dot' };
  return { label: 'Past', cls: 'past', icon: 'fa-flag-checkered' };
}
function calcDuration(from, to) {
  if (!from || !to) return '—';
  
  // Parse dates that could be in either ISO format or DD/MM/YYYY format
  const parseDate = (dateStr) => {
    // If it's already a Date object
    if (dateStr instanceof Date) return dateStr;
    
    // Try ISO format (YYYY-MM-DD)
    if (dateStr.includes('-')) {
      const [y, m, d] = dateStr.split('T')[0].split('-');
      return new Date(parseInt(y), parseInt(m) - 1, parseInt(d));
    }
    
    // Try DD/MM/YYYY format
    if (dateStr.includes('/')) {
      const [d, m, y] = dateStr.split('/');
      return new Date(parseInt(y), parseInt(m) - 1, parseInt(d));
    }
    
    // Try creating Date directly as fallback
    const date = new Date(dateStr);
    return isNaN(date.getTime()) ? null : date;
  };
  
  const fromDate = parseDate(from);
  const toDate = parseDate(to);
  
  if (!fromDate || !toDate) return '—';
  
  const diff = Math.round((toDate - fromDate) / 86400000);
  const days = diff + 1;
  
  return days + ' Day' + (days !== 1 ? 's' : '');
}
/* Grade / condition ki lists SCREEN ka dhancha hain (dropdown ke options),
   data nahi — asli grades aur remarks API se aate hain. */
const RS_GRADE_LIST = ['A+','A','B+','B','C+','C','D+','D','E+','E','F'];
const RS_COND_LIST = [
  { v:'gte',     l:'Greater than or equal to (>=)' },
  { v:'gt',      l:'Greater than (>)' },
  { v:'lte',     l:'Less than or equal to (<=)' },
  { v:'lt',      l:'Less than (<)' },
  { v:'eq',      l:'Equal to (=)' },
  { v:'between', l:'Between' },
];
const RS_COND_MAP = { gte:'≥', gt:'>', lte:'≤', lt:'<', eq:'=', between:'~' };
const RS_GRADE_COLORS = {
  'A+':'#16A34A', 'A':'#0284C7', 'B+':'#2563EB', 'B':'#6366F1',
  'C+':'#7C3AED', 'C':'#D97706', 'D':'#EA580C',  'E':'#9333EA', 'F':'#DC2626',
};

/* ── Result Card Options ki lakeerein ─────────────────────────────────
   Ye DATA nahi, SCREEN ka dhancha hai: kaunse toggle result card par
   mojood hain, aur har ek ka icon. On/off ki asli halat API se aati hai
   (examselectionsettings → RCO_GENERAL_FIELD / RCO_SIG_FIELD se map hoti
   hai), is liye yahan sab `off` se shuru hote hain — warna API ka jawab
   aane se pehle screen wo toggle "on" dikha deti thi jo shayad on tha hi
   nahi. Pehle ye list mock/exams.js me thi, jahan iska koi kaam nahi tha. */
const RCO_GENERAL_OPTIONS = [
  { label: 'Show School Logo',         icon: 'fa-school',         on: false },
  { label: 'Show School Name',         icon: 'fa-heading',        on: false },
  { label: 'Show Student Photo',       icon: 'fa-user',           on: false },
  { label: 'Show Student Roll Number', icon: 'fa-hashtag',        on: false },
  { label: 'Show Class and Section',   icon: 'fa-chalkboard',     on: false },
  { label: 'Show Subject-wise Marks',  icon: 'fa-book',           on: false },
  { label: 'Show Total Marks',         icon: 'fa-calculator',     on: false },
  { label: 'Show Obtained Marks',      icon: 'fa-circle-check',   on: false },
  { label: 'Show Percentage',          icon: 'fa-percent',        on: false },
  { label: 'Show Grade',               icon: 'fa-star',           on: false },
  { label: 'Show Position in Class',   icon: 'fa-trophy',         on: false },
  { label: 'Show Attendance',          icon: 'fa-calendar-check', on: false },
];

const RCO_SIG_OPTIONS = [
  { label: 'Show Principal Signature', icon: 'fa-pen-nib',      on: false },
  { label: 'Show Parent Signature',    icon: 'fa-handshake',    on: false },
  { label: 'Show Final Remarks',       icon: 'fa-comment-dots', on: false },
];

/* Result Card toggle label → examselectionsettings API field name.
   GET (getexamselectionsettingsbybranchid) ke boolean fields se toggles set hote hain,
   aur Save Preferences par inhi se POST (examselectionsettingscrud) payload banta hai. */
const RCO_GENERAL_FIELD = {
  'Show School Logo':         'showSchoolLogo',
  'Show School Name':         'showSchoolName',
  'Show Student Photo':       'showStudentPhoto',
  'Show Student Roll Number': 'showRollNumber',
  'Show Class and Section':   'showClassAndSection',
  'Show Subject-wise Marks':  'showSubjectWiseMarks',
  'Show Total Marks':         'showTotalMarks',
  'Show Obtained Marks':      'showObtainedMarks',
  'Show Percentage':          'showPercentage',
  'Show Grade':               'showGrade',
  'Show Position in Class':   'showPositionInClass',
  'Show Attendance':          'showAttendance',
};
const RCO_SIG_FIELD = {
  'Show Principal Signature': 'showPrincipalSignature',
  'Show Parent Signature':    'showParentSignature',
  'Show Final Remarks':       'showFinalRemarks',
};

/* Session API abhi chal rahi hai (terms uske baad aate hain) → term chips ki jagah
   placeholder dikhao, taake screen "koi term hi nahi" jaisi khali na lage. */
const TermChipsSkeleton = () => (
  <>
    {[0, 1, 2].map(i => <span key={i} className="exam-term-chip skel" aria-hidden="true" />)}
  </>
);

/* ── Result Card preview seed data + helpers ── */
const RES_SUBJECTS = [
  'English','Urdu','Mathematics','Science','Islamiyat',
  'Computer','Social Studies','Quran','Art & Craft','Physical Education',
];

/* A subject counts as ABSENT when its marks weren't entered — no marks record,
   or blank obtained / total marks. The Result-Setup absent handling (zero|exclude)
   then applies to it on the result cards (single / combined / history). */
function resSubjAbsent(rec, subjTotal) {
  const blank = (v) => v == null || String(v).trim() === '';
  if (rec == null) return true;
  const obt = rec.obtainMarks ?? rec.obtainedMarks ?? rec.marks;
  const tot = !blank(rec.totalMarks) ? rec.totalMarks : subjTotal;
  return blank(obt) || blank(tot) || Number(tot) <= 0;
}

/* Result-card absent handling:
   'zero'    — show absent as AB/0 and count them in totals
   'exclude' — show absent as AB and drop them from totals
   '' / none — no option selected: hide 0-mark (and absent) subjects from the card */
function rcHideZeroMarkSubjects(mode) {
  return mode !== 'zero' && mode !== 'exclude';
}
/* Zero / Exclude mode mein 0, blank, ya AB wala subject absent hai.
   Exclude uska total grand total se hata deta hai; Zero usay total mein rakhta hai. */
function rcCardIsAbsent(student, name, mode) {
  const want = String(name).trim().toLowerCase();
  const listed = (student?.absentSubjects || []).some(s => String(s).trim().toLowerCase() === want);
  if (listed) return true;
  if (mode !== 'zero' && mode !== 'exclude') return false;
  const raw = student?.obtained?.[name];
  if (raw == null || String(raw).trim() === '') return true;
  const token = String(raw).trim().toUpperCase();
  if (token === 'AB' || token === 'ABS' || token === 'ABSENT') return true;
  return !(Number(raw) > 0);
}
function rcFilterZeroMarkSubjects(subjects, student) {
  const obtained = student?.obtained || {};
  const absentSet = {};
  (student?.absentSubjects || []).forEach(s => { absentSet[s] = true; });
  return (subjects || []).filter(s => {
    if (absentSet[s]) return false;
    const raw = obtained[s];
    if (raw == null || String(raw).trim() === '') return false;
    return Number(raw) > 0;
  });
}

/* ── Result card par student ki asli tasveer ──────────────────────────
   getstudentsbybranchsectionandgrade har student ke against `picture` deta hai.
   Ek class/section ki list ek hi baar fetch hoti hai (cache), aur map me
   studentID + registration no dono keys par photo rakhi jati hai. */
const rcPhotoCache = new Map();
function loadClassPhotoMap(classID, sectionID) {
  const branchID = sessionStorage.getItem('branchID');
  const key = `${branchID}|${classID}|${sectionID}`;
  if (!rcPhotoCache.has(key)) {
    rcPhotoCache.set(key, (async () => {
      const map = {};
      try {
        const token = sessionStorage.getItem('token');
        const res = await fetch(
          buildUrl(`/api/getstudentsbybranchsectionandgrade?branchID=${branchID}&sectionID=${sectionID}&gradeID=${classID}`),
          { headers: { Authorization: `Bearer ${token}`, Accept: 'application/json' } },
        );
        const json = await res.json();
        (Array.isArray(json) ? json : (json?.data || [])).forEach(s => {
          const raw = String(s.picture ?? s.Picture ?? s.photo ?? '').trim();
          if (!raw || raw.toLowerCase() === 'string' || raw.toUpperCase() === 'N/A') return;
          // Backend localhost:4100 jaisa URL bhejta hai → media host par resolve karo.
          const url = resolveMediaUrl(raw);
          [s.id, s.studentID, s.StudentID, s.registrationNumber, s.RegistrationNumber, s.registerNo, s.rollNo]
            .forEach(k => { if (k != null && String(k).trim() !== '') map[String(k).trim()] = url; });
        });
      } catch (e) {
        console.error('Could not load student pictures:', e);
        rcPhotoCache.delete(key);   // agli baar dobara koshish ho sake
      }
      return map;
    })());
  }
  return rcPhotoCache.get(key);
}

/* Jo key pehle mil jaye (studentID ya roll/registration no) uski photo. */
async function rcStudentPhoto(classID, sectionID, ...keys) {
  if (!classID || !sectionID) return '';
  try {
    const map = await loadClassPhotoMap(classID, sectionID);
    for (const k of keys) {
      if (k == null || String(k).trim() === '') continue;
      const url = map[String(k).trim()];
      if (url) return url;
    }
  } catch { /* photo optional hai */ }
  return '';
}

function rcStuId(stu) {
  return stu?.id ?? stu?.studentID ?? stu?.StudentID ?? stu?._id ?? stu?.studentId ?? null;
}
function rcStuName(stu) {
  const direct = stu?.studentName ?? stu?.StudentName ?? stu?.name ?? stu?.fullName;
  const joined = `${stu?.firstName || stu?.FirstName || ''} ${stu?.lastName || stu?.LastName || ''}`.trim();
  return String(direct || joined || '—');
}
function rcStuFather(stu) {
  return String(stu?.fatherName ?? stu?.FatherName ?? stu?.father ?? '');
}
function rcStuRoll(stu) {
  const id = rcStuId(stu);
  return String(stu?.registrationNumber ?? stu?.RegistrationNumber ?? stu?.registerNo ?? stu?.reg ?? stu?.rollNo ?? id ?? '');
}
function rcPhotoFromRecord(stu, photoMap) {
  const id = rcStuId(stu);
  const roll = rcStuRoll(stu);
  const mapped = photoMap && (photoMap[String(id ?? '')] || (roll ? photoMap[String(roll)] : ''));
  if (mapped) return mapped;
  const raw = String(stu?.picture ?? stu?.Picture ?? stu?.photo ?? '').trim();
  if (!raw || raw.toLowerCase() === 'string' || raw.toUpperCase() === 'N/A') return '';
  return resolveMediaUrl(raw);
}
/* Class ki poori roster. Exam API kabhi sirf 1 row de deti hai — us soorat me
   Launch Setup ki class/section list (jo Students screen use karti hai) se
   lambi list lo, taake bulk har student ka card banaye. */
async function rcFetchClassStudents(classID, sectionID, extra = []) {
  const branchID = sessionStorage.getItem('branchID');
  const token = sessionStorage.getItem('token');
  const headers = { Authorization: `Bearer ${token}`, Accept: 'application/json' };
  const lists = [];
  if (Array.isArray(extra) && extra.length) lists.push(extra);
  try {
    const res = await fetch(
      buildUrl(`/api/getstudentsbybranchsectionandgrade?branchID=${branchID}&sectionID=${sectionID}&gradeID=${classID}`),
      { headers },
    );
    const json = await res.json();
    const primary = saUnwrapList(json);
    if (primary.length) lists.push(primary);
    const nested = json?.data?.students || json?.data?.Students || json?.students || json?.Students;
    if (Array.isArray(nested) && nested.length) lists.push(nested);
  } catch (e) {
    console.error('Could not load class students', e);
  }
  try {
    const res = await fetch(
      buildUrl(`/api/LaunchSetup/get-class-section-studentlist-by-branch/${branchID}`),
      { headers },
    );
    const json = await res.json();
    const grades = Array.isArray(json?.data) ? json.data : (Array.isArray(json) ? json : []);
    const fromRoster = [];
    grades.forEach(g => {
      const gid = g.id ?? g.gradeID ?? g.gradeId;
      if (String(gid) !== String(classID)) return;
      (g.sections || []).forEach(sec => {
        const sid = sec.sectionID ?? sec.id ?? sec.sectionId;
        if (String(sid) !== String(sectionID)) return;
        (sec.students || []).forEach(st => {
          if (st && st.isActive === false) return;
          fromRoster.push(st);
        });
      });
    });
    if (fromRoster.length) lists.push(fromRoster);
  } catch (e) {
    console.error('Could not load branch student roster', e);
  }
  const best = lists.slice().sort((a, b) => b.length - a.length)[0] || [];
  const seen = new Set();
  return best.filter(stu => {
    const id = String(rcStuId(stu) ?? '');
    if (!id || seen.has(id)) return false;
    seen.add(id);
    return true;
  });
}
async function rcMapPool(items, limit, fn, shouldStop) {
  const out = new Array(items.length);
  let cursor = 0;
  const n = Math.min(limit, items.length);
  await Promise.all(Array.from({ length: n }, async () => {
    while (cursor < items.length) {
      if (shouldStop?.()) return;
      const i = cursor++;
      try { out[i] = await fn(items[i], i); }
      catch (e) { console.error('bulk student card failed', e); out[i] = null; }
    }
  }));
  return out.filter(Boolean);
}
function rcOrdinal(n) {
  const num = Number(n) || 0;
  if (!num) return '—';
  const s = ['th', 'st', 'nd', 'rd'];
  const v = num % 100;
  return `${num}${s[(v - 20) % 10] || s[v] || s[0]}`;
}

/* Card ka avatar — asli tasveer, aur na mile (ya load na ho) to naam ke initials. */
function RcAvatar({ src, initials, size, fontSize, border, bg, color, extraStyle }) {
  const [failed, setFailed] = useState(false);
  useEffect(() => { setFailed(false); }, [src]);
  return (
    <div style={{
      width: size, height: size, borderRadius: '50%', flexShrink: 0,
      background: bg, border, overflow: 'hidden',
      display: 'flex', alignItems: 'center', justifyContent: 'center',
      fontSize, fontWeight: 800, color, ...(extraStyle || {}),
    }}>
      {src && !failed
        ? <img src={src} alt={initials || 'student'} onError={() => setFailed(true)}
               style={{ width: '100%', height: '100%', objectFit: 'cover', display: 'block' }} />
        : initials}
    </div>
  );
}

/* Result card ki subject list normalize karo — SIRF wahi subjects jo API se aaye
   aur jinka asli naam mil sake:
     • naam pehle exam-subject API se, warna class subjects (nameMap) se
     • jis row ka koi asli naam nahi (pehle "Subject 34662" jaisa placeholder ban
       kar card par extra rows aa jati thi) usay DROP kar do
     • ek hi subjectID / naam do baar aaye to sirf pehli baar
   Is se card par utne hi subjects aate hain jitne response me hain. */
function saUnwrapList(json) {
  if (Array.isArray(json)) return json;
  if (Array.isArray(json?.data)) return json.data;
  if (Array.isArray(json?.Data)) return json.Data;
  return [];
}
/* SA exam-subject row — IDs API ke liye, naam kabhi numeric ID nahi. */
function saNormSubject(item) {
  if (!item) return null;
  const subjectID = Number(item.subjectID ?? item.SubjectID ?? 0);
  const rawName = String(item.subjectName ?? item.SubjectName ?? item.name ?? item.subject ?? '').trim();
  const subjectName = cbrApi.saIsPlaceholderName(rawName, subjectID) ? '' : rawName;
  if (!subjectID && !subjectName) return null;
  return {
    id: Number(item.id ?? item.ID ?? 0),
    subjectID,
    subjectName,
    totalMarks: item.totalMarks ?? item.TotalMarks ?? '0',
    totalMarksSum: item.totalMarksSum ?? item.TotalMarksSum,
  };
}

function saSubjectLabel(s) {
  const n = String(s?.subjectName || '').trim();
  if (!n || cbrApi.saIsPlaceholderName(n, s?.subjectID)) return '—';
  return n;
}

function rcNormalizeSubjects(rawSubs, nameMap = {}) {
  const seenId = new Set(), seenName = new Set(), out = [];
  (rawSubs || []).forEach(su => {
    if (!su) return;
    const idKey = su.subjectID == null || su.subjectID === '' ? '' : String(su.subjectID);
    let name = String(su.subjectName || nameMap[su.subjectID] || '').trim();
    if (cbrApi.saIsPlaceholderName(name, su.subjectID)) name = String(nameMap[su.subjectID] || '').trim();
    if (cbrApi.saIsPlaceholderName(name, su.subjectID)) name = '';
    if (!idKey && !name) return;
    const nameKey = name.toLowerCase();
    if (idKey && seenId.has(idKey)) return;
    if (name && seenName.has(nameKey)) return;
    if (idKey) seenId.add(idKey);
    if (name) seenName.add(nameKey);
    out.push({ ...su, subjectName: name });
  });
  return out;
}

const RC_GRADE_SETUP = [
