      }
    })();
    return () => { cancelled = true; };
    /* eslint-disable-next-line react-hooks/exhaustive-deps */
  }, [resCardCtx]);

  /* When a student's card opens, load the real per-subject main-exam marks. */
  useEffect(() => {
    if (!cbrCardCtx) { setCbrCardMarks(null); return undefined; }
    setCbrCardMarks(null); // pehle clear — sirf API data dikhe, static/stale flash na ho
    const grp = cbrResults.find(g => g.id === cbrCardCtx.classId);
    const st  = grp?.students.find(s => s.rollNo === cbrCardCtx.studentRollNo);
    if (!grp || !st) return undefined;
    let cancelled = false;
    (async () => {
      try {
        /* The main exam may belong to any term — resolve its term from the
           all-term list (load it if not ready), then fall back to the current. */
        let pool = cbrAllExams;
        if (!pool.length) pool = await loadAllTermExams();
        const mainEx = pool.find(e => String(e.selectExam) === String(grp.mainExamID))
          || pool.find(e => e.name === grp.mainExam);
        const termID = mainEx?.termID ?? selectedTermId;
        let subs = await cbrApi.getMainExamSubjects({ classID: grp.classID, sectionID: grp.sectionID, termID, examID: grp.mainExamID });
        let withMarks = true;
        /* Main exam has no subjects → fall back to a sub exam's subject list and
           leave the marks empty. */
        if ((!subs || !subs.length) && grp.subExamIDs?.length) {
          const subExamId = grp.subExamIDs[0];
          const subTermID = pool.find(e => String(e.selectExam) === String(subExamId))?.termID ?? termID;
          subs = await cbrApi.getMainExamSubjects({ classID: grp.classID, sectionID: grp.sectionID, termID: subTermID, examID: subExamId });
          withMarks = false;
        }
        subs = subs || [];
        // Class ke REAL subjects (naam resolve + fallback list ke liye).
        let syl = [];
        try { syl = await getSyllabusSubjects(grp.classID, grp.sectionID) || []; } catch (e) { /* keep going */ }
        const nameMap = {};
        syl.forEach(s => { nameMap[s.subjectID] = s.subjectName; });
        subs = rcNormalizeSubjects(subs, nameMap);
        // Exam/sub-exam mein koi subject nahi → class ke real subjects dikhao (marks blank → absent).
        if (!subs.length) { subs = rcNormalizeSubjects(syl, nameMap); withMarks = false; }
        const token = sessionStorage.getItem('token');
        const headers = { Authorization: `Bearer ${token}`, Accept: 'application/json' };
        const obtained = {}, totals = {}, remarks = {}, absentSubjects = [];
        if (withMarks) {
          // Direct fetch taa-ke obtain + remarks dono mil sakein (Comment column ke liye)
          await Promise.all(subs.map(async su => {
            try {
              const p = new URLSearchParams({
                classID: String(grp.classID), termID: String(termID ?? ''), ExamID: String(grp.mainExamID),
                SubjectID: String(su.subjectID), StudentID: String(st.studentID), sectionID: String(grp.sectionID), pageNo: '1',
              });
              const r = await fetch(buildUrl(`/api/getsauploadmarksbyclassandtermandexamandsubject?${p}`), { headers });
              const d = await r.json();
              const rec = Array.isArray(d) ? d[0] : (d?.data?.[0] || null);
              obtained[su.subjectName] = Number(rec?.obtainMarks ?? rec?.obtainedMarks ?? 0);
              totals[su.subjectName]   = Number(rec?.totalMarks ?? su.totalMarks ?? 0);
              if (rec?.remarks) remarks[su.subjectName] = rec.remarks;
              if (resSubjAbsent(rec, su.totalMarks)) absentSubjects.push(su.subjectName);
            } catch { obtained[su.subjectName] = 0; totals[su.subjectName] = Number(su.totalMarks ?? 0); absentSubjects.push(su.subjectName); }
          }));
        } else {
          subs.forEach(su => { obtained[su.subjectName] = ''; totals[su.subjectName] = su.totalMarks; absentSubjects.push(su.subjectName); });
        }
        // Student ka FINAL remark (getremarksbystudentfilters) → card ke Final Remarks mein
        let finalRemark = '';
        try {
          const branchID = sessionStorage.getItem('branchID');
          const fp = new URLSearchParams({
            branchID: String(branchID), classID: String(grp.classID), sectionID: String(grp.sectionID),
            examID: String(grp.mainExamID), termID: String(termID ?? ''), studentID: String(st.studentID),
            pageNo: '1', pageCount: '20',
          });
          const fr = await fetch(buildUrl(`/api/getremarksbystudentfilters?${fp}`), { headers });
          const fd = await fr.json();
          const frec = Array.isArray(fd?.data) ? fd.data[0] : (Array.isArray(fd) ? fd[0] : (fd?.data || null));
          finalRemark = frec?.remarks || '';
        } catch (e) { /* no final remark */ }
        // Card ke header ka avatar — student ki asli tasveer.
        const photo = await rcStudentPhoto(grp.classID, grp.sectionID, st.studentID, st.rollNo);
        if (cancelled) return;
        setCbrCardMarks({ subjects: subs.map(s => s.subjectName), totals, obtained, remarks, finalRemark, absentSubjects, photo });
      } catch (e) {
        console.error('Error loading card subject marks:', e);
        if (!cancelled) setCbrCardMarks({ subjects: [], totals: {}, obtained: {} });
      }
    })();
    return () => { cancelled = true; };
    /* eslint-disable-next-line react-hooks/exhaustive-deps */
  }, [cbrCardCtx]);

  /* ── Result History state ── */
  const [rhSearchQ, setRhSearchQ]             = useState('');
  const [rhFilterSession, setRhFilterSession] = useState('');
  const [rhFilterClass, setRhFilterClass]     = useState('');
  const [rhFilterSection, setRhFilterSection] = useState('');
  const [rhFilterExam, setRhFilterExam]       = useState('');
  const [rhSearchFocused, setRhSearchFocused] = useState(false);
  const [rhActiveStudent, setRhActiveStudent] = useState(null); // student object
  /* Search/card se khola gaya student — wapas "All Students" par us ka card
     Fee module jaisa hara highlight rehta hai, agli search type karne tak. */
  const [rhHighlightId, setRhHighlightId]     = useState(null);
  const [rhCardCtx, setRhCardCtx]             = useState(null); // { student, result }
  const [rhReportReq, setRhReportReq]         = useState(null); // { student, type:'card'|'history'|'progress'|'comparison'|'attendance', result? }
  const [rhExams, setRhExams]                 = useState([]);   // student-click par fetched exams (examName/termName)
  const [rhExamsLoading, setRhExamsLoading]   = useState(false);
  const [rhCombined, setRhCombined]           = useState([]);   // student ki class/section ke combined assessments (combinedassessmentcrud)
  const [rhCardMarks, setRhCardMarks]         = useState(null); // View card ke liye real per-subject marks
  const [rhExamScores, setRhExamScores]       = useState({});   // { [exam.id]: overall % } exam history ke liye
  const [rhExamRanks, setRhExamRanks]         = useState({});   // { [exam.id]: "1st" } getstudentsrankings se
  const [rhCombinedRanks, setRhCombinedRanks] = useState({});   // { [combined.id]: { rank:"1st", pct } } getstudentsrankings(mainExamID) se
  const [rhStudentSummaries, setRhStudentSummaries] = useState({}); // { [studentId]: { avgPct, best, count, trend, grade } } card list ke liye
  const [rhAttendance, setRhAttendance] = useState(null); // active student ki REAL attendance: { pct, monthly:[{label,pct}] }
  const [rhAttnLoading, setRhAttnLoading] = useState(false); // attendance per-day loop chalte waqt spinner ke liye
  const rhAttnReqRef = useRef(0); // stale-response guard: student switch hone par purani loop ka result ignore

  /* Active student ki asli attendance (Attendance module se) laao.
     ⚠️ Backend har get-call mein SIRF us `attendanceDate` ka data deta hai (Attendance
     module bhi isi liye per-date loop karta hai). Isliye session ke start→aaj tak har din
     par ek get call chalate hain (concurrency-limited taake browser flood na ho), is student
     ke record ka status le kar overall % + monthly breakdown banate hain.
     sessionID wahi active-session ID hona chahiye jis ke against attendance save hui —
     Attendance module `getActiveSessionID()` use karta hai, hum bhi wahi lete hain. */
  const loadStudentAttendance = async (st) => {
    const reqId = ++rhAttnReqRef.current; // is call ka token; naya student aaya to purana ignore
    setRhAttnLoading(true);
    setRhAttendance(null);
    try {
      const branchID  = Number(sessionStorage.getItem('branchID')) || 0;
      const token     = sessionStorage.getItem('token');
      const classID   = st.gradeId   ?? st.classID   ?? st.classId   ?? '';
      const sectionID = st.sectionId ?? st.sectionID ?? '';
      const studentId = st.id;

      // sessionID: wahi jis se attendance save hui (active-session row ID).
      let sessionID = '';
      try { sessionID = await getActiveSessionID(); } catch (_) { /* ignore */ }
      if (!sessionID) sessionID = sessionStorage.getItem('sessionId') || sessionStorage.getItem('sessionID') || sessionStorage.getItem('SessionID') || '';

      // Session ka date range (sessionStorage se) — start se aaj (ya end, jo pehle aaye) tak.
      const startStr = sessionStorage.getItem('sessionStartDate');
      const endStr   = sessionStorage.getItem('sessionEndDate');
      const start = startStr ? new Date(startStr) : null;
      const today = new Date(); today.setHours(0, 0, 0, 0);
      let end = endStr ? new Date(endStr) : null;
      if (!start || isNaN(start.getTime())) { if (reqId === rhAttnReqRef.current) setRhAttendance({ pct: 0, monthly: [] }); return; }
      if (!end || isNaN(end.getTime()) || end > today) end = today;

      // Har din ki date-string (YYYY-MM-DD).
      const dates = [];
      for (let d = new Date(start.getFullYear(), start.getMonth(), start.getDate()); d <= end; d.setDate(d.getDate() + 1)) {
        dates.push(`${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`);
      }

      const CODE = { '1': 'present', '2': 'absent', '3': 'leave', '4': 'late' };
      const MONTHS = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
      const monthAgg = {};
      let att = 0, total = 0;

      // Concurrency-limited worker-pool (6 parallel) — browser ki 6-connection limit flood na ho.
      let cursor = 0;
      const worker = async () => {
        while (cursor < dates.length && reqId === rhAttnReqRef.current) {
          const dateStr = dates[cursor++];
          try {
            const res = await fetch(buildUrl('/api/student-attendance'), {
              method: 'POST',
              headers: { Authorization: `Bearer ${token}`, 'Content-Type': 'application/json', Accept: 'application/json' },
              body: JSON.stringify({
                id: 0, branchID, studentID: 0, sessionID,
                classID, sectionID, attendanceDate: dateStr, status: '', platform: 'ERP',
                isNotificationGen: false, action: 'get', createdBy: 0, modifiedBy: 0,
              }),
            });
            const json = await res.json();
            const recs = (json?.data || []).filter(r =>
              String(r.AttendanceDate ?? r.attendanceDate ?? '').slice(0, 10) === dateStr &&
              String(r.StudentID ?? r.studentID ?? r.studentId) === String(studentId));
            if (!recs.length) continue;
            const rec = recs[recs.length - 1]; // us din ka aakhri mark
            const raw = rec.Status ?? rec.status;
            const status = CODE[String(raw)] || (typeof raw === 'string' ? raw.toLowerCase() : '');
            if (!status) continue;
            const isAtt = status === 'present' || status === 'late';
            total++; if (isAtt) att++;
            const mi = new Date(`${dateStr}T00:00:00`).getMonth();
            if (!monthAgg[mi]) monthAgg[mi] = { att: 0, total: 0 };
            monthAgg[mi].total++; if (isAtt) monthAgg[mi].att++;
          } catch (_) { /* is din ko skip */ }
        }
      };
      await Promise.all(Array.from({ length: Math.min(6, dates.length) }, worker));

      if (reqId !== rhAttnReqRef.current) return; // beech mein student switch ho gaya → ignore
      const pct = total ? Math.round((att / total) * 100) : 0;
      const monthly = Object.keys(monthAgg)
        .sort((a, b) => a - b)
        .map(mi => ({ label: MONTHS[mi], pct: monthAgg[mi].total ? Math.round((monthAgg[mi].att / monthAgg[mi].total) * 100) : 0 }));
      setRhAttendance({ pct, monthly });
    } catch (e) {
      console.error('Could not load student attendance:', e);
      if (reqId === rhAttnReqRef.current) setRhAttendance({ pct: 0, monthly: [] });
    } finally {
      if (reqId === rhAttnReqRef.current) setRhAttnLoading(false);
    }
  };

  // Student par click karte hi us ki class/section ke exams fetch karo (result history).
  const loadStudentExams = async (st) => {
    try {
      setRhExamsLoading(true);
      // Naya student load hone se pehle purane student ka data foran clear karo —
      // warna naye student ke neeche purane (stale) exams/scores flash karte hain.
      setRhExams([]);
      setRhExamScores({});
      const branchID  = sessionStorage.getItem('branchID');
      const token     = sessionStorage.getItem('token');
      const classID   = st.gradeId   ?? st.classID   ?? st.classId   ?? '';
      const sectionID = st.sectionId ?? st.sectionID ?? '';
      const url = buildUrl(`/api/getexamsbybranchclassidsectionid?branchID=${branchID}&classID=${classID}&sectionID=${sectionID}&pageNo=1`);
      const res = await fetch(url, { headers: { Authorization: `Bearer ${token}`, Accept: '*/*' } });
      const data = await res.json();
      setRhExams(Array.isArray(data?.data) ? data.data : (Array.isArray(data) ? data : []));
    } catch (e) {
      console.error('Could not load student exam history', e);
      setRhExams([]);
    } finally {
      setRhExamsLoading(false);
    }
  };

  // Student ki class/section ke Combined Assessments (combinedassessmentcrud) laao —
  // Exam History mein single ke saath combined records (combinedResultName) bhi dikhein.
  const loadStudentCombined = async (st) => {
    try {
      setRhCombined([]);
      const branchID  = sessionStorage.getItem('branchID');
      const token     = sessionStorage.getItem('token');
      const classID   = st.gradeId   ?? st.classID   ?? st.classId   ?? '';
      const sectionID = st.sectionId ?? st.sectionID ?? '';
      const res = await fetch(buildUrl('/api/combinedassessmentcrud'), {
        method: 'POST',
        headers: { Authorization: `Bearer ${token}`, 'Content-Type': 'application/json', Accept: '*/*' },
        body: JSON.stringify({
          action: 'get',
          branchID: Number(branchID),
          classSectionIDs: [],
          combinedResultName: 'get',
          mainExamID: 0,
          subExams: [],
        }),
      });
      const data = await res.json();
      const list = Array.isArray(data) ? data : (Array.isArray(data?.data) ? data.data : []);
      // Sirf wahi combined jinke classSections mein is student ki class+section shaamil ho.
      const forStudent = list.filter(c => (c.classSections || []).some(cs =>
        String(cs.classID) === String(classID) && String(cs.sectionID) === String(sectionID)));
      setRhCombined(forStudent);
    } catch (e) {
      console.error('Could not load combined assessments', e);
      setRhCombined([]);
    }
  };

  // Jab koi student active ho → uske exams + attendance + combined load karo; band karte hi clear.
  useEffect(() => {
    if (rhActiveStudent) { loadStudentExams(rhActiveStudent); loadStudentAttendance(rhActiveStudent); loadStudentCombined(rhActiveStudent); }
    else { setRhExams([]); setRhCombined([]); rhAttnReqRef.current++; setRhAttendance(null); setRhAttnLoading(false); }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [rhActiveStudent]);

  /* Result History "View" card khulte hi us exam ka REAL per-subject record load karo:
       1) getSyllabusSubjects → class/section ke saare subjects (Math / Science 3 / KG)
       2) har subject ke against getsauploadmarksbyclassandtermandexamandsubject → obtain + total marks
     (Single assessment card bhi yahi marks API use karta hai). */
  useEffect(() => {
    if (!rhCardCtx) { setRhCardMarks(null); return undefined; }
    setRhCardMarks(null); // pehle clear karo taa-ke purana/static data flash na ho (sirf API data dikhe)
    const { result, student } = rhCardCtx;
    const isCombined = result?.type === 'combined' || result?.combinedId != null;
    const classID    = result?.classID   ?? student?.gradeId   ?? student?.classID;
    const sectionID  = result?.sectionID ?? student?.sectionId ?? student?.sectionID;
    // Combined ka koi selectExam nahi hota — uski jagah mainExamID exam ke tor par use hota hai.
    const examID     = isCombined ? result?.mainExamID : result?.selectExam;
    const studentId  = student?.id;
    if (!classID || !sectionID || !examID) { setRhCardMarks({ subjects: [], totals: {}, obtained: {} }); return undefined; }
    let cancelled = false;
    (async () => {
      try {
        const token = sessionStorage.getItem('token');
        const headers = { Authorization: `Bearer ${token}`, Accept: 'application/json' };
        // Combined: mainExam kisi bhi term ka ho sakta hai → term all-term list se resolve karo.
        // Single: result.termID pehle se available hota hai.
        let termID = result?.termID;
        let subjList;
        if (isCombined) {
          let pool = cbrAllExams;
          if (!pool.length) pool = (await loadAllTermExams().catch(() => [])) || [];
          const mainEx = (pool || []).find(e => String(e.selectExam) === String(examID))
            || (pool || []).find(e => e.name === result?.mainExamName);
          termID = mainEx?.termID ?? termID ?? selectedTermId;
          // Combined tab jaisा: mainExam ke subjects; na milein to sub-exam ke subjects (marks phir bhi
          // mainExamID ke against fetch honge). Subject naam class syllabus se resolve.
          let subs = await cbrApi.getMainExamSubjects({ classID, sectionID, termID, examID }).catch(() => []);
          if ((!subs || !subs.length) && (result?.subExamIDs || []).length) {
            const subExamId = result.subExamIDs[0];
            const subTermID = (pool || []).find(e => String(e.selectExam) === String(subExamId))?.termID ?? termID;
            subs = await cbrApi.getMainExamSubjects({ classID, sectionID, termID: subTermID, examID: subExamId }).catch(() => []);
          }
          subs = subs || [];
          let syl = [];
          try { syl = (await getSyllabusSubjects(classID, sectionID)) || []; } catch { /* keep going */ }
          const nameMap = {};
          syl.forEach(s => { nameMap[s.subjectID] = s.subjectName; });
          subjList = rcNormalizeSubjects(subs, nameMap);
          if (!subjList.length) subjList = rcNormalizeSubjects(syl, nameMap);
        } else {
          const rawSubs = await cbrApi.mergeSaSubjectsWithStudentMarks({
            classID, sectionID, termID: termID ?? selectedTermId, examID, studentID: studentId,
          }).catch(() => []);
          subjList = rcNormalizeSubjects((rawSubs || []).map(saNormSubject).filter(Boolean));
        }
        // 2) Har subject ke against student ke obtain/total marks (dono modes ExamID=examID use karte hain)
        const records = await Promise.all(subjList.map(async su => {
          try {
            const p = new URLSearchParams({
              classID: String(classID), termID: String(termID ?? ''), ExamID: String(examID),
              SubjectID: String(su.subjectID), StudentID: String(studentId),
              sectionID: String(sectionID), pageNo: '1',
            });
            const r = await fetch(buildUrl(`/api/getsauploadmarksbyclassandtermandexamandsubject?${p}`), { headers });
            const d = await r.json();
            const rec = Array.isArray(d) ? d[0] : (d?.data?.[0] || null);
            return { su, rec };
          } catch { return { su, rec: null }; }
        }));
        if (cancelled) return;
        const obtained = {}, totals = {}, remarks = {}, absentSubjects = [];
        records.forEach(({ su, rec }) => {
          const name = su.subjectName;
          obtained[name] = Number(rec?.obtainMarks ?? rec?.obtainedMarks ?? 0);
          totals[name]   = Number(rec?.totalMarks ?? su.totalMarks ?? 0);
          if (rec?.remarks) remarks[name] = rec.remarks;   // saved remarks → Comment column
          if (resSubjAbsent(rec, su.totalMarks)) absentSubjects.push(name);
        });
        // 3) Student ka FINAL remark (getremarksbystudentfilters) → card ke Final Remarks mein
        let finalRemark = '';
        try {
          const branchID = sessionStorage.getItem('branchID');
          const fp = new URLSearchParams({
            branchID: String(branchID), classID: String(classID), sectionID: String(sectionID),
            examID: String(examID), termID: String(termID ?? ''), studentID: String(studentId),
            pageNo: '1', pageCount: '20',
          });
          const fr = await fetch(buildUrl(`/api/getremarksbystudentfilters?${fp}`), { headers });
          const fd = await fr.json();
          const frec = Array.isArray(fd?.data) ? fd.data[0] : (Array.isArray(fd) ? fd[0] : (fd?.data || null));
          finalRemark = frec?.remarks || '';
        } catch (e) { /* no final remark */ }
        // Card ke header ka avatar — student ki asli tasveer.
        const photo = await rcStudentPhoto(classID, sectionID, studentId, student?.rollNo);
        if (cancelled) return;
        setRhCardMarks({ subjects: subjList.map(s => s.subjectName), totals, obtained, remarks, finalRemark, absentSubjects, photo });
      } catch (e) {
        console.error('Error loading result-history card subject marks:', e);
        if (!cancelled) setRhCardMarks({ subjects: [], totals: {}, obtained: {} });
      }
    })();
    return () => { cancelled = true; };
    /* eslint-disable-next-line react-hooks/exhaustive-deps */
  }, [rhCardCtx]);

  /* Exam history ke har exam ka overall % compute karo (score bar / grade / Performance Trends ke liye):
     har exam ke saare subjects ke obtain/total marks jodo → % = sum(obtain)/sum(total)*100. */
  useEffect(() => {
    if (!rhActiveStudent || !rhExams.length) { setRhExamScores({}); setRhExamRanks({}); return undefined; }
    const st = rhActiveStudent;
    const classID = st.gradeId ?? st.classID;
    const sectionID = st.sectionId ?? st.sectionID;
    const studentId = st.id;
    let cancelled = false;
    (async () => {
      try {
        const token = sessionStorage.getItem('token');
        const headers = { Authorization: `Bearer ${token}`, Accept: 'application/json' };
        // Har exam ki rankings (getstudentsrankings) — is student ka rank Position column me.
        const ranks = {};
        await Promise.all(rhExams.map(async ex => {
          try {
            const rp = new URLSearchParams({ sectionID: String(sectionID), termID: String(ex.termID ?? ''), examID: String(ex.selectExam) });
            const rr = await fetch(buildUrl(`/api/getstudentsrankings?${rp}`), { headers });
            const rd = await rr.json();
            const listR = Array.isArray(rd) ? rd : (rd?.data || []);
            const mine = listR.find(x => String(x.studentId ?? x.StudentId ?? x.studentID) === String(studentId));
            if (mine && mine.ranking) ranks[ex.id] = String(mine.ranking);
          } catch { /* skip exam ranking */ }
        }));
        if (!cancelled) setRhExamRanks(ranks);

        const scores = {};
        await Promise.all(rhExams.map(async ex => {
          const rawSubs = await cbrApi.getMainExamSubjects({ classID, sectionID, termID: ex.termID, examID: ex.selectExam }).catch(() => []);
          const subs = rcNormalizeSubjects((rawSubs || []).map(saNormSubject).filter(Boolean));
          let obt = 0, tot = 0;
          await Promise.all(subs.map(async su => {
            try {
              const p = new URLSearchParams({
                classID: String(classID), termID: String(ex.termID ?? ''), ExamID: String(ex.selectExam),
                SubjectID: String(su.subjectID), StudentID: String(studentId), sectionID: String(sectionID), pageNo: '1',
              });
              const r = await fetch(buildUrl(`/api/getsauploadmarksbyclassandtermandexamandsubject?${p}`), { headers });
              const d = await r.json();
              const rec = Array.isArray(d) ? d[0] : (d?.data?.[0] || null);
              if (rec) { obt += Number(rec.obtainMarks ?? rec.obtainedMarks ?? 0); tot += Number(rec.totalMarks ?? 0); }
            } catch { /* skip subject */ }
          }));
          scores[ex.id] = tot > 0 ? Math.round((obt / tot) * 100) : 0;
        }));
        if (!cancelled) setRhExamScores(scores);
      } catch (e) {
        console.error('Error computing exam history scores:', e);
        if (!cancelled) setRhExamScores({});
      }
    })();
    return () => { cancelled = true; };
    /* eslint-disable-next-line react-hooks/exhaustive-deps */
  }, [rhExams, rhActiveStudent]);

