    const pct        = totalMarksSum > 0 ? Math.round((obtMarks / totalMarksSum) * 10000) / 100 : 0;
    // Grade card jaisa — gradingcrud (rsGrades) se % ke hisaab se, taake table & card SAME.
    const grade      = (obtMarks > 0 && totalMarksSum > 0)
