/* ═══════════════════════════════════════════════════════════════════
   ADD / EDIT EXAM MODAL — verbatim from HTML #examModalOverlay
   ═══════════════════════════════════════════════════════════════════ */
function ExamModal({ data, onClose, onSave, toast, selectedTermId }) {
  const isEdit = !!data?.id || !!(data?.classes && data.classes.some(c => c.id));
  
  const [name, setName] = useState('');
  const [allClasses, setAllClasses] = useState([]);
  const [classes, setCls] = useState([]);
  const [from, setFrom] = useState('');
  const [to, setTo] = useState('');
  const [search, setSearch] = useState('');
  const [dropOpen, setDropOpen] = useState(false);
  const [originalClassIds, setOriginalClassIds] = useState(new Set());
  
  const wrapRef = useRef(null);
  const inputRef = useRef(null);
  
  // Track original classes for deletion detection
  useEffect(() => {
    if (data && data.classes && data.classes.length) {
      const originalIds = new Set(data.classes.map(c => String(c.sectionID)));
      setOriginalClassIds(originalIds);
    } else if (data && data.id && !data.classes?.length) {
      // If editing but no classes in data, fetch from API or use empty
      setOriginalClassIds(new Set());
    } else {
      setOriginalClassIds(new Set());
    }
  }, [data]);
  
  useEffect(() => {
    if (data) {
      setName(data.name || '');
      setFrom(data.from ? data.from.split('T')[0] : '');
      setTo(data.to ? data.to.split('T')[0] : '');
      
      if (data.classes && data.classes.length) {
        setCls(data.classes);
        const originalIds = new Set(data.classes.map(c => String(c.sectionID)));
        setOriginalClassIds(originalIds);
      } else {
        setCls([]);
        setOriginalClassIds(new Set());
      }
      
      setSearch('');
      setDropOpen(false);
      
      getClasses(data.classes || []);
    }
  }, [data]);
  
  useEffect(() => {
    if (!dropOpen) return;
    
    const close = (e) => {
      if (wrapRef.current && !wrapRef.current.contains(e.target)) {
        setDropOpen(false);
      }
    };
    
    document.addEventListener('mousedown', close);
    return () => document.removeEventListener('mousedown', close);
  }, [dropOpen]);
  
  async function getClasses(preselected) {
    try {
      const branchID = sessionStorage.getItem('branchID');
      const empID = sessionStorage.getItem('employee_ID');
      const token = sessionStorage.getItem('token');
      
      const response = await fetch(
        buildUrl(`/api/getclassesbybranchinexamination?branchID=${branchID}&empID=${empID}`),
        {
          method: "GET",
          headers: {
            Authorization: `Bearer ${token}`,
            Accept: "application/json"
          }
        }
      );
      
      const json = await response.json();
      
      const mapped = (json.data || json || []).map(item => ({
        classID: item.gradeID,
        sectionID: item.sectionID,
        sectionName: item.sectionName || '',
        gradeName: item.name || item.gradeName || '',
        className: `${item.name} - ${item.sectionName}`
      }));
      
      setAllClasses(mapped);
      
      if (preselected && preselected.length) {
        const normalized = preselected
          .map(pc => {
            const sid = pc?.sectionID ?? pc?.classID ?? pc;
            const match = mapped.find(m => String(m.sectionID) === String(sid));
            if (match) {
              return {
                ...match,
                id: pc?.id ?? 0,
                selectExam: pc?.selectExam
              };
            }
            return {
              classID: pc?.gradeID,
              sectionID: sid,
              sectionName: pc?.sectionName || '',
              gradeName: pc?.gradeName || '',
              className: pc?.className || `${pc?.gradeName || ''} - ${pc?.sectionName || ''}`,
              id: pc?.id ?? 0,
              selectExam: pc?.selectExam
            };
          })
          .filter(Boolean);
        
        setCls(normalized);
      } else {
        setCls([]);
      }
    } catch (error) {
      console.log("Could not load classes", error);
    }
  }
  
  const removeCls = (c) =>
    setCls(arr => arr.filter(x => String(x.sectionID) !== String(c.sectionID)));
  
  const toggleCls = (c) =>
    setCls(arr =>
      arr.some(x => String(x.sectionID) === String(c.sectionID))
        ? arr.filter(x => String(x.sectionID) !== String(c.sectionID))
        : [...arr, c]
    );
  
  const submit = async () => {
    if (!name.trim()) {
      toast('Enter exam name', 'warning');
      return;
    }
    if (!classes.length) {
      toast('Select classes', 'warning');
      return;
    }

    /* Session-date guard: exam ki start/end date current session ki UTC window ke
       andar honi chahiye — bahar ho to toaster (session range ke saath) + block. */
    const fromChk = validateSessionDateFromStorage(from, 'exam start date');
    if (!fromChk.ok) { toast(fromChk.message, 'error'); return; }
    const toChk = validateSessionDateFromStorage(to, 'exam end date');
    if (!toChk.ok) { toast(toChk.message, 'error'); return; }

    const branchID = sessionStorage.getItem('branchID');
    const token = sessionStorage.getItem('token');
    const currentClassIds = new Set(classes.map(c => String(c.sectionID)));
    
    // Determine which classes were removed
    const removedClassIds = [];
    if (isEdit && originalClassIds.size > 0) {
      for (const oldId of originalClassIds) {
        if (!currentClassIds.has(oldId)) {
          removedClassIds.push(oldId);
        }
      }
    }
    
    // Delete removed classes
    if (removedClassIds.length > 0) {
      try {
        const deletePromises = removedClassIds.map(async (sectionId) => {
          // Find the original class object to get its ID
          const removedClass = data.classes?.find(c => String(c.sectionID) === sectionId);
          if (removedClass && removedClass.id) {
            const deleteUrl = buildUrl(`/api/deletesingleaddexam?id=${removedClass.id}`);
            const response = await fetch(deleteUrl, {
              method: "DELETE",
              headers: {
                Authorization: `Bearer ${token}`,
                Accept: "*/*"
              }
            });
            return response.json();
          }
          return null;
        });
        
        await Promise.all(deletePromises);
        console.log(`Deleted ${removedClassIds.length} class(es)`);
      } catch (error) {
        console.log("Error deleting classes:", error);
      }
    }
    
    // Prepare payloads for insert and update
    const insertPayloads = [];
    const updatePayloads = [];
    
    for (const c of classes) {
      const existingClass = data?.classes?.find(
        existing => String(existing.sectionID) === String(c.sectionID)
      );
      
      const payload = {
        action: existingClass && existingClass.id ? "update" : "insert",
        id: existingClass?.id || 0,
        branchID: Number(branchID),
        classID: String(c.classID),
        sectionID: String(c.sectionID),
        sectionName: '',
        gradeName: '',
        examName: name.trim(),
        selectExam: String(data?.selectExam || c.selectExam || '0'),
        termID: String(selectedTermId),
        termName: '',
        dateFrom: from ? new Date(from).toISOString() : '',
        dateTo: to ? new Date(to).toISOString() : '',
        createdOn: new Date().toISOString()
      };
      
      if (existingClass && existingClass.id) {
        updatePayloads.push(payload);
      } else {
        insertPayloads.push(payload);
      }
    }
    
    // Combine all payloads
    const allPayloads = [...insertPayloads, ...updatePayloads];
    
    if (allPayloads.length === 0) {
      toast('No changes to save', 'info');
      onClose();
      return;
    }
    
    // Call onSave with all payloads
    onSave({ 
      payloads: allPayloads, 
      name: name.trim(), 
      from, 
      to, 
      classes: [...classes],
      deletedCount: removedClassIds.length
    });
  };
  
  if (!data) return null;
  
  const dropOptions = allClasses.filter(c =>
    !search ||
    c.className.toLowerCase().includes(search.toLowerCase())
  );
  
  return (
    <div className="exam-modal-overlay open" onClick={e => { if (e.target === e.currentTarget) onClose(); }}>
      <div className="exam-modal">
        <div className="exam-modal-header">
          <div className="exam-modal-header-left">
            <div className="exam-modal-header-icon"><i className={`fa-solid ${isEdit ? 'fa-pen-to-square' : 'fa-plus'}`}></i></div>
            <div>
              <div className="exam-modal-title">{isEdit ? 'Edit Exam' : 'Add Exam'}</div>
              <div className="exam-modal-sub">
                {isEdit ? 'Update exam details' : 'Create a new examination for selected classes'}
              </div>
            </div>
          </div>
          <Tooltip text="Close"><button className="exam-modal-close" onClick={onClose} aria-label="Close"><i className="fa-solid fa-xmark"></i></button></Tooltip>
        </div>
        
        <div className="exam-modal-body">
          <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 16, marginBottom: 14 }}>
            <div className="form-group" style={{ marginBottom: 0, position: 'relative' }}>
              <label className="form-label">Select Classes <span className="req-star">*</span></label>
              <div className="exam-class-select-wrap" ref={wrapRef} onClick={() => { setDropOpen(true); inputRef.current?.focus(); }}>
                {classes.map(c => (
                  <span key={c.sectionID} className="exam-class-tag">
                    {c.className}
                    <button
                      className="exam-class-tag-x"
                      onClick={e => {
                        e.stopPropagation();
                        removeCls(c);
                      }}
                    >
                      ✕
                    </button>
                  </span>
                ))}
                <input
                  ref={inputRef}
                  className="exam-class-input"
                  type="text"
                  placeholder="Search classes..."
                  value={search}
                  onChange={e => { setSearch(e.target.value); setDropOpen(true); }}
                  autoComplete="off"
                />
              </div>
              <div className={`exam-class-dropdown${dropOpen ? ' open' : ''}`}>
                {dropOptions.length === 0 ? (
                  <div className="exam-class-option" style={{ color: 'var(--text-muted)', cursor: 'default' }}>No matches</div>
                ) : (
                  dropOptions.map(c => (
                    <div
                      key={c.sectionID}
                      className={`exam-class-option${
                        classes.some(x => String(x.sectionID) === String(c.sectionID)) ? ' selected' : ''
                      }`}
                      onMouseDown={e => {
                        e.preventDefault();
                        e.stopPropagation();
                        toggleCls(c);
                      }}
                    >
                      {c.className}
                    </div>
                  ))
                )}
              </div>
            </div>
            
            <div className="form-group" style={{ marginBottom: 0 }}>
              <label className="form-label">Exam Name <span className="req-star">*</span></label>
              <div className="exam-name-field">
                <i className="fa-solid fa-file-signature exam-field-icon"></i>
                <input className="form-input" type="text" placeholder="e.g. 1st Term Exam" value={name} onChange={e => setName(e.target.value)} autoComplete="off" />
              </div>
            </div>
          </div>
          
          <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 16 }}>
            <div className="form-group" style={{ marginBottom: 0 }}>
              <label className="form-label">Start Date</label>
              <div className="exam-date-field">
                <i className="fa-regular fa-calendar exam-field-icon"></i>
                <input
                  className="form-input"
                  type="date"
                  value={from}
                  onChange={e => {
                    const v = e.target.value;
                    setFrom(v);
                    // Agar end date ab start date se pehle ho gayi to use clear karo
                    if (to && v && to < v) setTo('');
                  }}
                />
              </div>
            </div>
            <div className="form-group" style={{ marginBottom: 0 }}>
              <label className="form-label">End Date</label>
              <div className="exam-date-field">
                <i className="fa-regular fa-calendar-check exam-field-icon"></i>
                {/* End date kam se kam start date ya us se aage ho (start se pehle nahi) */}
                <input
                  className="form-input"
                  type="date"
                  value={to}
                  min={from || undefined}
                  onChange={e => setTo(e.target.value)}
                />
              </div>
            </div>
          </div>
        </div>
        
        <div className="exam-modal-footer">
          <Tooltip text="Cancel and close">
            <button className="exam-cancel-btn" onClick={onClose}>
              <i className="fa-solid fa-xmark"></i> Cancel
            </button>
          </Tooltip>
          <Tooltip text={isEdit ? 'Save exam' : 'Submit new exam'}>
            <button className="exam-submit-btn" onClick={submit}>
              <i className="fa-solid fa-check"></i> {isEdit ? 'Save' : 'Submit'}
            </button>
          </Tooltip>
        </div>
      </div>
    </div>
  );
}
/* ═══════════════════════════════════════════════════════════════════
   REPORT STYLE PICKER — opens new tab with the chosen-style PDF
   ═══════════════════════════════════════════════════════════════════ */
function ExamReportPicker({ req, exams, term, branchSchool, onClose }) {
  const isAll  = req.scope === 'all';
  const target = isAll ? null : exams.find(e => e.id === req.scope);
  const name   = isAll ? `${term} Term — All Exams` : (target?.name || 'Exam Report');

  // Format default us button se aata hai jisse picker khula (PDF ya Word).
  return (
    <StandardReportPicker
      open
      title={name}
      formats={['pdf', 'word', 'excel']}
      defaultFormat={req?.format || 'pdf'}
      onClose={onClose}
      onGenerate={(style, format) => {
        // PDF / Word / Excel — generate function format ke hisaab se handle karta hai.
        generateExamReport({ req, exams, term, target, branchSchool }, style === 'color', format);
        onClose();
      }}
    />
  );
}

/* ═══════════════════════════════════════════════════════════════════
   DATE SHEET — EDIT MODAL (subjects entry rows)
   ═══════════════════════════════════════════════════════════════════ */
function DsEditModal({ ctx, onClose, onSave, toast }) {
  const [rows, setRows] = useState(ctx.rows);
  const [pendingRemoveIdx, setPendingRemoveIdx] = useState(null);

  const updateRow = (idx, key, val) => setRows(rs => rs.map((r, i) => i === idx ? { ...r, [key]: val } : r));
  const addRow = () => setRows(rs => [...rs, { subject: '', date: '', timeFrom: '', timeTo: '' }]);
  const requestRemove = idx => setPendingRemoveIdx(idx);
const confirmRemove = async () => {
  if (pendingRemoveIdx == null) return;

  const row = rows[pendingRemoveIdx];

  try {
    const token = sessionStorage.getItem('token');
    const branchID = sessionStorage.getItem('branchID');

    const requestPayload = {
      id: row.id,
      branchID: Number(branchID),
      classID: Number(ctx.classID),
      sectionID: Number(ctx.sectionID),
      examID: Number(ctx.examId),
      termID: ctx.termID,
          subjectName: row.subject,      // ← Add subject name
      date: row.date,                // ← Add date
      timeFrom: row.timeFrom,        // ← Add timeFrom
      timeTo: row.timeTo,
      action: "delete"
    };

    const res = await fetch(buildUrl('/api/datesheetcrud'), {
      method: 'POST',   // (if backend supports DELETE, better; otherwise POST is fine)
      headers: {
        Authorization: `Bearer ${sessionStorage.getItem('token')}`,
        'Content-Type': 'application/json',
        Accept: 'application/json'
      },
      body: JSON.stringify(requestPayload)
    });

    const data = await res.json();

    if (!res.ok) {
      toast('Failed to delete subject', 'error');
      return;
    }

    // UI se remove only after success
    setRows(rs => rs.filter((_, i) => i !== pendingRemoveIdx));
    setPendingRemoveIdx(null);

    toast('Subject deleted successfully', 'success');

  } catch (err) {
    console.error(err);
    toast('Error deleting subject', 'error');
  }
};
const save = () => {
  const payload = {
    ...ctx,
    rows: rows.map(r => ({
      id: r.id || 0,  // ← Add this line to preserve the ID
      subject: (r.subject || '').trim(),
      date: r.date || '',
      timeFrom: r.timeFrom || '',
      timeTo: r.timeTo || '',
    })),
  };
  onSave(payload);
};
  return (
    <div className="exam-modal-overlay open" onClick={e => { if (e.target === e.currentTarget) onClose(); }}>
      <div className="exam-modal ds-edit-modal">
        <div className="exam-modal-header">
          <div className="exam-modal-header-left">
            <div className="exam-modal-header-icon"><i className="fa-solid fa-calendar-days"></i></div>
            <div>
              <div className="exam-modal-title">Edit Date Sheet</div>
              <div className="exam-modal-sub">{ctx.className} — {rows.length} subject{rows.length !== 1 ? 's' : ''}</div>
            </div>
          </div>
          <Tooltip text="Close"><button className="exam-modal-close" onClick={onClose} aria-label="Close"><i className="fa-solid fa-xmark"></i></button></Tooltip>
        </div>

        <div className="exam-modal-body ds-edit-body">
          {rows.length === 0 && (
            <div className="ds-edit-empty">
              <i className="fa-regular fa-calendar-plus"></i>
              <div>No subjects added yet.</div>
              <div className="ds-edit-empty-sub">Click <strong>Add Subject</strong> to start building the date sheet.</div>
            </div>
          )}

          {rows.map((r, idx) => (
            <div key={idx} className="ds-edit-card">
              <div className="ds-edit-card-head">
                <div className="ds-edit-num">{idx + 1}</div>
                <div className="ds-edit-card-title">
                  {r.subject?.trim() || <span style={{ color: 'var(--text-muted)', fontWeight: 500 }}>New subject</span>}
                </div>
                <Tooltip text="Remove subject"><button className="ds-edit-card-remove" onClick={() => requestRemove(idx)}>
                  <i className="fa-solid fa-trash"></i>
                </button></Tooltip>
              </div>

              <div className="ds-edit-fields">
                <div className="ds-edit-field ds-edit-field-wide">
                  <label>Subject</label>
                  {/* Sirf dropdown se subject pick — manual typing/edit nahi. */}
                  <select
                    className="ds-edit-input"
                    value={r.subject}
                    onChange={e => updateRow(idx, 'subject', e.target.value)}
                  >
                    <option value="">Select subject…</option>
                    {(() => {
                      const opts = (ctx.subjects || []).map(s => s.subjectName || s).filter(Boolean);
                      // Agar pehle se saved subject list mein nahi to use bhi option banao (warna blank dikhe).
                      if (r.subject && !opts.includes(r.subject)) opts.unshift(r.subject);
                      return [...new Set(opts)].map(name => <option key={name} value={name}>{name}</option>);
                    })()}
                  </select>
                </div>
                <div className="ds-edit-field">
                  <label>Date</label>
                  <input className="ds-edit-input" type="date" value={r.date} onChange={e => updateRow(idx, 'date', e.target.value)} />
                </div>
                <div className="ds-edit-field">
                  <label>Time From</label>
                  <input className="ds-edit-input" type="time" value={dsTimeToInput(r.timeFrom)} onChange={e => updateRow(idx, 'timeFrom', dsTimeFromInput(e.target.value))} />
                </div>
                <div className="ds-edit-field">
                  <label>Time To</label>
                  <input className="ds-edit-input" type="time" value={dsTimeToInput(r.timeTo)} onChange={e => updateRow(idx, 'timeTo', dsTimeFromInput(e.target.value))} />
                </div>
              </div>
            </div>
          ))}

          <button className="ds-edit-add" onClick={addRow}>
            <i className="fa-solid fa-plus"></i> Add Subject
          </button>
        </div>

        <div className="exam-modal-footer">
          <Tooltip text="Cancel and close"><button className="exam-cancel-btn" onClick={onClose}><i className="fa-solid fa-xmark"></i> Cancel</button></Tooltip>
          <Tooltip text="Save Date Sheet"><button className="exam-submit-btn" onClick={save}><i className="fa-solid fa-check"></i> Save Date Sheet</button></Tooltip>
        </div>
      </div>

      {/* nested remove-row confirm (Academics-style) */}
      {pendingRemoveIdx != null && (
        <div className="confirm-overlay open" onClick={e => { if (e.target === e.currentTarget) setPendingRemoveIdx(null); }}>
          <div className="confirm-dialog">
            <div className="confirm-glow" style={{ background: 'linear-gradient(90deg,#EF4444,#DC2626,#EF4444)' }} />
            <div className="confirm-hero">
              <div className="confirm-ring">
                <div className="confirm-icon-wrap" style={{ background: 'rgba(220,38,38,.1)', color: '#DC2626' }}>
                  <i className="fa-solid fa-xmark"></i>
                </div>
              </div>
            </div>
            <div className="confirm-body">
              <div className="confirm-title">Remove Subject</div>
              <div
                className="confirm-msg"
                dangerouslySetInnerHTML={{
                  __html: rows[pendingRemoveIdx]?.subject?.trim()
                    ? `Are you sure you want to remove <strong>${rows[pendingRemoveIdx].subject.trim()}</strong> from the date sheet?`
                    : 'Are you sure you want to remove this subject row?',
                }}
              />
              <div className="confirm-hint">
                <i className="fa-solid fa-triangle-exclamation"></i>
                <span>This subject will be deleted from the date sheet.</span>
              </div>
            </div>
            <div className="confirm-footer">
              <Tooltip text="Cancel and close"><button className="confirm-btn confirm-btn--cancel" onClick={() => setPendingRemoveIdx(null)}>Cancel</button></Tooltip>
              <Tooltip text="Yes, Remove (confirm)"><button className="confirm-btn confirm-btn--confirm" onClick={confirmRemove}>Yes, Remove</button></Tooltip>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

/* ═══════════════════════════════════════════════════════════════════
   DATE SHEET — REPORT PICKER + BUILDER (A4 portrait)
   ═══════════════════════════════════════════════════════════════════ */
function DsReportPicker({ req, ex, dateSheets, term, branchSchool, onClose }) {
  if (!ex) return null;

  // Format default us button se aata hai jisse picker khula (PDF ya Word).
  return (
    <StandardReportPicker
      open
      title={req.name}
      formats={['pdf', 'word', 'excel']}
      defaultFormat={req?.format || 'pdf'}
      onClose={onClose}
      onGenerate={async (style, format) => {
        // PDF / Word / Excel — generate function ke andar format ke hisaab se handle hote hain.
        await generateDateSheetReport({ ex, dateSheets, term, classKey: req.classKey, branchSchool }, style === 'color', format);
        onClose();
      }}
    />
  );
}

async function generateDateSheetReport({ ex, dateSheets, term, classKey, branchSchool }, isColor, format = 'pdf') {
  const isAll = classKey === 'all';

 let w = null;
if (format === 'pdf') {
  w = window.open('', '_blank', 'width=960,height=820');
  if (!w) return;
  w.document.write('<p style="font-family:sans-serif;padding:24px;color:#475569">Preparing report…</p>');
}

  /* Real branch header (name / academic year) from the /report-header/{branchId}
     API (saved in branchSchool) — rendered by the shared report-kit header. */
  const bs         = branchSchool || {};
  const dsEsc = s => String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
  const dsFmtDate = dsFmtDateDisplay;

  // Target classes: 'all' → saari; warna classKey (cls_examId_sectionID_i) ki sectionID wali class.
  const keyParts = String(classKey).split('_');
  const sectionIdFromKey = keyParts[keyParts.length - 2];
  const targetClasses = isAll
    ? (ex.classes || [])
    : (ex.classes || []).filter(c => String(c.sectionID) === String(sectionIdFromKey));

  // Har class ka datesheet seedha API se fetch karo (dateSheets state/key mismatch se bachne ke liye).
  const fetchDs = async (cls) => {
    try {
      const branchID = sessionStorage.getItem('branchID');
      const empID    = sessionStorage.getItem('employee_ID');
      const token    = sessionStorage.getItem('token');
      const params = new URLSearchParams({
        branchID: String(branchID), classID: String(cls.classID), termID: String(ex.termID ?? ''),
        ExamID: String(ex.selectExam ?? ex.id), sectionID: String(cls.sectionID), empID: String(empID),
      });
      const r = await fetch(buildUrl(`/api/getdatesheetbybranchclassidtermid?${params.toString()}`),
        { headers: { Authorization: `Bearer ${token}`, Accept: 'application/json' } });
      const data = await r.json();
      // const rows = Array.isArray(data) ? data : (data?.data || []);
      // return rows.map(dsMapApiRow);
    const rows = Array.isArray(data) ? data : (data?.data || []);

      return rows
        .map(dsMapApiRow)
        .sort((a, b) => {
          if (!a.date) return 1;
          if (!b.date) return -1;
          const dCmp = new Date(a.date) - new Date(b.date);
          if (dCmp !== 0) return dCmp;
          return dsTimeToMinutes(a.timeFrom) - dsTimeToMinutes(b.timeFrom);
        });
    } catch (e) {
      console.error('Date sheet fetch failed', e);
      return [];
    }
  };
    const blocks = await Promise.all((targetClasses || []).map(async cls => ({ cls, rows: await fetchDs(cls) })));

  /* Two coordinated palettes:
     • Colorful: brand blue header, blue-tinted accent rows.
     • Colorless: dedicated LOW-INK layout — white header, light gray
       borders, NO row striping (rowEv = white), no colored accent.
     The header/footer chrome itself comes from the shared report kit. */
  const aColor = isColor ? '#1E40AF' : '#374151';
  const aBg    = isColor ? '#EFF6FF' : '#FFFFFF';
  const aBdr   = isColor ? '#BFDBFE' : '#D1D5DB';
  const tMuted = isColor ? '#64748B' : '#4B5563';
  const rowEv  = isColor ? '#F8FAFF' : '#FFFFFF';

  const classBlocks = blocks.map(({ cls, rows }) => {
    if (!cls) return '';
    const rowsHtml = rows.length
      ? rows.map((s, si) => `
        <tr style="background:${si % 2 === 0 ? '#fff' : rowEv}">
          <td style="padding:8px 12px;font-size:11.5px;font-weight:700;color:#0F172A;border-bottom:1px solid ${aBdr}">${si + 1}</td>
          <td style="padding:8px 12px;font-size:11.5px;font-weight:700;color:#0F172A;border-bottom:1px solid ${aBdr}">${dsEsc(s.subject)}</td>
          <td style="padding:8px 12px;font-size:11.5px;color:${tMuted};white-space:nowrap;border-bottom:1px solid ${aBdr}">${dsFmtDate(s.date)}</td>
          <td style="padding:8px 12px;font-size:11.5px;color:${tMuted};white-space:nowrap;border-bottom:1px solid ${aBdr}">${dsEsc(s.timeFrom) || '—'}</td>
          <td style="padding:8px 12px;font-size:11.5px;color:${tMuted};white-space:nowrap;border-bottom:1px solid ${aBdr}">${dsEsc(s.timeTo) || '—'}</td>
        </tr>`).join('')
      : `<tr><td colspan="5" style="padding:12px;font-size:12px;color:${tMuted};text-align:center">No subjects added</td></tr>`;

    return `
      <div style="margin-bottom:20px;page-break-inside:avoid">
        <div style="display:flex;align-items:center;gap:8px;margin-bottom:7px">
          <div style="width:7px;height:7px;border-radius:50%;background:${aColor};flex-shrink:0"></div>
          <div style="font-size:13px;font-weight:800;color:#0F172A">${dsEsc(cls.className || `${cls.gradeName || ''}${cls.sectionName ? ' - ' + cls.sectionName : ''}`.trim())}</div>
        </div>
        <table style="width:100%;table-layout:fixed;border-collapse:collapse;border:1px solid ${aBdr}">
          <colgroup><col style="width:34px"><col><col style="width:108px"><col style="width:92px"><col style="width:92px"></colgroup>
          <thead>
            <tr style="background:${aBg}">
              <th style="padding:7px 10px;font-size:10px;font-weight:700;color:${aColor};text-align:left;text-transform:uppercase;letter-spacing:.5px;border-bottom:2px solid ${aBdr}">#</th>
              <th style="padding:7px 10px;font-size:10px;font-weight:700;color:${aColor};text-align:left;text-transform:uppercase;letter-spacing:.5px;border-bottom:2px solid ${aBdr}">Subject</th>
              <th style="padding:7px 10px;font-size:10px;font-weight:700;color:${aColor};text-align:left;text-transform:uppercase;letter-spacing:.5px;white-space:nowrap;border-bottom:2px solid ${aBdr}">Date</th>
              <th style="padding:7px 10px;font-size:10px;font-weight:700;color:${aColor};text-align:left;text-transform:uppercase;letter-spacing:.5px;white-space:nowrap;border-bottom:2px solid ${aBdr}">Time From</th>
              <th style="padding:7px 10px;font-size:10px;font-weight:700;color:${aColor};text-align:left;text-transform:uppercase;letter-spacing:.5px;white-space:nowrap;border-bottom:2px solid ${aBdr}">Time To</th>
            </tr>
          </thead>
          <tbody>${rowsHtml}</tbody>
        </table>
      </div>`;
  }).join('');

  const bodyHtml = `${EXAM_KIT_TABLE_CSS}
    <div style="display:flex;flex-wrap:wrap;border:1px solid ${aBdr};border-radius:8px;margin-bottom:16px;overflow:hidden">
      ${[
        ['Term', term],
        ['Exam', ex.name],
        ['Classes', String(targetClasses.length)],
        ['Period', `${dsFmtDate(ex.from)} → ${dsFmtDate(ex.to)}`],
      ].map(([k, v]) => `
        <div style="flex:1;min-width:120px;padding:10px 16px;border-right:1px solid ${aBdr};overflow-wrap:anywhere">
          <div style="font-size:9px;font-weight:700;text-transform:uppercase;letter-spacing:.5px;color:${tMuted};margin-bottom:2px">${k}</div>
          <div style="font-size:12.5px;font-weight:800;color:${aColor}">${v}</div>
        </div>
      `).join('')}
    </div>
    ${classBlocks || '<div style="padding:24px;text-align:center;color:' + tMuted + '">No date sheets yet.</div>'}`;

  const html = buildStandardReportHtml({
    title: `Date Sheet — ${ex.name}`,
    format,
    isColor,
    bodyHtml,
    subtitleLine: examKitSub(bs, dsEsc(term), dsEsc(ex.name)),
    schoolName: examKitSchool(bs),
  });

  // PDF → print preview; Word → wahi preview "Save as Word" button ke saath (deliverReport); Excel → .xls.
  if (format === 'pdf') {
    w.document.open();
    w.document.write(html);
    w.document.close();
  } else {
    examDeliverReport(`Date Sheet - ${ex?.name || ''}`, format, html);
  }
}

/* ═══════════════════════════════════════════════════════════════════
   SYLLABUS — EDIT MODAL (subject tabs + rich-text editor)
   ═══════════════════════════════════════════════════════════════════ */
/* Self-contained rich-text editor for Syllabus — Lesson Plan editor jaisa
   full toolbar (undo/redo, size, bold/underline/italic/strike, color, align,
   lists, table, link, image, math, clear). Selection ko save/restore karta hai
   taake popup (link/image/math) focus churaye to bhi command sahi jagah lage. */
function SylRteEditor({ html, onChange, placeholder }) {
  const ref = useRef(null);
  const savedRange = useRef(null);
  const lastEmitted = useRef(null); // editor ne khud jo aakhri content bheja
  const [imgSel, setImgSel] = useState(null); // editor me select ki hui <img> (resize/align)
  const [, setImgTick] = useState(0);         // overlay ko img ke saath reposition karne ke liye

  // Image resize/align overlay — scroll/resize par reposition; bahar click/Escape par band.
  useEffect(() => {
    if (!imgSel) return undefined;
    const reposition = () => setImgTick(t => t + 1);
    const onDocDown = (e) => {
      if (e.target.closest && e.target.closest('.syl-img-overlay')) return;
      if (e.target.tagName === 'IMG') return;
      setImgSel(null);
    };
    const onKey = (e) => { if (e.key === 'Escape') setImgSel(null); };
    window.addEventListener('scroll', reposition, true);
    window.addEventListener('resize', reposition);
    document.addEventListener('mousedown', onDocDown, true);
    window.addEventListener('keydown', onKey);
    return () => {
      window.removeEventListener('scroll', reposition, true);
      window.removeEventListener('resize', reposition);
      document.removeEventListener('mousedown', onDocDown, true);
      window.removeEventListener('keydown', onKey);
    };
  }, [imgSel]);

  // Sirf EXTERNAL html change par overwrite karo (jaise subject switch / async load).
  // Apne hi emit (color/image/math/typing) par reset NA karo — warna content/cursor
  // disturb hota hai aur functionality "kaam nahi kar rahi" lagti hai.
  useEffect(() => {
    const el = ref.current;
    if (!el) return;
    if (html === lastEmitted.current) return;     // apna hi emit — skip
    if (document.activeElement === el) return;     // typing ke doran overwrite mat karo
    if (el.innerHTML !== (html || '')) {
      el.innerHTML = html || '';
    }
  }, [html]);

  const emit = () => {
    if (!ref.current) return;
    lastEmitted.current = ref.current.innerHTML;
    onChange(ref.current.innerHTML);
  };

  const saveSelection = () => {
    const sel = window.getSelection();
    if (!sel || !sel.rangeCount) return;
    const range = sel.getRangeAt(0);
    if (ref.current && ref.current.contains(range.commonAncestorContainer)) {
      // CLONE karo — warna live range popup focus par collapse ho kar start (1st row)
      // par chala jata hai, aur equation/link galat jagah insert hoti hai.
      savedRange.current = range.cloneRange();
    }
  };
  const restoreSelection = () => {
    const el = ref.current;
    if (!el) return false;
    // range ko focus() se PEHLE parho — warna el.focus() editor ka onFocus={saveSelection}
    // trigger karta hai jo savedRange ko galat (start/1st row) position se overwrite kar
    // deta hai, aur equation/insert galat jagah chala jata hai.
    const range = savedRange.current;
    el.focus();
    if (range) {
      const sel = window.getSelection();
      sel.removeAllRanges();
      sel.addRange(range);
    }
    return true;
  };
  const exec = (cmd, val) => {
    restoreSelection();
    document.execCommand(cmd, false, val !== undefined ? val : null);
    saveSelection();
    emit();
  };
  const execAlign = (cmd) => {
    if (!restoreSelection()) return;
    try { document.execCommand('styleWithCSS', false, true); } catch (err) {}
    document.execCommand(cmd, false, null);
    saveSelection();
    emit();
  };
  const insertHTMLCmd = (h) => {
    restoreSelection();
    document.execCommand('insertHTML', false, h);
    saveSelection();
    emit();
  };
  const insertTable = () => insertHTMLCmd(
    '<table style="border-collapse:collapse;width:100%;margin:8px 0"><tr><td style="border:1px solid #BFDBFE;padding:6px 10px">Col 1</td><td style="border:1px solid #BFDBFE;padding:6px 10px">Col 2</td></tr><tr><td style="border:1px solid #BFDBFE;padding:6px 10px">Row 2</td><td style="border:1px solid #BFDBFE;padding:6px 10px">Row 2</td></tr></table>'
  );
  const popupInput = (placeholderTxt, initial, onEnter) => {
    saveSelection();
    const inp = document.createElement('input');
    inp.type = 'text';
    inp.value = initial || '';
    inp.placeholder = placeholderTxt;
    inp.style.cssText = 'position:fixed;top:50%;left:50%;transform:translate(-50%,-50%);z-index:9999;padding:8px 12px;border:1px solid #CBD5E1;border-radius:8px;font-size:13px;width:320px;box-shadow:0 4px 20px rgba(0,0,0,.15)';
    document.body.appendChild(inp);
    inp.focus(); inp.select();
    inp.addEventListener('keydown', (e) => {
      if (e.key === 'Enter') { if (inp.value) onEnter(inp.value); inp.remove(); }
      if (e.key === 'Escape') inp.remove();
    });
    inp.addEventListener('blur', () => setTimeout(() => inp.remove(), 200));
  };
  const insertLink = () => popupInput('Enter URL', 'https://', (v) => exec('createLink', v));
  const insertMath = () => popupInput('e.g. x² + y² = z²', '', (v) =>
    insertHTMLCmd(`<span style="font-family:'Cambria Math',serif">${v}</span>`));
  const insertImage = () => {
    saveSelection();
    const f = document.createElement('input');
    f.type = 'file'; f.accept = 'image/*'; f.style.display = 'none';
    document.body.appendChild(f);
    f.addEventListener('change', () => {
      const file = f.files && f.files[0];
      if (file) {
        const reader = new FileReader();
        reader.onload = (ev) => exec('insertImage', ev.target.result);
        reader.readAsDataURL(file);
      }
      f.remove();
    });
    f.click();
  };

  // ── Image resize/align (Lesson Plan editor jaisa) ──
  // contentEditable Chrome me <img> ke resize handles nahi deta, is liye image click par
  // ek overlay dikhate hain: align (L/C/R) + size (± / 25/50/100%). Style img par lagti hai.
  const isEditorImg = (node) => node && node.tagName === 'IMG' && ref.current && ref.current.contains(node);
  const onEditorClick = (e) => {
    saveSelection();
    setImgSel(isEditorImg(e.target) ? e.target : null);
  };
  const alignImg = (mode) => {
    const img = imgSel; if (!img) return;
    if (mode === 'inline') { img.style.display = 'inline'; img.style.marginLeft = ''; img.style.marginRight = ''; }
    else {
      img.style.display = 'block';
      img.style.marginLeft  = (mode === 'center' || mode === 'right') ? 'auto' : '0';
      img.style.marginRight = (mode === 'center' || mode === 'left')  ? 'auto' : '0';
    }
    setImgTick(t => t + 1); emit();
  };
  const setImgWidth = (pct) => {
    const img = imgSel; if (!img) return;
    img.style.width = pct + '%'; img.style.height = 'auto'; img.style.maxWidth = '100%';
    setImgTick(t => t + 1); emit();
  };
  const nudgeImg = (deltaPx) => {
    const img = imgSel; if (!img) return;
    const cur = img.getBoundingClientRect().width || 0;
    img.style.width = Math.max(40, Math.round(cur + deltaPx)) + 'px';
    img.style.height = 'auto'; img.style.maxWidth = '100%';
    setImgTick(t => t + 1); emit();
  };
  const deleteImg = () => {
    const img = imgSel; if (!img) return;
    img.remove();          // image ko editor se hatao
    setImgSel(null);       // overlay band
    emit();                // content sync (image gayab)
  };

  return (
    <>
      <div className="syl-rte-toolbar">
        <Tooltip text="Undo"><button className="syl-tb-btn" onMouseDown={e => e.preventDefault()} onClick={() => exec('undo')}><i className="fa-solid fa-rotate-left"></i></button></Tooltip>
        <Tooltip text="Redo"><button className="syl-tb-btn" onMouseDown={e => e.preventDefault()} onClick={() => exec('redo')}><i className="fa-solid fa-rotate-right"></i></button></Tooltip>
        <div className="syl-tb-divider"></div>
        <Tooltip text="Font size"><select className="syl-tb-select" defaultValue="" onMouseDown={e => e.stopPropagation()} onChange={e => { exec('fontSize', e.target.value); e.target.value = ''; }}>
          <option value="">Size</option>
          <option value="1">Small</option>
          <option value="3">Normal</option>
          <option value="4">Large</option>
          <option value="5">X-Large</option>
        </select></Tooltip>
        <div className="syl-tb-divider"></div>
        <Tooltip text="Bold"><button className="syl-tb-btn" onMouseDown={e => e.preventDefault()} onClick={() => exec('bold')}><b>B</b></button></Tooltip>
        <Tooltip text="Underline"><button className="syl-tb-btn" onMouseDown={e => e.preventDefault()} onClick={() => exec('underline')}><u>U</u></button></Tooltip>
        <Tooltip text="Italic"><button className="syl-tb-btn" onMouseDown={e => e.preventDefault()} onClick={() => exec('italic')}><i>I</i></button></Tooltip>
        <Tooltip text="Strikethrough"><button className="syl-tb-btn" onMouseDown={e => e.preventDefault()} onClick={() => exec('strikeThrough')}><s>S</s></button></Tooltip>
        <Tooltip text="Text color">
          <label className="syl-tb-btn" onMouseDown={e => e.preventDefault()}
            style={{ fontSize: 11, fontWeight: 800, color: '#DC2626', textDecoration: 'underline', textDecorationColor: '#DC2626', cursor: 'pointer', position: 'relative' }}>
            A
            <input type="color" defaultValue="#DC2626"
              style={{ position: 'absolute', opacity: 0, width: '100%', height: '100%', top: 0, left: 0, cursor: 'pointer' }}
              onChange={e => exec('foreColor', e.target.value)} />
          </label>
        </Tooltip>
        <div className="syl-tb-divider"></div>
        <Tooltip text="Align left"><button className="syl-tb-btn" onMouseDown={e => e.preventDefault()} onClick={() => execAlign('justifyLeft')}><i className="fa-solid fa-align-left"></i></button></Tooltip>
        <Tooltip text="Align center"><button className="syl-tb-btn" onMouseDown={e => e.preventDefault()} onClick={() => execAlign('justifyCenter')}><i className="fa-solid fa-align-center"></i></button></Tooltip>
        <Tooltip text="Align right"><button className="syl-tb-btn" onMouseDown={e => e.preventDefault()} onClick={() => execAlign('justifyRight')}><i className="fa-solid fa-align-right"></i></button></Tooltip>
        <Tooltip text="Justify"><button className="syl-tb-btn" onMouseDown={e => e.preventDefault()} onClick={() => execAlign('justifyFull')}><i className="fa-solid fa-align-justify"></i></button></Tooltip>
        <div className="syl-tb-divider"></div>
        <Tooltip text="Numbered list"><button className="syl-tb-btn" onMouseDown={e => e.preventDefault()} onClick={() => exec('insertOrderedList')}><i className="fa-solid fa-list-ol"></i></button></Tooltip>
        <Tooltip text="Bullet list"><button className="syl-tb-btn" onMouseDown={e => e.preventDefault()} onClick={() => exec('insertUnorderedList')}><i className="fa-solid fa-list-ul"></i></button></Tooltip>
        <Tooltip text="Insert table"><button className="syl-tb-btn" onMouseDown={e => e.preventDefault()} onClick={insertTable}><i className="fa-solid fa-table-cells"></i></button></Tooltip>
        <div className="syl-tb-divider"></div>
        <Tooltip text="Insert link"><button className="syl-tb-btn" onMouseDown={e => e.preventDefault()} onClick={insertLink}><i className="fa-solid fa-link"></i></button></Tooltip>
        <Tooltip text="Insert image from your device"><button className="syl-tb-btn" onMouseDown={e => { e.preventDefault(); saveSelection(); }} onClick={insertImage}><i className="fa-regular fa-image"></i></button></Tooltip>
        <Tooltip text="Insert math formula"><button className="syl-tb-btn" onMouseDown={e => { e.preventDefault(); saveSelection(); }} style={{ fontWeight: 800, fontSize: 14 }} onClick={insertMath}>∑</button></Tooltip>
        <div className="syl-tb-divider"></div>
        <Tooltip text="Clear formatting"><button className="syl-tb-btn" onMouseDown={e => e.preventDefault()} onClick={() => exec('removeFormat')} style={{ fontSize: 11, color: 'var(--text-muted)', fontWeight: 700 }}>Clear</button></Tooltip>
      </div>
      <div
        ref={ref}
        className="syl-rte-editor"
        contentEditable
        suppressContentEditableWarning
        data-placeholder={placeholder}
        dir="ltr"
        onInput={emit}
        onClick={onEditorClick}
        onMouseUp={saveSelection}
        onKeyUp={saveSelection}
        onFocus={saveSelection}
      />
      {/* Image resize/align overlay — selected image ke upar toolbar.
          Portal to body — warna modal ke transform (fadeSlide) se position:fixed toot
          jata hai aur overlay image se bahar aa jata hai. */}
      {imgSel && createPortal((() => {
        const r = imgSel.getBoundingClientRect();
        const tbBtn = { border: 'none', background: 'transparent', color: '#E2E8F0', cursor: 'pointer', fontSize: 12, padding: '3px 6px', borderRadius: 5, fontFamily: 'inherit', lineHeight: 1 };
        return (
          <div className="syl-img-overlay" style={{ position: 'fixed', top: r.top, left: r.left, width: r.width, height: r.height, border: '2px solid #1E40AF', boxSizing: 'border-box', zIndex: 100000, pointerEvents: 'none' }}>
            <div style={{ position: 'absolute', top: -36, left: 0, display: 'flex', alignItems: 'center', gap: 2, background: '#1E293B', borderRadius: 8, padding: '3px 5px', pointerEvents: 'auto', boxShadow: '0 4px 14px rgba(0,0,0,.3)', whiteSpace: 'nowrap' }} onMouseDown={e => e.preventDefault()}>
              <Tooltip text="Align left"><button style={tbBtn} onClick={() => alignImg('left')}><i className="fa-solid fa-align-left"></i></button></Tooltip>
              <Tooltip text="Center"><button style={tbBtn} onClick={() => alignImg('center')}><i className="fa-solid fa-align-center"></i></button></Tooltip>
              <Tooltip text="Align right"><button style={tbBtn} onClick={() => alignImg('right')}><i className="fa-solid fa-align-right"></i></button></Tooltip>
              <span style={{ width: 1, height: 16, background: '#475569', margin: '0 3px' }}></span>
              <Tooltip text="Smaller"><button style={tbBtn} onClick={() => nudgeImg(-30)}><i className="fa-solid fa-minus"></i></button></Tooltip>
              <Tooltip text="Bigger"><button style={tbBtn} onClick={() => nudgeImg(30)}><i className="fa-solid fa-plus"></i></button></Tooltip>
              <span style={{ width: 1, height: 16, background: '#475569', margin: '0 3px' }}></span>
              <Tooltip text="25%"><button style={tbBtn} onClick={() => setImgWidth(25)}>25%</button></Tooltip>
              <Tooltip text="50%"><button style={tbBtn} onClick={() => setImgWidth(50)}>50%</button></Tooltip>
              <Tooltip text="100%"><button style={tbBtn} onClick={() => setImgWidth(100)}>100%</button></Tooltip>
              <span style={{ width: 1, height: 16, background: '#475569', margin: '0 3px' }}></span>
              <Tooltip text="Remove image"><button style={{ ...tbBtn, color: '#F87171' }} onClick={deleteImg}><i className="fa-solid fa-trash-can"></i></button></Tooltip>
              <Tooltip text="Done"><button style={tbBtn} onClick={() => setImgSel(null)}><i className="fa-solid fa-xmark"></i></button></Tooltip>
            </div>
          </div>
        );
      })(), document.body)}
    </>
  );
}

function SylEditModal({ ctx, onClose, onSave, onContentSaved, toast, subjects: externalSubjects = [], examId, term, fetchSubjectSyllabus }) {
const [localSubjects, setLocalSubjects] = useState(() => {
    if (externalSubjects && externalSubjects.length) {
      return externalSubjects.map(s => ({
        subjectID: s.subjectID,                      // ← explicitly preserve
        subjectName: s.subjectName || s.subject,
        subject: s.subjectName || s.subject,
        content: s.content || '',
        updatedAt: s.updatedAt || '—',
      }));
    }
    return [];
  });

  const [activeIdx, setActiveIdx] = useState(0);

  const loadSubjectSyllabus = async (subjectObj, idx) => {
  if (!fetchSubjectSyllabus || !subjectObj) return;

  const data = await fetchSubjectSyllabus(
    ctx.classID,
    ctx.sectionID,
    subjectObj.subjectID,
    examId,
    term
  );

  if (data && data.length) {
    const incoming = data[0];

    setLocalSubjects(ss =>
      ss.map((s, i) =>
        i === idx
          ? {
              ...s,
              id: incoming.id,
              syllabusID: incoming.syllabusID,
              content: incoming.subjectDetails || '',
              updatedAt: incoming.updatedAt || s.updatedAt
            }
          : s
      )
    );
  }
};
  const saveSubject = async (goNext = false) => {
  if (!cur) return;

  const plainText = (cur.content || '').replace(/<[^>]+>/g, '').trim();

  if (!plainText) {
    toast('Please add content first.', 'warning');
    return;
  }

  try {
    const token = sessionStorage.getItem('token');
    const branchID = sessionStorage.getItem('branchID');
const isUpdate = cur?.id > 0;

const payload = {
  id: isUpdate ? cur.id : 0,
  syllabusID: cur?.syllabusID || 0,
  imagePath: "string",
  examID: examId,
  branchID: branchID,
  classID: String(ctx.classID),
  className:  "",
  sectionID: ctx.sectionID,
  sectionName: ctx.sectionName || "",
  terms: String(term),
  termName: "",
  subjectName: String(cur.subjectID),
  subjectDisplayName: cur.subjectName,
  subjectDetails: cur.content,
  action: isUpdate ? "update" : "insert",
  imagePaths: ["string"]
};
    const response = await fetch(
      buildUrl('/api/examsyllabuscrud'),
      {
        method: "POST",
        headers: {
          Authorization: `Bearer ${token}`,
          "Content-Type": "application/json",
          Accept: "application/json"
        },
        body: JSON.stringify(payload)
      }
    );

    const data = await response.json();

    if (!response.ok) {
      throw new Error(data.message || 'Failed to save syllabus');
    }

    const unpublished = typeof onContentSaved === 'function' ? !!(await onContentSaved()) : false;

    if (goNext) {
      toast(unpublished
        ? 'Syllabus saved. It is unpublished — publish again to show the changes.'
        : 'Syllabus saved successfully.', 'success');
      const next = (activeIdx + 1) % localSubjects.length;
      setActiveIdx(next);

      if (localSubjects[next]) {
        loadSubjectSyllabus(localSubjects[next]);
      }
    } else {
      onSave(localSubjects);
    }
  } catch (err) {
    console.error(err);
    toast(err.message || 'Failed to save syllabus', 'error');
  }
};

useEffect(() => {
  if (localSubjects.length) {
    loadSubjectSyllabus(localSubjects[0], 0);
  }
  // eslint-disable-next-line react-hooks/exhaustive-deps
}, [localSubjects.length]);
  // Second useEffect — externalSubjects merge, subjectID explicitly preserve karo
  useEffect(() => {
    if (externalSubjects && externalSubjects.length) {
      const existingContent = {};
      if (ctx.subjects && ctx.subjects.length) {
        ctx.subjects.forEach(s => {
          existingContent[s.subjectName || s.subject] = { content: s.content, updatedAt: s.updatedAt };
        });
      }

      const merged = externalSubjects.map(s => ({
        subjectID: s.subjectID,                      // ← explicitly preserve
        subjectName: s.subjectName || s.subject,
        subject: s.subjectName || s.subject,
        content: existingContent[s.subjectName]?.content || s.content || '',
        updatedAt: existingContent[s.subjectName]?.updatedAt || s.updatedAt || '—',
      }));
      setLocalSubjects(merged);
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [externalSubjects, ctx.subjects]);
  const cur = localSubjects[activeIdx] || null;
  const plainLen = (cur?.content || '').replace(/<[^>]+>/g, '').length;

  const updateContent = htmlVal => {
    setLocalSubjects(ss => ss.map((s, i) => i === activeIdx ? { ...s, content: htmlVal } : s));
  };

const saveAndNext = () => {
  saveSubject(true);
};
const save = () => {
  saveSubject(false);
};
  return (
    <div className="exam-modal-overlay open" onClick={e => { if (e.target === e.currentTarget) onClose(); }}>
      <div className="exam-modal syl-edit-modal" style={{ maxWidth: 860 }}>
        <div className="exam-modal-header">
          <div className="exam-modal-header-left">
            <div className="exam-modal-header-icon"><i className="fa-solid fa-book-open"></i></div>
            <div>
              <div className="exam-modal-title">Edit Syllabus</div>
              <div className="exam-modal-sub">{ctx.className} — {localSubjects.length} subject{localSubjects.length !== 1 ? 's' : ''}</div>
            </div>
          </div>
          <Tooltip text="Close"><button className="exam-modal-close" onClick={onClose} aria-label="Close"><i className="fa-solid fa-xmark"></i></button></Tooltip>
        </div>

        <div className="exam-modal-body" style={{ paddingTop: 18 }}>
          {/* Subject tabs */}
          <div className="syl-subj-tabs">
         {localSubjects.map((s, i) => (
  <button
    key={s.subjectID || i}
    className={`syl-subj-tab${i === activeIdx ? ' active' : ''}`}
    onClick={() => {
        console.log('clicked subject:', s);   // subjectID dikh raha hai ya nahi

      setActiveIdx(i);
      loadSubjectSyllabus(s, i);
    }}
  >
    {s.subjectName}
  </button>
))}
          </div>

          {cur && (
            <div>
              <div style={{ marginBottom: 10 }}>
                <div style={{ fontSize: 12, fontWeight: 700 }}>
                  {cur.subjectName} — Syllabus Content
                </div>
                <div style={{ fontSize: 11, color: 'var(--text-muted)', marginTop: 2 }}>Status is auto-calculated based on content.</div>
              </div>

              <div className="syl-rte-wrap">
                <SylRteEditor
                  key={`${activeIdx}-${cur?.id}`}   // ✅ stable key
                  html={cur?.content || ''}
                  onChange={updateContent}
                  placeholder="Enter syllabus content here..."
                />
                <div className="syl-rte-char-count">Characters: {plainLen}</div>
              </div>
            </div>
          )}
        </div>

        <div className="exam-modal-footer">
          <Tooltip text="Discard changes and close">
            <button className="exam-cancel-btn" onClick={onClose}>
              <i className="fa-solid fa-xmark"></i> Close
            </button>
          </Tooltip>
          <Tooltip text="Save and move to the next class">
           <button
  className="exam-cancel-btn"
  style={{ borderColor: '#1E40AF', color: '#1E40AF' }}
  onClick={saveAndNext}
>
  <i className="fa-solid fa-arrow-right"></i>
  Save & Next
</button>

          </Tooltip>
          <Tooltip text="Save and close">

<button
  className="exam-submit-btn"
  onClick={save}
>
  <i className="fa-solid fa-check"></i>
  Save & Close
</button>
          </Tooltip>
        </div>
      </div>
    </div>
  );
}


/* ═══════════════════════════════════════════════════════════════════
   SYLLABUS — REPORT PICKER + BUILDER (A4 portrait)
   ═══════════════════════════════════════════════════════════════════ */
function SylReportPicker({ req, ex, syllabusData, term, branchSchool, onClose }) {
  if (!ex) return null;

  // Format default us button se aata hai jisse picker khula (PDF ya Word).
  return (
    <StandardReportPicker
      open
      title={req.name}
      formats={['pdf', 'word', 'excel']}
      defaultFormat={req?.format || 'pdf'}
      onClose={onClose}
      onGenerate={async (style, format) => {
        // PDF / Word / Excel — generate function format ke hisaab se handle karta hai.
        await generateSyllabusReport({ ex, syllabusData, term, classKey: req.classKey, branchSchool }, style === 'color', format);
        onClose();
      }}
    />
  );
}

async function generateSyllabusReport({ ex, syllabusData, term, classKey, branchSchool }, isColor, format = 'pdf') {
  const isAll = classKey === 'all';

  // Window pehle kholo (popup-blocker se bachne ke liye), phir data fetch — PDF aur Word dono ke liye.
  // Excel seedha file download hota hai, us ke liye window nahi.
  const w = format === 'excel' ? null : window.open('', '_blank', 'width=960,height=820');
  if (format !== 'excel') {
    if (!w) return;
    w.document.write('<p style="font-family:sans-serif;padding:24px;color:#475569">Preparing report…</p>');
  }

  /* Real branch header (name / academic year) from /report-header (branchSchool) — shared report-kit header. */
  const bs         = branchSchool || {};
  const sEsc = s => String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');

  // Target classes: 'all' → saari; warna classKey (scls_examId_sectionID_i) ki sectionID wali class.
  const keyParts = String(classKey).split('_');
  const sectionIdFromKey = keyParts[keyParts.length - 2];
  const targetClasses = isAll
    ? (ex.classes || [])
    : (ex.classes || []).filter(c => String(c.sectionID) === String(sectionIdFromKey));

  // API response se asal term name yahan capture hoga (report header/meta ke liye).
  let resolvedTermName = '';
  // Har class ka syllabus seedha API se fetch (syllabusData state/key mismatch se bachne ke liye).
  const fetchSyl = async (cls) => {
    try {
      const branchID = sessionStorage.getItem('branchID');
      const empID    = sessionStorage.getItem('employee_ID');
      const token    = sessionStorage.getItem('token');
      const params = new URLSearchParams({
        branchID: String(branchID), classID: String(cls.classID), Terms: String(ex.termID ?? ''),
        ExamID: String(ex.selectExam ?? ex.id), sectionID: String(cls.sectionID), pageNo: '1', empID: String(empID),
      });
      const r = await fetch(buildUrl(`/api/getexamsyllabusbybranchclassandterms?${params.toString()}`),
        { headers: { Authorization: `Bearer ${token}`, Accept: 'application/json' } });
      const data = await r.json();
      const rows = data?.data || data?.result || (Array.isArray(data) ? data : []);
      // Asal term name API se le lo (e.g. "term 1") — UI ke sylTerm ki jagah.
      if (!resolvedTermName && rows[0]?.termName) resolvedTermName = rows[0].termName;
      // API har subject ko duplicate de rahi hai → subject (id) par dedupe, har subject ek hi baar.
      const seen = new Set();
      return rows.reduce((acc, it) => {
        const key = String(it.subjectName ?? it.subjectID ?? it.subjectDisplayName ?? '');
        if (seen.has(key)) return acc;
        seen.add(key);
        acc.push({
          subject: it.subjectDisplayName || it.subjectName || '',
          content: it.subjectDetails || '',
          updatedAt: it.updatedAt || it.UpdatedOn || '—',
        });
        return acc;
      }, []);
    } catch (e) { console.error('Syllabus fetch failed', e); return []; }
  };
  const blocks = await Promise.all((targetClasses || []).map(async cls => ({ cls, rows: await fetchSyl(cls) })));

  // Report mein asal term name (API se) dikhao; na mile to passed term, warna exam ka term.
  const termLabel = resolvedTermName || term || ex.term || '';
  const aColor = isColor ? '#1E40AF' : '#374151';
  const aBg    = isColor ? '#EFF6FF' : '#F5F5F5';
  const aBdr   = isColor ? '#BFDBFE' : '#DDD';
  const tMuted = isColor ? '#64748B' : '#666';
  const rowEv  = isColor ? '#F8FAFF' : '#F7F7F7';
  const okC    = isColor ? '#16A34A' : '#333';
  const noC    = isColor ? '#D97706' : '#777';

  const classBlocks = blocks.map(({ cls, rows }) => {
    if (!cls) return '';
    const rowsHtml = rows.length ? rows.map((s, si) => {
      const plainAll = (s.content || '').replace(/<[^>]+>/g, '').trim();
      const added    = plainAll.length > 0;
      // Rich-text content ko AS-IS (HTML) render karo — bullets/bold/headings/math preserve hon.
      const plain    = added ? `<div class="syl-rep-html">${s.content}</div>` : '—';
      const sc       = added ? okC : noC;
      return `
        <tr style="background:${si % 2 === 0 ? '#fff' : rowEv}">
          <td style="padding:8px 12px;font-size:11.5px;font-weight:700;color:#0F172A;border-bottom:1px solid ${aBdr};vertical-align:top">${si + 1}</td>
          <td style="padding:8px 12px;font-size:11.5px;font-weight:700;color:#0F172A;border-bottom:1px solid ${aBdr};vertical-align:top">${sEsc(s.subject)}</td>
          <td style="padding:8px 12px;font-size:11px;color:${tMuted};border-bottom:1px solid ${aBdr};vertical-align:top;overflow-wrap:break-word;word-break:normal">${plain}</td>
          <td style="padding:8px 12px;border-bottom:1px solid ${aBdr};vertical-align:top">
            <span style="display:inline-block;padding:2px 8px;border-radius:999px;font-size:10px;font-weight:700;background:${sc}22;color:${sc};border:1px solid ${sc}55">
              ${added ? 'Added' : 'Not Added'}
            </span>
          </td>
        </tr>`;
    }).join('') : `<tr><td colspan="4" style="padding:12px;text-align:center;font-size:12px;color:${tMuted}">No syllabus added</td></tr>`;

    return `
      <div class="syl-class-block" style="margin-bottom:20px">
        <div class="syl-class-head" style="display:flex;align-items:center;gap:8px;margin-bottom:7px">
          <div style="width:7px;height:7px;border-radius:50%;background:${aColor};flex-shrink:0"></div>
          <div style="font-size:13px;font-weight:800;color:#0F172A">${sEsc(cls.className || `${cls.gradeName || ''}${cls.sectionName ? ' - ' + cls.sectionName : ''}`.trim())}</div>
        </div>
        <table style="width:100%;table-layout:fixed;border-collapse:collapse;border:1px solid ${aBdr}">
          <colgroup><col style="width:34px"><col style="width:110px"><col><col style="width:80px"></colgroup>
          <thead>
            <tr style="background:${aBg}">
              <th style="padding:7px 12px;font-size:10px;font-weight:700;color:${aColor};text-align:left;text-transform:uppercase;letter-spacing:.5px;border-bottom:2px solid ${aBdr}">#</th>
              <th style="padding:7px 12px;font-size:10px;font-weight:700;color:${aColor};text-align:left;text-transform:uppercase;letter-spacing:.5px;border-bottom:2px solid ${aBdr}">Subject</th>
              <th style="padding:7px 12px;font-size:10px;font-weight:700;color:${aColor};text-align:left;text-transform:uppercase;letter-spacing:.5px;border-bottom:2px solid ${aBdr}">Syllabus Summary</th>
              <th style="padding:7px 12px;font-size:10px;font-weight:700;color:${aColor};text-align:left;text-transform:uppercase;letter-spacing:.5px;border-bottom:2px solid ${aBdr}">Status</th>
            </tr>
          </thead>
          <tbody>${rowsHtml}</tbody>
        </table>
      </div>`;
  }).join('');

  const bodyHtml = `<style>
table{width:100%;table-layout:fixed}
/* Break long words only when needed — normal text wraps at word boundaries,
   not mid-word (warna text agli row me ajeeb tarah chala jata hai). */
td,th{overflow-wrap:break-word;word-break:normal}
/* Rich-text syllabus content reset (bullets/bold/headings/math preserve; KaTeX ko chhua nahi) */
.syl-rep-html{font-size:11px;line-height:1.5;color:#334155;overflow-wrap:break-word;word-break:normal}
.syl-rep-html p{font-size:11px !important;margin:2px 0 !important;color:#334155 !important}
.syl-rep-html ul,.syl-rep-html ol{font-size:11px !important;margin:3px 0 !important;padding-left:18px !important;color:#334155 !important}
.syl-rep-html li{margin:2px 0 !important}
.syl-rep-html h1,.syl-rep-html h2,.syl-rep-html h3,.syl-rep-html h4,.syl-rep-html h5,.syl-rep-html h6{font-size:12px !important;font-weight:700 !important;margin:5px 0 2px !important;color:#0F172A !important}
.syl-rep-html img{max-width:100%;height:auto}

/* ── Dynamic print pagination (NO hardcoded page breaks) ──
   Browser ki print layout engine khud available page-space ke hisaab se
   content arrange karti hai; neeche ke rules us arrangement ko guide karte
   hain. Sab selectors .syl-report-body ke andar scoped hain — sirf is
   syllabus report ke document par asar, baaki reports bilkul untouched. */
.syl-meta-grid{break-inside:avoid;page-break-inside:avoid}
/* Class block khud toot sakta hai (bari table ko pages par split karne ke liye),
   lekin uski heading hamesha table ke saath rahegi (orphan heading na ho). */
.syl-class-block{break-inside:auto;page-break-inside:auto}
.syl-class-head{break-after:avoid;page-break-after:avoid;break-inside:avoid;page-break-inside:avoid}
/* Table page boundary par toote to column header har page par dobara aaye. */
.syl-report-body table{page-break-inside:auto}
.syl-report-body thead{display:table-header-group}
.syl-report-body tfoot{display:table-footer-group}
/* Rows ko current page par jahan se shuru hon wahin se fill hone do aur zaroorat
   par (jab content remaining space se bari ho) natural-ly split hone do — yani
   bara subject-summary page ke bache hue space me bharta hai aur agle page par
   continue hota hai. 'avoid' yahan NAHI lagate: ek bari row (jo bache hue space
   se lambi ho) 'avoid' ki wajah se poori agle page par defer ho jati thi, jis se
   pehla page (ya pehla page bhi) blank reh jata tha. 'auto' us blank ko hata deta
   hai. (shared PRINT_SAFE_CSS ka row-level avoid .syl-report-body ki zyada
   specificity se override ho jata hai — sirf syllabus report par, baaki reports
   waise hi.) Column-header (th) chhoti hai, use intact rakhte hain. */
.syl-report-body tr{break-inside:auto;page-break-inside:auto}
.syl-report-body th{break-inside:avoid;page-break-inside:avoid}
/* Bari rich-text summary ko zaroorat par split hone do (warna poora blank page). */
.syl-rep-html{break-inside:auto;page-break-inside:auto}
.syl-rep-html p,.syl-rep-html li{orphans:2;widows:2}
@media print{
  .syl-report-body table{page-break-inside:auto}
  .syl-report-body tr{break-inside:auto;page-break-inside:auto}
  .syl-class-head{break-after:avoid;page-break-after:avoid}
}
</style>
    <div class="syl-report-body">
    <div class="syl-meta-grid" style="display:flex;flex-wrap:wrap;border:1px solid ${aBdr};border-radius:8px;margin-bottom:16px;overflow:hidden">
      ${[
        ['Term', termLabel],
        ['Exam', ex.name],
        ['Classes', String(targetClasses.length)],
      ].map(([k, v]) => `
        <div style="flex:1;min-width:120px;padding:10px 16px;border-right:1px solid ${aBdr};overflow-wrap:anywhere">
          <div style="font-size:9px;font-weight:700;text-transform:uppercase;letter-spacing:.5px;color:${tMuted};margin-bottom:2px">${k}</div>
          <div style="font-size:12.5px;font-weight:800;color:${aColor}">${v}</div>
        </div>
      `).join('')}
    </div>
    ${classBlocks || '<div style="padding:24px;text-align:center;color:' + tMuted + '">No syllabus yet.</div>'}
    </div>`;

  const html = buildStandardReportHtml({
    title: `Syllabus — ${ex.name}`,
    format,
    isColor,
    bodyHtml,
    subtitleLine: examKitSub(bs, sEsc(termLabel), sEsc(ex.name)),
    schoolName: examKitSchool(bs),
  });

  // PDF → print preview; Word → wahi preview "Save as Word" button ke saath (deliverReport); Excel → .xls.
  examDeliverReport(`Syllabus - ${ex?.name || ''}`, format, html, { win: w });
}

