      );
      const subjData = await subjRes.json();
      const subjRecord = Array.isArray(subjData) ? subjData[0] : (subjData?.data?.[0] || null);
      const apiTotal = Number(subjRecord?.totalMarks ?? subjectObj.totalMarks ?? 0);
