  // First subject load on mount
  useEffect(() => {
    if (subjects.length > 0) {
      fetchSubjectData(subjects[0]);
    }
  }, []);

  const handleTabClick = (idx) => {
    setTab(idx);
    fetchSubjectData(subjects[idx]);
  };

  const updateObt = (subject, val) => {
    const curSubjObj = subjects[tab];
    const subjectID = curSubjObj?.subjectID;
    const maxMarks = subjectTotalMarks[subjectID] ?? (cd.totalMarks[subject] || 0);
setObtained(o => ({
  ...o,
  [subject]: val === '' ? '' : Math.max(0, Math.min(maxMarks, parseFloat(val) || 0))
}));
  };

  const updateMc = (subject, val) => {
    setManualRemarks(o => ({ ...o, [subject]: val }));
  };

  const onAbsentToggle = e => {
    const checked = e.target.checked;
    const cs = subjects[tab]?.subjectName;
    if (!cs) return;
    // Sirf CURRENT subject ko absent mark/unmark karo (baaki subjects par asar nahi).
    setAbsentSubs(prev => ({ ...prev, [cs]: checked }));
    if (checked) setObtained(o => ({ ...o, [cs]: 0 }));
  };

  const computePayload = () => {
    const absSet = { ...absentSubs };
    (student.absentSubjects || []).forEach(s => { absSet[s] = true; });
    const subjNames = (subjects || []).map(s => s.subjectName).filter(Boolean);
    const hideZero = rcHideZeroMarkSubjects(absentMode);
    const skipSubj = (s) => absSet[s] || (hideZero && !(Number(obtained[s]) > 0));
    const tot = absentMode === 'zero'
      ? Object.values(cd.totalMarks).reduce((a, b) => a + b, 0)
      : subjNames.reduce((a, s) => skipSubj(s) ? a : a + (cd.totalMarks[s] || 0), 0);
    const obt = subjNames.reduce((a, s) => a + (skipSubj(s) ? 0 : (obtained[s] || 0)), 0);
    const pct = tot ? (obt / tot) * 100 : 0;
    return { obtained, manualRemarks, absentSubjects: Object.keys(absSet).filter(k => absSet[k]), finalRemarks: rcGetFinalRemarks(pct) };
  };

  const saveAndNext = async () => {
    // Save & Close jaise hi saari save APIs chalao, phir next subject par jao.
    // Agar save block ho (jaise total marks 0) to next par mat jao — user theek kare.
    const ok = await saveCurrentSubject();
    if (ok === false) return;
    const nextIdx = (tab + 1) % (subjects.length || 1);
    setTab(nextIdx);
    fetchSubjectData(subjects[nextIdx]);
  };
const saveCurrentSubject = async () => {
  try {
    const token = sessionStorage.getItem('token');
    const branchID = sessionStorage.getItem('branchID');
    const classID = resTotalMarksCtx?.classID || '';
    const sectionID = resTotalMarksCtx?.sectionID || '';
    const examID = resTotalMarksCtx?.selectExam || 0;
    const termID = selectedTermId || '';

    const curSubjObj = subjects[tab] || {};
    const curSubj = curSubjObj.subjectName || '';
    const curSubjID = curSubjObj.subjectID;
    const existingId = subjectExistingMarkId[curSubjID] || 0;
    const obtainedMarks = obtained[curSubj] || 0;
    const curTotal = subjectTotalMarks[curSubjID] ?? 0;
    // Total marks set na ho (0) to marks save mat karo — toaster dikhao.
    if (!curTotal || Number(curTotal) <= 0) {
      toast?.('Please add total marks for this subject.', 'error');
      return false;
    }
    const pct = curTotal > 0 ? Math.round((obtainedMarks / curTotal) * 100) : 0;
    // Auto Comment/remarks branch ke configured grading se (percentage → matching band).
    const gradeObj = (obtainedMarks && curTotal)
      ? (rcGradeByScale(pct, grades) || rcGetGrade(obtainedMarks, curTotal))
      : null;
    // Manual comment mojood hai? (agar hai to CalculateUploadRemark na chalao warna
    // wo auto-computed remark se manual value overwrite kar dega.)
    const hasManual = !!(manualRemarks[curSubj] && String(manualRemarks[curSubj]).trim());
    const remarks = manualRemarks[curSubj] || (gradeObj ? gradeObj.comment : '');

    const headers = {
      Authorization: `Bearer ${token}`,
      'Content-Type': 'application/json',
      Accept: 'application/json'
    };

    const commonParams = new URLSearchParams({
      branchId: String(branchID),
      classId: String(classID),
      sectionId: String(sectionID),
      termId: String(termID),
      examId: String(examID),
      studentId: String(student.id),
    });
const today = new Date().toISOString().split("T")[0]; // YYYY-MM-DD

    // API 1: Save marks
const savePayload = {
  id: existingId,
  subjectID: Number(curSubjID),
  obtainMarks: String(obtainedMarks),
  totalMarks: String(curTotal),
  subjectName: "",
  studentID: Number(student.id),
  classID: Number(classID),
  className: "",
  termID: Number(termID),
  term: "",
  examID: Number(examID),
  examName: "",
  sectionID: Number(sectionID),
  sectionName: "",
  branchID: Number(branchID),
  dateFrom: today, // ya dynamic date
  dateTo: today,   // ya dynamic date
  remarks: remarks,
  percentage: String(pct),
  action: existingId > 0 ? "update" : "insert",
};

    // API 1: Save marks — response check + log (silent-fail diagnose ke liye).
    // Console me actual URL/status/response dikhega; agar base URL galat ho
    // (localStorage sm_api_base_url) ya token expire ho to yahin pata chal jayega.
    const saveUrl = buildUrl('/api/sauploadmarkscrud');
    const saveRes = await fetch(saveUrl, {
      method: 'POST',
      headers,
      body: JSON.stringify(savePayload)
    });
    const saveText = await saveRes.text().catch(() => '');
    console.log('[saveMarks] POST', saveUrl, '\npayload:', savePayload, '\nstatus:', saveRes.status, '\nresponse:', saveText);
    if (!saveRes.ok) {
      toast?.(`Save failed (HTTP ${saveRes.status}). ${String(saveText).slice(0, 140)}`, 'error');
      return false;
    }

    // API 2: FetchFinalRemarksAgainstPercentage
    await fetch(
      buildUrl(`/api/FetchFinalRemarksAgainstPercentage?${commonParams}`),
      { method: 'GET', headers }
    );

    // API 3: CalculateUploadRemark — remark ko percentage/grade se dobara compute karta
    // hai. Manual comment ho to ye NA chalao, warna manual value auto se overwrite ho
    // jati hai. Manual na ho to hi auto-calculate chale.
    if (!hasManual) {
      const calculateParams = new URLSearchParams({
        ...Object.fromEntries(commonParams),
        subjectId: String(curSubjID),
      });
      await fetch(
        buildUrl(`/api/CalculateUploadRemark?${calculateParams}`),
        { method: 'GET', headers }
      );
    }

    // API 4: saveoverallstudentresultpercentage
    await fetch(buildUrl('/api/saveoverallstudentresultpercentage'), {
      method: 'POST',
      headers,
      body: JSON.stringify({
        branchID: Number(branchID),
        classID: Number(classID),
        sectionID: Number(sectionID),
        termID: Number(termID),
        examID: Number(examID),
      })
    });

    toast?.('Marks saved!', 'success');
    return true;
  } catch (err) {
    console.error('Error saving marks:', err);
    toast?.('Could not save marks', 'error');
    return false;
  }
};

const saveAndClose = async () => {
  // Save block ho (total marks 0) to modal band mat karo — user total marks add kare.
  const ok = await saveCurrentSubject();
  if (ok === false) return;
  onSave(computePayload());
};
  const curSubjObj = subjects[tab] || {};
  const curSubj = curSubjObj.subjectName || '';
  const curSubjID = curSubjObj.subjectID;
  const curAbsent = !!absentSubs[curSubj]; // sirf is subject ka absent state
  const curTotal = subjectTotalMarks[curSubjID] ?? (cd.totalMarks[curSubj] || 0);
  const curObt = obtained[curSubj] || '';
  const curPct = curTotal ? Math.round((curObt / curTotal) * 100) : 0;
  // Grade + Auto Comment branch ke configured grading (gradingcrud → grades) se —
  // percentage ke hisaab se matching band ki remarks dikhao. Config na ho to default.
  const curGrade = (curObt && curTotal)
    ? (rcGradeByScale(curPct, grades) || rcGetGrade(curObt, curTotal))
    : null;

  return createPortal(
    <div
      onClick={e => { if (e.target === e.currentTarget) onClose(); }}
      style={{ position: 'fixed', inset: 0, zIndex: 9400, background: 'rgba(10,22,40,.58)', backdropFilter: 'blur(5px)', display: 'flex', alignItems: 'center', justifyContent: 'center', padding: 20 }}
    >
      <div className="exam-modal" style={{ maxWidth: 720, display: 'flex', flexDirection: 'column', maxHeight: '90vh' }}>
        <div className="exam-modal-header">
          <div className="exam-modal-header-left">
            <div className="exam-modal-header-icon"><i className="fa-solid fa-pen-ruler"></i></div>
            <div>
              <div className="exam-modal-title">Update Result</div>
              <div className="exam-modal-sub">{student.name} · {student.father}</div>
            </div>
          </div>
          <Tooltip text="Close"><button className="exam-modal-close" onClick={onClose} aria-label="Close"><i className="fa-solid fa-xmark"></i></button></Tooltip>
        </div>

        <div className="exam-modal-body" style={{ paddingTop: 18, overflowY: 'auto' }}>
          {/* Subject tabs */}
          <div className="syl-subj-tabs">
            {subjects.map((s, i) => (
              <button
                key={`subj-${s.subjectID ?? i}-${i}`}
                className={`syl-subj-tab${tab === i ? ' active' : ''}`}
                onClick={() => handleTabClick(i)}
              >
                {saSubjectLabel(s)}
              </button>
            ))}
          </div>

          {/* Absent toggle */}
          <div style={{ display: 'flex', alignItems: 'center', gap: 12, padding: '10px 14px', background: 'var(--bg-muted)', borderRadius: 'var(--radius-md)', marginBottom: 14, border: '1px solid var(--border-light)' }}>
            <i className="fa-solid fa-user-xmark" style={{ color: '#D97706', fontSize: 16 }}></i>
            <div style={{ flex: 1 }}>
              <div style={{ fontSize: 12.5, fontWeight: 700, color: 'var(--text-primary)' }}>Mark Absent — {curSubj}</div>
              <div style={{ fontSize: 11, color: 'var(--text-muted)' }}>If absent, this subject's marks will be set to 0</div>
            </div>
            <label className="res-toggle-wrap">
              <input type="checkbox" checked={curAbsent} onChange={onAbsentToggle} />
              <span className="res-toggle-slider"></span>
            </label>
          </div>

          {/* Active subject panel */}
          <div style={{ opacity: curAbsent ? .35 : 1, pointerEvents: curAbsent ? 'none' : 'auto' }}>
            {loadingSubject ? (
              <div style={{ padding: '24px', textAlign: 'center', color: 'var(--text-muted)' }}>
                <i className="fa-solid fa-spinner fa-spin" style={{ fontSize: 20, marginBottom: 8, display: 'block' }}></i>
                Loading subject data...
              </div>
            ) : (
              <>
                <div style={{ fontSize: 12, fontWeight: 700, color: 'var(--text-secondary)', marginBottom: 8 }}>
                  {curSubj} — {student.name}
                </div>
                <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 12, marginBottom: 12 }}>
                  <div>
                    <label style={{ fontSize: 11.5, fontWeight: 700, color: 'var(--text-muted)', display: 'block', marginBottom: 4 }}>Total Marks</label>
                    <input className="rs-input" type="number" value={curTotal} readOnly style={{ background: 'var(--bg-muted)' }} />
                  </div>
                  <div>
                    <label style={{ fontSize: 11.5, fontWeight: 700, color: 'var(--text-muted)', display: 'block', marginBottom: 4 }}>Obtained Marks</label>
                    <input
                      className="rs-input"
                      type="number"
                      value={curObt}
                      min={0}
                      max={curTotal}
                      onChange={e => updateObt(curSubj, e.target.value)}
                    />
                  </div>
                </div>
                <div style={{ display: 'flex', alignItems: 'center', gap: 12, padding: '10px 14px', background: 'var(--bg-muted)', borderRadius: 'var(--radius-md)' }}>
                  <div>
                    <div style={{ fontSize: 10, fontWeight: 700, textTransform: 'uppercase', letterSpacing: '.5px', color: 'var(--text-muted)', marginBottom: 3 }}>Percentage</div>
                    <div style={{ fontSize: 15, fontWeight: 800, color: '#1E40AF' }}>{curTotal ? `${curPct}%` : '—'}</div>
                  </div>
                  <div>
                    <div style={{ fontSize: 10, fontWeight: 700, textTransform: 'uppercase', letterSpacing: '.5px', color: 'var(--text-muted)', marginBottom: 3 }}>Grade</div>
                    <div style={{ fontSize: 15, fontWeight: 800, color: curGrade ? (RS_GRADE_COLORS[curGrade.grade] || '#16A34A') : 'var(--text-muted)' }}>
                      {curGrade ? curGrade.grade : '—'}
                    </div>
                  </div>
                  <div style={{ flex: 1 }}>
                    <div style={{ fontSize: 10, fontWeight: 700, textTransform: 'uppercase', letterSpacing: '.5px', color: 'var(--text-muted)', marginBottom: 3 }}>Auto Comment</div>
                    <div style={{ fontSize: 12, color: 'var(--text-secondary)' }}>{curGrade ? curGrade.comment : '—'}</div>
                  </div>
                </div>
                <div style={{ marginTop: 12 }}>
                  <label style={{ fontSize: 11.5, fontWeight: 700, color: 'var(--text-muted)', display: 'block', marginBottom: 4 }}>Manual Comment (optional)</label>
                  <input
                    className="rs-input"
                    type="text"
                    value={manualRemarks[curSubj] || ''}
                    onChange={e => updateMc(curSubj, e.target.value)}
                    placeholder="Override auto comment..."
                  />
                </div>
              </>
            )}
          </div>
        </div>

        <div className="exam-modal-footer">
          <Tooltip text="Close"><button className="exam-cancel-btn" onClick={onClose}><i className="fa-solid fa-xmark"></i> Close</button></Tooltip>
          <Tooltip text="Save and move to the next subject">
            <button
              className="exam-cancel-btn"
              style={{ borderColor: '#1E40AF', color: '#1E40AF' }}
              onClick={saveAndNext}
            >
              <i className="fa-solid fa-arrow-right"></i> Next Subject
            </button>
          </Tooltip>
          <Tooltip text="Save and close"><button className="exam-submit-btn" onClick={saveAndClose}><i className="fa-solid fa-check"></i> Save &amp; Close</button></Tooltip>
        </div>
      </div>
    </div>,
    document.body
  );
}
/* ═══════════════════════════════════════════════════════════════════
   SINGLE ASSESSMENT — RESULT CARD VIEWER (with PDF print)
   ═══════════════════════════════════════════════════════════════════ */
/* ═══════════════════════════════════════════════════════════════════
   SINGLE ASSESSMENT — FINAL REMARKS MODAL
   ═══════════════════════════════════════════════════════════════════ */
/* ═══════════════════════════════════════════════════════════════════
   COMBINED ASSESSMENT — CREATE NEW MODAL
   ═══════════════════════════════════════════════════════════════════ */
function CbrCreateModal({ exams, onClose, onCreate, toast }) {
  /* Exams are keyed by selectExam — the real exam id all the combined-assessment
     APIs expect (mainExamID / subExams.examID / examIDs). */
  const [name, setName]             = useState('');
  const [mainSel, setMainSel]       = useState(null);   // selected main exam's selectExam
  const [subSels, setSubSels]       = useState([]);     // selected sub exams' selectExam
  const [weights, setWeights]       = useState({});     // { selectExam: weightage }
  const [subTotals, setSubTotals]   = useState({});     // { selectExam: originalTotalMarks }
  const [fetched, setFetched]       = useState(false);
  const [commonClasses, setCommonClasses] = useState([]); // [{ classID, sectionID, className, sectionName }]
  const [classes, setClasses]       = useState([]);       // selected subset (same shape)
  const [errorMsg, setErrorMsg]     = useState('');
  const [busy, setBusy]             = useState(false);

  useEffect(() => {
    const onKey = e => { if (e.key === 'Escape') onClose(); };
    document.addEventListener('keydown', onKey);
    return () => document.removeEventListener('keydown', onKey);
  }, [onClose]);

  const examSel = ex => String(ex.selectExam);
  const findBySel = sel => exams.find(e => examSel(e) === String(sel));
  const subList = exams.filter(e => examSel(e) !== String(mainSel));
  const clsKey = c => `${c.classID}_${c.sectionID}`;

  const resetDownstream = () => { setFetched(false); setCommonClasses([]); setClasses([]); setErrorMsg(''); };

  const pickMain = sel => {
    setMainSel(sel);
    setSubSels([]); setWeights({}); setSubTotals({});
    resetDownstream();
  };

  const toggleSub = sel => {
    const key = String(sel);
    setSubSels(prev => {
      if (prev.includes(key)) {
        setWeights(w => { const n = { ...w }; delete n[key]; return n; });
        return prev.filter(s => s !== key);
      }
      setWeights(w => ({ ...w, [key]: w[key] ?? 20 }));
      /* Load this sub exam's original total marks (API 3). */
      const ex = findBySel(key);
      const c  = ex?.classes?.[0];
      if (ex && c && subTotals[key] == null) {
        cbrApi.getSubExamTotalMarks(key, c.classID, c.sectionID, ex.termID)
          .then(r => setSubTotals(t => ({ ...t, [key]: r?.originalTotalMarks ?? 0 })))
          .catch(e => console.error('Error loading sub exam total marks:', e));
      }
      return [...prev, key];
    });
    resetDownstream();
  };

  const updateWeight = (sel, val) => {
    const w = Math.max(1, parseFloat(val) || 1);
    setWeights(prev => ({ ...prev, [String(sel)]: w }));
  };

  /* Fetch common classes across main + all sub exams (API 4). */
  const doFetch = async () => {
    if (!mainSel || !subSels.length) return;
    setErrorMsg('');
    try {
      const examIDs = [mainSel, ...subSels];
      const common = await cbrApi.getCommonClasses(examIDs);
      if (!common || !common.length) {
        setErrorMsg('No common classes found between main and sub exams.');
        setFetched(true); setCommonClasses([]); setClasses([]);
        return;
      }
      setFetched(true);
      setCommonClasses(common);
      setClasses(common.slice()); // pre-select all
    } catch (e) {
      console.error('Error fetching common classes:', e);
      setErrorMsg(e.serverMessage || 'Could not fetch classes.');
    }
  };

  const toggleClass = cls => {
    setClasses(prev => prev.some(c => clsKey(c) === clsKey(cls))
      ? prev.filter(c => clsKey(c) !== clsKey(cls))
      : [...prev, cls]);
  };

  const canCreate = !!mainSel && subSels.length > 0 && fetched && classes.length > 0 && !!name.trim();

  let hint = 'Select a Main Exam to continue';
  let hintColor = 'var(--text-muted)';
  if (errorMsg) {
    hint = errorMsg;
    hintColor = '#DC2626';
  } else if (!name.trim()) {
    hint = 'Enter a name for this combined result';
  } else if (!mainSel) {
    hint = 'Select a Main Exam to continue';
  } else if (!subSels.length) {
    hint = 'Now select one or more Sub Exams';
  } else if (!fetched) {
    hint = 'Set weightage for each sub exam, then click Fetch Classes';
  } else if (!classes.length) {
    hint = 'Select at least one class';
    hintColor = '#D97706';
  } else {
    hint = `${classes.length} class${classes.length > 1 ? 'es' : ''} selected · Ready to create`;
    hintColor = '#16A34A';
  }

  /* Create the combined result (API 5), then let the parent refresh the list. */
  const handleCreate = async () => {
    if (!canCreate || busy) return;
    setBusy(true);
    try {
      await cbrApi.createCombinedResult({
        combinedResultName: name.trim(),
        mainExamID: Number(mainSel),
        subExams: subSels.map(sel => ({
          examID: Number(sel),
          examName: findBySel(sel)?.name || '',
          originalTotalMarks: Number(subTotals[sel] || 0),
          weightage: Number(weights[sel] || 0),
        })),
        classSectionIDs: classes.map(c => ({ classID: c.classID, sectionID: c.sectionID })),
      });
      onCreate();
    } catch (e) {
      console.error('Error creating combined result:', e);
      toast(e.serverMessage || 'Could not create combined result', 'error');
      setBusy(false);
    }
  };

  return createPortal(
    <div
      onClick={e => { if (e.target === e.currentTarget) onClose(); }}
      style={{ position: 'fixed', inset: 0, zIndex: 9800, background: 'rgba(10,22,40,.65)', backdropFilter: 'blur(5px)', display: 'flex', alignItems: 'center', justifyContent: 'center', padding: 16, overflowY: 'auto' }}
    >
      <div style={{ background: 'var(--bg-card)', borderRadius: 20, width: '100%', maxWidth: 700, maxHeight: '92vh', display: 'flex', flexDirection: 'column', boxShadow: '0 24px 64px rgba(0,0,0,.35)', animation: 'fadeSlide .22s ease', overflow: 'hidden' }}>
        {/* Header */}
        <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', padding: '18px 24px', borderBottom: '1px solid var(--border-light)', background: 'var(--bg-muted)', flexShrink: 0 }}>
          <div style={{ display: 'flex', alignItems: 'center', gap: 10 }}>
            <div style={{ width: 34, height: 34, borderRadius: 9, background: 'linear-gradient(135deg,#1E40AF,#7C3AED)', color: '#fff', display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: 14 }}>
              <i className="fa-solid fa-layer-group"></i>
            </div>
            <div>
              <div style={{ fontSize: 15, fontWeight: 800, color: 'var(--text-primary)' }}>Create Combined Result</div>
              <div style={{ fontSize: 11.5, color: 'var(--text-muted)', marginTop: 1 }}>Set up a new combined assessment</div>
            </div>
          </div>
          <button
            type="button"
            onClick={onClose}
            style={{ width: 32, height: 32, borderRadius: 8, border: '1.5px solid var(--border-light)', background: 'transparent', color: 'var(--text-muted)', cursor: 'pointer', display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: 14 }}
          >
            <i className="fa-solid fa-xmark"></i>
          </button>
        </div>

        {/* Body */}
        <div style={{ flex: 1, overflowY: 'auto', padding: '22px 24px' }}>
          {/* Info banner */}
          <div style={{ display: 'flex', gap: 10, padding: '11px 14px', background: 'rgba(30,64,175,.08)', border: '1px solid rgba(30,64,175,.2)', borderRadius: 10, marginBottom: 20 }}>
            <i className="fa-solid fa-circle-info" style={{ color: '#1E40AF', fontSize: 13, marginTop: 1, flexShrink: 0 }}></i>
            <div style={{ fontSize: 11.5, color: 'var(--text-secondary)', lineHeight: 1.65 }}>
              Select a <strong>Main Exam</strong> and one or more <strong>Sub Exams</strong>. Click <strong>Fetch Classes</strong> to load matching classes, select your classes, then click <strong>Create Combined Result</strong>.
            </div>
          </div>

          {/* Result Name */}
          <div style={{ marginBottom: 18 }}>
            <label style={{ display: 'block', fontSize: 10, fontWeight: 700, textTransform: 'uppercase', letterSpacing: '.8px', color: 'var(--text-muted)', marginBottom: 7 }}>
              <i className="fa-solid fa-tag" style={{ color: '#1E40AF', marginRight: 5 }}></i>Combined Result Name
            </label>
            <input
              className="rs-input"
              type="text"
              value={name}
              onChange={e => setName(e.target.value)}
              placeholder="e.g. Mid + Final Combined Result"
              style={{ padding: '10px 14px', fontSize: 13, fontWeight: 600 }}
            />
          </div>

          {/* Main Exam */}
          <div style={{ marginBottom: 18 }}>
            <div style={{ fontSize: 10, fontWeight: 700, textTransform: 'uppercase', letterSpacing: '.8px', color: 'var(--text-muted)', marginBottom: 8, display: 'flex', alignItems: 'center', gap: 8 }}>
              <i className="fa-solid fa-book-open" style={{ color: '#1E40AF' }}></i>Main Exam
              <span style={{ flex: 1, height: 1, background: 'var(--border-light)' }}></span>
            </div>
            <div style={{ display: 'flex', flexWrap: 'wrap', gap: 8 }}>
              {exams.map(ex => (
                <button
                  key={examSel(ex)}
                  type="button"
                  className={`ds-exam-btn${String(mainSel) === examSel(ex) ? ' active' : ''}`}
                  onClick={() => pickMain(examSel(ex))}
                >
