            <i className="fa-solid fa-file"></i> Single Assessment
          </button>
          <button type="button" style={mode === 'combined' ? tabActive : tabBase} onClick={() => setMode('combined')}>
            <i className="fa-solid fa-layer-group"></i> Combined Assessment
          </button>
        </div>
        )}

        {/* Card area */}
        <div style={{ flex: 1, overflowY: 'auto', padding: 24, background: '#F1F5F9' }}>
          {loading ? (
            <div style={{ maxWidth: 720, margin: '0 auto', minHeight: 280, display: 'flex', flexDirection: 'column', alignItems: 'center', justifyContent: 'center', color: 'var(--text-muted)', fontSize: 13 }}>
              <i className="fa-solid fa-spinner fa-spin" style={{ fontSize: 28, marginBottom: 14, color: tConfig.accent }}></i>
              Loading result card…
            </div>
          ) : (
          <div ref={cardRef} style={{ maxWidth: 720, margin: '0 auto', borderRadius: 12, overflow: 'hidden', boxShadow: '0 8px 32px rgba(0,0,0,.14)' }}>
            {template === 'classic' && (
              <ClassicResultCard
                rcoGeneral={rcoGeneral} rcoSig={rcoSig} rsSigs={rsSigs} rsAbsentMode={rsAbsentMode}
                mode={mode} student={stEff} rd={rd} ex={ex} school={school} grades={grades} remarks={remarks}
              />
            )}
            {template === 'insight' && (
              <InsightResultCard
                rcoGeneral={rcoGeneral} rcoSig={rcoSig} rsSigs={rsSigs} rsAbsentMode={rsAbsentMode}
                mode={mode} student={stEff} rd={rd} ex={ex} school={school} grades={grades} remarks={remarks}
              />
            )}
            {template === 'portfolio' && (
              <PortfolioResultCard
                rcoGeneral={rcoGeneral} rcoSig={rcoSig} rsSigs={rsSigs} rsAbsentMode={rsAbsentMode}
                mode={mode} student={stEff} rd={rd} ex={ex} school={school} grades={grades} remarks={remarks}
              />
            )}
          </div>
          )}
        </div>
      </div>
    </div>,
    document.body
  );
}

/* Bulk result cards — ek class/section ke SAARE students ke result cards ek saath.
   APIs: getstudentsbybranchsectionandgrade (students) → getsasubjectbybranchclassandterm (exam subjects)
   → getsauploadmarksbyclassandtermandexamandsubject (per student/subject marks + remarks)
   → getremarksbystudentfilters (final remark). Single-card jaisi hi rendering, bas N students. */
function BulkCardModal({ ctx, template, school, grades, remarks = [], rcoGeneral, rcoSig, rsSigs, rsAbsentMode, onClose, toast }) {
  const { classID, sectionID, selectExam, termID, className, examName, students: presetStudents } = ctx;
  const [cards, setCards]       = useState([]);   // [{ student, rd }]
  const [loading, setLoading]   = useState(true);
  const [progress, setProgress] = useState({ done: 0, total: 0 });
  const [attnMap, setAttnMap]   = useState({});   // { [studentId]: pct } — REAL attendance
  const cardRef = useRef(null);

  useEffect(() => {
    const onKey = e => { if (e.key === 'Escape') onClose(); };
    document.addEventListener('keydown', onKey);
    return () => document.removeEventListener('keydown', onKey);
  }, [onClose]);

  // Poori class ki REAL attendance (cards ke saath parallel) — ek dafa laao.
  useEffect(() => {
    let alive = true;
    fetchClassAttendanceMap(classID, sectionID).then(map => { if (alive) setAttnMap(map || {}); });
    return () => { alive = false; };
    /* eslint-disable-next-line react-hooks/exhaustive-deps */
  }, []);

  useEffect(() => {
    let cancelled = false;
    (async () => {
      try {
        setLoading(true);
        const branchID = sessionStorage.getItem('branchID');
        const token    = sessionStorage.getItem('token');
        const headers  = { Authorization: `Bearer ${token}`, Accept: 'application/json' };

        // Poori class — exam list kabhi 1 student pe ruk jati hai, roster se poori lo.
        const studentsRaw = await rcFetchClassStudents(classID, sectionID, presetStudents);
        const photoMap = await loadClassPhotoMap(classID, sectionID).catch(() => ({}));

        let subs = [];
        try {
          const rawSubs = await cbrApi.getMainExamSubjects({ classID, sectionID, termID, examID: selectExam });
          subs = rcNormalizeSubjects((rawSubs || []).map(saNormSubject).filter(Boolean));
        } catch { /* no subjects */ }
        if (!subs.length && studentsRaw[0]) {
          try {
            const merged = await cbrApi.mergeSaSubjectsWithStudentMarks({
              classID, sectionID, termID, examID: selectExam, studentID: rcStuId(studentsRaw[0]),
            });
            subs = rcNormalizeSubjects((merged || []).map(saNormSubject).filter(Boolean));
          } catch { /* keep empty */ }
        }

        if (!cancelled) setProgress({ done: 0, total: studentsRaw.length });
        let done = 0;
        const built = await rcMapPool(studentsRaw, 4, async (stu) => {
          if (cancelled) return null;
          const studentId = rcStuId(stu);
          const obtained = {}, manualRemarks = {}, totals = {}, absentSubjects = [];
          await Promise.all(subs.map(async su => {
            try {
              const p = new URLSearchParams({
                classID: String(classID), termID: String(termID ?? ''), ExamID: String(selectExam),
                SubjectID: String(su.subjectID), StudentID: String(studentId), sectionID: String(sectionID), pageNo: '1',
              });
              const r = await fetch(buildUrl(`/api/getsauploadmarksbyclassandtermandexamandsubject?${p}`), { headers });
              const d = await r.json();
              const rec = Array.isArray(d) ? d[0] : (d?.data?.[0] || d?.Data?.[0] || null);
              obtained[su.subjectName] = Number(rec?.obtainMarks ?? rec?.obtainedMarks ?? 0);
              totals[su.subjectName]   = Number(rec?.totalMarks ?? su.totalMarks ?? 0);
              if (rec?.remarks) manualRemarks[su.subjectName] = rec.remarks;
              if (resSubjAbsent(rec, su.totalMarks)) absentSubjects.push(su.subjectName);
            } catch { absentSubjects.push(su.subjectName); }
          }));
          let finalRemark = '';
          try {
            const fp = new URLSearchParams({
              branchID: String(branchID), classID: String(classID), sectionID: String(sectionID),
              examID: String(selectExam), termID: String(termID ?? ''), studentID: String(studentId),
              pageNo: '1', pageCount: '20',
            });
            const fr = await fetch(buildUrl(`/api/getremarksbystudentfilters?${fp}`), { headers });
            const fd = await fr.json();
            const frec = Array.isArray(fd?.data) ? fd.data[0] : (Array.isArray(fd) ? fd[0] : null);
            finalRemark = frec?.remarks || '';
          } catch { /* no final remark */ }
          done += 1;
          if (!cancelled) setProgress({ done, total: studentsRaw.length });
          const obtSum = Object.values(obtained).reduce((a, n) => a + (Number(n) || 0), 0);
          return {
            _obt: obtSum,
            student: {
              id: studentId,
              rollNo: rcStuRoll(stu),
              name: rcStuName(stu),
              father: rcStuFather(stu),
              obtained, manualRemarks, finalRemarks: finalRemark,
              absentSubjects, attendance: '—',
              photo: rcPhotoFromRecord(stu, photoMap),
            },
            rd: { released: false, totalMarks: totals, subjects: subs.map(s => s.subjectName) },
          };
        }, () => cancelled);

        const ranked = built
          .filter(c => c._obt > 0)
          .sort((a, b) => (b._obt - a._obt) || a.student.name.localeCompare(b.student.name));
        const rankOf = {};
        let cur = 0, prev = null;
        ranked.forEach((c, i) => {
          if (prev === null || c._obt !== prev) { cur = i + 1; prev = c._obt; }
          rankOf[String(c.student.id)] = rcOrdinal(cur);
        });
        const cardsOut = built.map(c => ({
          student: { ...c.student, position: rankOf[String(c.student.id)] || '—' },
          rd: c.rd,
        }));
        if (!cancelled) { setCards(cardsOut); setLoading(false); }
      } catch (e) {
        console.error('Bulk card load failed', e);
        if (!cancelled) { setLoading(false); toast?.('Could not load bulk cards', 'error'); }
      }
    })();
    return () => { cancelled = true; };
    /* eslint-disable-next-line react-hooks/exhaustive-deps */
  }, []);

  const cardEx = { name: examName || 'Result', classes: [className || ''] };
  const Card = template === 'insight' ? InsightResultCard : template === 'portfolio' ? PortfolioResultCard : ClassicResultCard;

  const printAll = () => {
    const node = cardRef.current;
    if (!node) return;
    const w = window.open('', '_blank', 'width=980,height=860');
    if (!w) { toast?.('Pop-up blocker prevented opening', 'error'); return; }
    w.document.write(`<!DOCTYPE html><html><head>
<meta charset="UTF-8">
<link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.5.2/css/all.min.css">
<title>Result Cards — ${className || ''}</title>
<style>
*{margin:0;padding:0;box-sizing:border-box}
html,body{background:#fff;font-family:'Plus Jakarta Sans','Segoe UI',Arial,sans-serif;color:#0F172A}
@page{size:A4 portrait;margin:12mm}
@media print{ body{-webkit-print-color-adjust:exact;print-color-adjust:exact} .no-print{display:none!important}
  thead{display:table-header-group} tr{break-inside:avoid;page-break-inside:avoid} }
.bulk-card{max-width:210mm;margin:0 auto 12px;page-break-after:always;break-after:page;overflow:visible!important;height:auto!important}
.bulk-card:last-child{page-break-after:auto;break-after:auto}
.bulk-card img{max-width:100%;height:auto}
.print-bar{text-align:center;padding:14px;background:#F8FAFF;border-top:1px solid #BFDBFE}
.print-bar button{background:linear-gradient(135deg,#1E3A8A,#1E40AF);color:#fff;border:none;padding:10px 22px;border-radius:10px;font-size:13px;font-weight:700;cursor:pointer;margin-right:8px}
.print-bar .close-btn{background:transparent;border:1.5px solid #CBD5E1;color:#64748B}
.cl-doc-header, .cl-doc-header *{color:#0F172A !important;text-shadow:none !important}
</style></head><body>
${node.innerHTML}
<div class="print-bar no-print">
  <button onclick="window.print()">🖨 Save as PDF</button>
  <button class="close-btn" onclick="window.close()">Close</button>
</div>
</body></html>`);
    w.document.close();
  };

  return createPortal(
    <div onClick={e => { if (e.target === e.currentTarget) onClose(); }}
      style={{ position: 'fixed', inset: 0, zIndex: 9500, background: 'rgba(10,22,40,.7)', backdropFilter: 'blur(6px)', display: 'flex', alignItems: 'center', justifyContent: 'center', padding: 20, overflowY: 'auto' }}>
      <div style={{ background: 'var(--bg-card)', borderRadius: 18, width: '100%', maxWidth: 820, maxHeight: '92vh', display: 'flex', flexDirection: 'column', overflow: 'hidden', boxShadow: '0 24px 64px rgba(0,0,0,.4)' }}>
        {/* Header */}
        <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', padding: '14px 22px', borderBottom: '1px solid var(--border-light)', background: 'var(--bg-muted)', flexShrink: 0 }}>
          <div>
            <div style={{ fontSize: 14, fontWeight: 700, color: 'var(--text-primary)' }}>Bulk Result Cards — {className}</div>
            <div style={{ fontSize: 11, color: 'var(--text-muted)', marginTop: 1 }}>
              {examName} · {loading ? `Loading ${progress.done}/${progress.total}…` : `${cards.length} student${cards.length !== 1 ? 's' : ''}`}
            </div>
          </div>
          <div style={{ display: 'flex', gap: 8 }}>
            <button type="button" onClick={printAll} disabled={loading || !cards.length}
              style={{ display: 'inline-flex', alignItems: 'center', gap: 6, padding: '7px 16px', borderRadius: 9, background: (!loading && cards.length) ? 'linear-gradient(135deg,#1E3A8A,#1E40AF)' : '#94A3B8', border: 'none', color: '#fff', fontSize: 12.5, fontWeight: 700, cursor: (!loading && cards.length) ? 'pointer' : 'not-allowed', fontFamily: 'inherit' }}>
              <i className="fa-solid fa-file-pdf"></i> {loading ? `Loading ${progress.done}/${progress.total}` : `Print All (${cards.length})`}
            </button>
            <button type="button" onClick={onClose}
              style={{ width: 32, height: 32, borderRadius: 8, border: '1.5px solid var(--border-light)', background: 'transparent', color: 'var(--text-muted)', cursor: 'pointer', display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
              <i className="fa-solid fa-xmark"></i>
            </button>
          </div>
        </div>
        {/* Cards area */}
        <div style={{ flex: 1, overflowY: 'auto', padding: 24, background: '#F1F5F9' }}>
          {loading && !cards.length ? (
            <div style={{ textAlign: 'center', padding: 40, color: 'var(--text-muted)' }}>
              <i className="fa-solid fa-spinner fa-spin" style={{ fontSize: 26, marginBottom: 12, display: 'block' }}></i>
              Loading students &amp; marks… ({progress.done}/{progress.total})
            </div>
          ) : !cards.length ? (
            <div style={{ textAlign: 'center', padding: 40, color: 'var(--text-muted)' }}>No students found for this class.</div>
          ) : (
            <div ref={cardRef} style={{ maxWidth: 720, margin: '0 auto' }}>
              {cards.map((c, i) => (
                <div key={c.student.id || i} className="bulk-card" style={{ marginBottom: 18, borderRadius: 12, overflow: 'hidden', boxShadow: '0 8px 32px rgba(0,0,0,.14)' }}>
                  <Card rcoGeneral={rcoGeneral} rcoSig={rcoSig} rsSigs={rsSigs} rsAbsentMode={rsAbsentMode}
                    mode="single"
                    student={attnMap[String(c.student.id)] != null ? { ...c.student, attendance: `${attnMap[String(c.student.id)]}%` } : c.student}
                    rd={c.rd} ex={cardEx} school={school} grades={grades} remarks={remarks} />
                </div>
              ))}
            </div>
          )}
        </div>
      </div>
    </div>,
    document.body
  );
}

/* Bulk COMBINED result cards — ek class ke SAARE students ke combined cards ek saath.
   Combined breakdown (grandTotal / sub-exam breakdown / overall % / rank) pehle se cbrResults
   group ke har student par maujood hai; sirf per-subject main-exam marks load karne hain. */
function BulkCombinedCardModal({ grp, termID, template, school, grades, remarks = [], rcoGeneral, rcoSig, rsSigs, rsAbsentMode, onClose, toast }) {
  const [cards, setCards]       = useState([]);
  const [loading, setLoading]   = useState(true);
  const [progress, setProgress] = useState({ done: 0, total: (grp?.students || []).length });
  const [attnMap, setAttnMap]   = useState({});   // { [studentId]: pct } — REAL attendance
  const cardRef = useRef(null);

  useEffect(() => {
    const onKey = e => { if (e.key === 'Escape') onClose(); };
    document.addEventListener('keydown', onKey);
    return () => document.removeEventListener('keydown', onKey);
  }, [onClose]);

  // Poori class ki REAL attendance (cards ke saath parallel) — ek dafa laao.
  useEffect(() => {
    if (!grp) return undefined;
    let alive = true;
    fetchClassAttendanceMap(grp.classID, grp.sectionID).then(map => { if (alive) setAttnMap(map || {}); });
    return () => { alive = false; };
    /* eslint-disable-next-line react-hooks/exhaustive-deps */
  }, []);

  useEffect(() => {
    if (!grp) return undefined;
    let cancelled = false;
    (async () => {
      try {
        setLoading(true);
        const empID = sessionStorage.getItem('employee_ID');
        const token = sessionStorage.getItem('token');
        const headers = { Authorization: `Bearer ${token}`, Accept: 'application/json' };

        // 1) Main exam ke subjects (na milein to sub-exam ki list, bina marks ke)
        let subs = await cbrApi.getMainExamSubjects({ classID: grp.classID, sectionID: grp.sectionID, termID, examID: grp.mainExamID }).catch(() => []);
        let withMarks = true;
        if ((!subs || !subs.length) && grp.subExamIDs?.length) {
          subs = await cbrApi.getMainExamSubjects({ classID: grp.classID, sectionID: grp.sectionID, termID, examID: grp.subExamIDs[0] }).catch(() => []);
          withMarks = false;
        }
        subs = subs || [];
        // subjectName=null → naam resolve karo
        const nameMap = {};
        try {
          const subRes = await fetch(buildUrl(`/get-subjects_byEmployeeID/${grp.classID}/${grp.sectionID}/${empID}`), { headers });
          const subData = await subRes.json();
          (subData?.data || (Array.isArray(subData) ? subData : [])).forEach(s => { nameMap[s.subjectID] = s.subjectName; });
        } catch { /* names best-effort */ }
        subs = rcNormalizeSubjects(subs, nameMap);
        const subjectNames = subs.map(s => s.subjectName);

        // Poori class. grp.students kabhi sirf 1 row hoti hai (CA marks API) —
        // roster se baqi students bhi lo, warna bulk ek hi card banata hai.
        const roster = await rcFetchClassStudents(grp.classID, grp.sectionID);
        const photoMap = await loadClassPhotoMap(grp.classID, grp.sectionID).catch(() => ({}));
        const known = new Map();
        (grp.students || []).forEach(st => {
          if (st?.studentID != null) known.set(String(st.studentID), st);
        });
        let people = roster.slice();
        const rosterIds = new Set(people.map(p => String(rcStuId(p) ?? '')));
        known.forEach((st, id) => {
          if (!rosterIds.has(id)) {
            people.push({
              id: st.studentID, studentID: st.studentID,
              studentName: st.name, fatherName: st.father, registrationNumber: st.rollNo,
            });
          }
        });
        if (!people.length) {
          people = [...known.values()].map(st => ({
            id: st.studentID, studentID: st.studentID,
            studentName: st.name, fatherName: st.father, registrationNumber: st.rollNo,
          }));
        }

        const num = v => Number(v ?? 0) || 0;
        const fromApiCard = (c, info) => {
          const sid = c.studentID ?? c.StudentID;
          const main = c.mainExam ?? c.MainExam ?? {};
          const subArr = c.subExams ?? c.SubExams ?? [];
          return {
            studentID: sid,
            rollNo: info.rollNo || c.registrationNumber || c.RegistrationNumber || sid,
            name: info.name || c.studentName || c.StudentName || '—',
            father: info.father || c.fatherName || c.FatherName || '',
            mainObt: num(main.obtainedMarks ?? main.ObtainedMarks),
            mainTotal: num(main.totalMarks ?? main.TotalMarks),
            subs: subArr.map(s => ({
              name: s.examName ?? s.ExamName ?? '',
              subObt: num(s.originalObtained ?? s.OriginalObtained),
              origT: num(s.originalTotal ?? s.OriginalTotal),
              conv: num(s.convertedObtained ?? s.ConvertedObtained),
              weight: num(s.weightage ?? s.Weightage),
            })),
            grandObt: num(c.grandObtained ?? c.GrandObtained),
            grandTotal: num(c.grandTotal ?? c.GrandTotal),
            pct: num(c.percentage ?? c.Percentage),
            rank: String(c.ranking ?? c.Ranking ?? ''),
          };
        };

        if (!cancelled) setProgress({ done: 0, total: people.length });
        let done = 0;
        const built = await rcMapPool(people, 4, async (person) => {
          if (cancelled) return null;
          const studentId = rcStuId(person);
          let st = known.get(String(studentId));
          if (!st && studentId != null) {
            const card = await cbrApi.getStudentCard({
              studentID: studentId, subExamIDs: grp.subExamIDs || [],
              classID: grp.classID, sectionID: grp.sectionID, mainExamID: grp.mainExamID,
            }).catch(() => null);
            if (card) {
              st = fromApiCard(card, { name: rcStuName(person), father: rcStuFather(person), rollNo: rcStuRoll(person) });
            }
          }
          if (!st) {
            st = {
              studentID: studentId, rollNo: rcStuRoll(person), name: rcStuName(person), father: rcStuFather(person),
              mainObt: 0, mainTotal: 0, subs: [], grandObt: 0, grandTotal: 0, pct: 0, rank: '',
            };
          }
          const obtained = {}, totals = {}, absentSubjects = [];
          if (withMarks) {
            await Promise.all(subs.map(async su => {
              const m = await cbrApi.getStudentSubjectMark({
                classID: grp.classID, sectionID: grp.sectionID, termID,
                examID: grp.mainExamID, subjectID: su.subjectID, studentID: st.studentID,
              }).catch(() => null);
              obtained[su.subjectName] = m == null ? '' : m;
              totals[su.subjectName]   = su.totalMarks;
              if (m == null || String(m).trim() === '' || !su.totalMarks || Number(su.totalMarks) <= 0) absentSubjects.push(su.subjectName);
            }));
          } else {
            subs.forEach(su => { obtained[su.subjectName] = ''; totals[su.subjectName] = su.totalMarks; absentSubjects.push(su.subjectName); });
          }
          done += 1;
          if (!cancelled) setProgress({ done, total: people.length });
          const rankNum = parseInt(st.rank, 10) || 0;
          const rankSfx = rankNum ? ((String(st.rank).match(/[a-z]+$/i) || [''])[0] || (rankNum === 1 ? 'st' : rankNum === 2 ? 'nd' : rankNum === 3 ? 'rd' : 'th')) : '';
          return {
            student: {
              id: st.studentID, rollNo: st.rollNo || rcStuRoll(person), name: st.name || rcStuName(person), father: st.father || rcStuFather(person),
              obtained, absentSubjects, attendance: '—', _attnId: st.studentID,
              photo: rcPhotoFromRecord(person, photoMap) || await rcStudentPhoto(grp.classID, grp.sectionID, st.studentID, st.rollNo),
              _combined: {
                grandTotal: st.grandTotal, grandObt: st.grandObt, ovPct: st.pct,
                mainExName: grp.mainExam, mainTotal: st.mainTotal, mainObt: st.mainObt,
                subBreakdown: st.subs, rank: rankNum, rankSfx,
              },
            },
            rd: { totalMarks: Object.keys(totals).length ? totals : { ...RES_DEFAULT_TOTALS }, subjects: subjectNames },
          };
        }, () => cancelled);

        // Jis student ka rank API se nahi aaya, grand obtained se class position.
        const needRank = built.some(c => !c.student._combined.rank);
        if (needRank) {
          const order = built
            .map((c, i) => ({ i, obt: Number(c.student._combined.grandObt) || 0, name: c.student.name }))
            .filter(x => x.obt > 0)
            .sort((a, b) => (b.obt - a.obt) || String(a.name).localeCompare(String(b.name)));
          let cur = 0, prev = null;
          order.forEach((x, idx) => {
            if (prev === null || x.obt !== prev) { cur = idx + 1; prev = x.obt; }
            if (!built[x.i].student._combined.rank) {
              const label = rcOrdinal(cur);
              built[x.i].student._combined.rank = cur;
              built[x.i].student._combined.rankSfx = String(label).replace(String(cur), '');
            }
          });
        }
        built.forEach(c => {
          if (!c.student._combined.rank) {
            c.student._combined.rank = '—';
            c.student._combined.rankSfx = '';
          }
        });
        if (!cancelled) { setCards(built); setLoading(false); }
      } catch (e) {
        console.error('Bulk combined card load failed', e);
        if (!cancelled) { setLoading(false); toast?.('Could not load combined cards', 'error'); }
      }
    })();
    return () => { cancelled = true; };
    /* eslint-disable-next-line react-hooks/exhaustive-deps */
  }, []);

  const cardEx = { name: grp?.mainExam || 'Combined', classes: [grp?.cls || ''] };
  const Card = template === 'insight' ? InsightResultCard : template === 'portfolio' ? PortfolioResultCard : ClassicResultCard;

  const printAll = () => {
    const node = cardRef.current;
    if (!node) return;
    const w = window.open('', '_blank', 'width=980,height=860');
    if (!w) { toast?.('Pop-up blocker prevented opening', 'error'); return; }
    w.document.write(`<!DOCTYPE html><html><head><meta charset="UTF-8"><title>Combined Result Cards — ${grp?.cls || ''}</title>
<link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.5.2/css/all.min.css">
<style>
*{margin:0;padding:0;box-sizing:border-box}
html,body{background:#fff;font-family:'Plus Jakarta Sans','Segoe UI',Arial,sans-serif;color:#0F172A}
@page{size:A4 portrait;margin:12mm}
@media print{ body{-webkit-print-color-adjust:exact;print-color-adjust:exact} .no-print{display:none!important}
  thead{display:table-header-group} tr{break-inside:avoid;page-break-inside:avoid} }
.bulk-card{max-width:210mm;margin:0 auto 12px;page-break-after:always;break-after:page;overflow:visible!important;height:auto!important}
.bulk-card:last-child{page-break-after:auto;break-after:auto}
.bulk-card img{max-width:100%;height:auto}
.print-bar{text-align:center;padding:14px;background:#F8FAFF;border-top:1px solid #BFDBFE}
.print-bar button{background:linear-gradient(135deg,#1E3A8A,#1E40AF);color:#fff;border:none;padding:10px 22px;border-radius:10px;font-size:13px;font-weight:700;cursor:pointer;margin-right:8px}
.print-bar .close-btn{background:transparent;border:1.5px solid #CBD5E1;color:#64748B}
.cl-doc-header, .cl-doc-header *{color:#0F172A !important;text-shadow:none !important}
</style></head><body>
${node.innerHTML}
<div class="print-bar no-print">
  <button onclick="window.print()">🖨 Save as PDF</button>
  <button class="close-btn" onclick="window.close()">Close</button>
</div>
</body></html>`);
    w.document.close();
  };

  return createPortal(
    <div onClick={e => { if (e.target === e.currentTarget) onClose(); }}
      style={{ position: 'fixed', inset: 0, zIndex: 9500, background: 'rgba(10,22,40,.7)', backdropFilter: 'blur(6px)', display: 'flex', alignItems: 'center', justifyContent: 'center', padding: 20, overflowY: 'auto' }}>
      <div style={{ background: 'var(--bg-card)', borderRadius: 18, width: '100%', maxWidth: 820, maxHeight: '92vh', display: 'flex', flexDirection: 'column', overflow: 'hidden', boxShadow: '0 24px 64px rgba(0,0,0,.4)' }}>
        <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', padding: '14px 22px', borderBottom: '1px solid var(--border-light)', background: 'var(--bg-muted)', flexShrink: 0 }}>
          <div>
            <div style={{ fontSize: 14, fontWeight: 700, color: 'var(--text-primary)' }}>Bulk Combined Cards — {grp?.cls}</div>
            <div style={{ fontSize: 11, color: 'var(--text-muted)', marginTop: 1 }}>
              {grp?.mainExam} · {loading ? `Loading ${progress.done}/${progress.total}…` : `${cards.length} student${cards.length !== 1 ? 's' : ''}`}
            </div>
          </div>
          <div style={{ display: 'flex', gap: 8 }}>
            <button type="button" onClick={printAll} disabled={loading || !cards.length}
              style={{ display: 'inline-flex', alignItems: 'center', gap: 6, padding: '7px 16px', borderRadius: 9, background: (!loading && cards.length) ? 'linear-gradient(135deg,#1E3A8A,#1E40AF)' : '#94A3B8', border: 'none', color: '#fff', fontSize: 12.5, fontWeight: 700, cursor: (!loading && cards.length) ? 'pointer' : 'not-allowed', fontFamily: 'inherit' }}>
              <i className="fa-solid fa-file-pdf"></i> {loading ? `Loading ${progress.done}/${progress.total}` : `Print All (${cards.length})`}
            </button>
            <button type="button" onClick={onClose}
              style={{ width: 32, height: 32, borderRadius: 8, border: '1.5px solid var(--border-light)', background: 'transparent', color: 'var(--text-muted)', cursor: 'pointer', display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
              <i className="fa-solid fa-xmark"></i>
            </button>
          </div>
        </div>
        <div style={{ flex: 1, overflowY: 'auto', padding: 24, background: '#F1F5F9' }}>
          {loading && !cards.length ? (
            <div style={{ textAlign: 'center', padding: 40, color: 'var(--text-muted)' }}>
              <i className="fa-solid fa-spinner fa-spin" style={{ fontSize: 26, marginBottom: 12, display: 'block' }}></i>
              Loading students &amp; combined marks… ({progress.done}/{progress.total})
            </div>
          ) : !cards.length ? (
            <div style={{ textAlign: 'center', padding: 40, color: 'var(--text-muted)' }}>No students found.</div>
          ) : (
            <div ref={cardRef} style={{ maxWidth: 720, margin: '0 auto' }}>
              {cards.map((c, i) => (
                <div key={c.student.id || i} className="bulk-card" style={{ marginBottom: 18, borderRadius: 12, overflow: 'hidden', boxShadow: '0 8px 32px rgba(0,0,0,.14)' }}>
                  <Card rcoGeneral={rcoGeneral} rcoSig={rcoSig} rsSigs={rsSigs} rsAbsentMode={rsAbsentMode}
                    mode="combined"
                    student={attnMap[String(c.student._attnId)] != null ? { ...c.student, attendance: `${attnMap[String(c.student._attnId)]}%` } : c.student}
                    rd={c.rd} ex={cardEx} school={school} grades={grades} remarks={remarks} />
                </div>
              ))}
            </div>
          )}
        </div>
      </div>
    </div>,
    document.body
  );
}

function TemplatePreviewModal({ templateId, rcoGeneral, rcoSig, rsSigs, rsAbsentMode, onClose, onSelect }) {
  const t = RC_TEMPLATES.find(x => x.id === templateId);
  const [mode, setMode] = useState('single'); // single | combined

  useEffect(() => {
    const onKey = e => { if (e.key === 'Escape') onClose(); };
    document.addEventListener('keydown', onKey);
    return () => document.removeEventListener('keydown', onKey);
  }, [onClose]);

  if (!t) return null;

  const tabBase = {
    display: 'flex', alignItems: 'center', gap: 7,
    padding: '8px 18px 10px', fontSize: 12.5, fontWeight: 700,
    background: 'transparent', border: 'none',
    borderBottom: '2.5px solid transparent', cursor: 'pointer',
    fontFamily: 'inherit', marginBottom: -1,
    color: 'var(--text-muted)',
  };
  const tabActive = { ...tabBase, color: t.accent, borderBottomColor: t.accent };

  return createPortal(
    <div
      onClick={e => { if (e.target === e.currentTarget) onClose(); }}
      style={{ position: 'fixed', inset: 0, zIndex: 9900, background: 'rgba(10,22,40,.7)', backdropFilter: 'blur(6px)', display: 'flex', alignItems: 'center', justifyContent: 'center', padding: 20, overflowY: 'auto' }}
    >
      <div style={{ background: 'var(--bg-card)', borderRadius: 18, width: '100%', maxWidth: 820, maxHeight: '92vh', display: 'flex', flexDirection: 'column', overflow: 'hidden', boxShadow: '0 24px 64px rgba(0,0,0,.4)', animation: 'fadeSlide .22s ease' }}>
        {/* Header */}
        <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', padding: '14px 22px', borderBottom: '1px solid var(--border-light)', background: 'var(--bg-muted)', flexShrink: 0 }}>
          <div style={{ display: 'flex', alignItems: 'center', gap: 10 }}>
            <div style={{ width: 32, height: 32, borderRadius: 8, background: t.accentLight, color: t.accent, display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: 14 }}>
              <i className="fa-solid fa-eye"></i>
            </div>
            <div>
              <div style={{ fontSize: 14, fontWeight: 700, color: 'var(--text-primary)' }}>{t.name} — Preview</div>
              <div style={{ fontSize: 11, color: 'var(--text-muted)', marginTop: 1 }}>Switch between Single and Combined Assessment previews</div>
            </div>
          </div>
          <div style={{ display: 'flex', gap: 8 }}>
            <button
              type="button"
              onClick={() => onSelect(t.id)}
              style={{ display: 'inline-flex', alignItems: 'center', gap: 6, padding: '7px 16px', borderRadius: 9, background: t.accent, border: 'none', color: '#fff', fontSize: 12.5, fontWeight: 700, cursor: 'pointer', fontFamily: 'inherit' }}
            >
              <i className="fa-solid fa-check"></i> Select
            </button>
            <button
              type="button"
              onClick={onClose}
              style={{ width: 32, height: 32, borderRadius: 8, border: '1.5px solid var(--border-light)', background: 'transparent', color: 'var(--text-muted)', cursor: 'pointer', display: 'flex', alignItems: 'center', justifyContent: 'center' }}
            >
              <i className="fa-solid fa-xmark"></i>
            </button>
          </div>
        </div>

        {/* Sub-tabs */}
        <div style={{ display: 'flex', gap: 0, padding: '12px 22px 0', borderBottom: '1px solid var(--border-light)', background: 'var(--bg-muted)', flexShrink: 0 }}>
          <button type="button" style={mode === 'single' ? tabActive : tabBase} onClick={() => setMode('single')}>
            <i className="fa-solid fa-file"></i> Single Assessment
          </button>
          <button type="button" style={mode === 'combined' ? tabActive : tabBase} onClick={() => setMode('combined')}>
            <i className="fa-solid fa-layer-group"></i> Combined Assessment
          </button>
        </div>

        {/* Preview area */}
        <div style={{ flex: 1, overflowY: 'auto', padding: 24, background: '#F1F5F9' }}>
          <div style={{ maxWidth: 720, margin: '0 auto', borderRadius: 12, overflow: 'hidden', boxShadow: '0 8px 32px rgba(0,0,0,.14)' }}>
            {t.id === 'classic' && (
              <ClassicResultCard
                rcoGeneral={rcoGeneral}
                rcoSig={rcoSig}
                rsSigs={rsSigs}
                rsAbsentMode={rsAbsentMode}
                mode={mode}
                preview
              />
            )}
            {t.id === 'insight' && (
              <InsightResultCard
                rcoGeneral={rcoGeneral}
                rcoSig={rcoSig}
                rsSigs={rsSigs}
                rsAbsentMode={rsAbsentMode}
                mode={mode}
                preview
              />
            )}
            {t.id === 'portfolio' && (
              <PortfolioResultCard
                rcoGeneral={rcoGeneral}
                rcoSig={rcoSig}
                rsSigs={rsSigs}
                rsAbsentMode={rsAbsentMode}
                mode={mode}
                preview
              />
            )}
          </div>
        </div>
      </div>
    </div>,
    document.body
  );
}

/* ═══════════════════════════════════════════════════════════════════
   RESULT SETUP — EDIT MODAL (4 tabs: grades, signatures, remarks, absent)
   ═══════════════════════════════════════════════════════════════════ */
function ResultSetupModal({ grades, sigs, remarks, absentMode, onAbsentChange, onSave, onClose, toast,
                           reloadGrades, reloadSigs, reloadRemarks }) {
  const [tab, setTab] = useState('grades');
  const [draftGrades, setDraftGrades] = useState(() => {
    if (grades && grades.length) {
      return grades.map(g => ({ ...g }));
    }
    return [];
  });
  const [draftSigs, setDraftSigs] = useState(() => {
    if (sigs && sigs.length) {
      return sigs.map(s => ({ ...s }));
    }
    return [];
  });
  const [draftRemarks, setDraftRemarks] = useState(() => {
    if (remarks && remarks.length) {
      return remarks.map(r => ({ ...r }));
    }
    return [];
  });
  const [draftAbsent, setDraftAbsent] = useState(absentMode);
  const [loading, setLoading] = useState(false);

  // Update drafts when props change
  useEffect(() => {
    if (grades && grades.length) {
      setDraftGrades(grades.map(g => ({ ...g })));
    }
  }, [grades]);

  useEffect(() => {
    if (sigs && sigs.length) {
      setDraftSigs(sigs.map(s => ({ ...s })));
    }
  }, [sigs]);

  useEffect(() => {
    if (remarks && remarks.length) {
      setDraftRemarks(remarks.map(r => ({ ...r })));
    }
  }, [remarks]);

  const upGrade = (id, k, v) => setDraftGrades(rows => rows.map(r => r.id === id ? { ...r, [k]: v } : r));
  const upSig = (id, k, v) => setDraftSigs(rows => rows.map(r => r.id === id ? { ...r, [k]: v } : r));
  const upRemark = (id, k, v) => setDraftRemarks(rows => rows.map(r => r.id === id ? { ...r, [k]: v } : r));

/* Naye (abhi tak save na huye) row ki unique id. Sirf `Date.now()` se ek hi
   millisecond me add hui do rows ko same id mil jati thi — phir ek row edit
   karne par dono badal jati thin. */
const tempId = () => `temp_${Date.now()}_${Math.random().toString(36).slice(2, 8)}`;

const addGrade = () =>
  setDraftGrades(r => {
    // Jo grades pehle se use ho chuki hain unhe skip karke agli available grade
    // default karo (A+ used → A, phir B+ ...). Sab use ho gayi to blank.
    const used = new Set(r.map(g => g.grade));
    const nextGrade = RS_GRADE_LIST.find(gr => !used.has(gr)) || '';
    return [
      ...r,
      { id: tempId(), grade: nextGrade, cond: 'gte', pct: '', comment: '' }
    ];
  });
   const addSig = () =>
  setDraftSigs(r => [
    ...r,
    { id: tempId(), name: '', desig: '', img: '' }
  ]);

const addRemark = () =>
  setDraftRemarks(r => [
    ...r,
    { id: tempId(), cond: 'gte', pct: '', text: '' }
  ]);  const [rsConfirm, setRsConfirm] = useState(null);

  const askDeleteGrade = g => setRsConfirm({
    kind: 'grade', id: g.id,
    title: 'Delete Grade',
    message: `Delete grade rule for <strong>${g.grade || '—'}</strong>?`,
  });
  const askDeleteSig = s => setRsConfirm({
    kind: 'sig', id: s.id,
    title: 'Delete Signature',
    message: `Delete signature for <strong>${s.name?.trim() || 'this entry'}</strong>?`,
  });
  const askDeleteRemark = r => setRsConfirm({
    kind: 'remark', id: r.id,
    title: 'Delete Remark',
    message: `Delete this final remark rule (${RS_COND_MAP[r.cond] || '≥'} ${r.pct || '—'}%)?`,
  });

const runDelete = async () => {
  if (!rsConfirm) return;

  const { kind, id } = rsConfirm;

  try {
    const token = sessionStorage.getItem("token");

    if (typeof id === "number" && id > 0) {
      let endpoint = "";

      if (kind === "grade") {
        endpoint = `/api/delete-grading-setup/${id}`;
      } else if (kind === "sig") {
        endpoint = `/api/delete-grading-uploader/${id}`;
      } else if (kind === "remark") {
        endpoint = `/api/delete-overall-grading/${id}`;
      }

      if (endpoint) {
        await fetch(buildUrl(endpoint), {
          method: "DELETE",
          headers: {
            Authorization: `Bearer ${token}`,
            Accept: "application/json"
          }
        });
      }
    }

    // Remove from local state
    if (kind === "grade") {
      setDraftGrades(r => r.filter(x => x.id !== id));
    }

    if (kind === "sig") {
      setDraftSigs(r => r.filter(x => x.id !== id));
    }

    if (kind === "remark") {
      setDraftRemarks(r => r.filter(x => x.id !== id));
    }

    setRsConfirm(null);

    toast("Deleted successfully", "success");
  } catch (err) {
    console.error(err);
    toast("Failed to delete", "error");
  }
};
  const uploadSig = (id, file) => {
    if (!file) return;
    const reader = new FileReader();
    reader.onload = e => upSig(id, 'img', e.target.result);
    reader.readAsDataURL(file);
  };

  // Helper function to save a single grade to API
  const saveGradeToAPI = async (grade) => {
    try {
      const token = sessionStorage.getItem('token');
      const branchID = sessionStorage.getItem('branchID');
      
      // Format percentage based on condition
      let percentage = '';
      switch (grade.cond) {
        case 'gte': percentage = `≥${grade.pct}`; break;
        case 'gt': percentage = `>${grade.pct}`; break;
        case 'lte': percentage = `≤${grade.pct}`; break;
        case 'lt': percentage = `<${grade.pct}`; break;
        case 'eq': percentage = `=${grade.pct}`; break;
        default: percentage = grade.pct;
      }
      
      const isUpdate = grade.id && typeof grade.id === 'number' && grade.id > 0;
      
      const payload = {
        id: isUpdate ? grade.id : 0,
        branchID: branchID || "1",
        percentage: percentage,
        grade: grade.grade || '',
        remarks: grade.comment || '',
        percentageNo: "",
        action: isUpdate ? "update" : "insert"
      };
      
      console.log("Saving grade payload:", payload);
      
      const response = await fetch(buildUrl('/api/gradingcrud'), {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          Authorization: `Bearer ${token}`,
          Accept: 'application/json'
        },
        body: JSON.stringify(payload)
      });
      
      const data = await response.json();
      console.log("Grade save response:", data);
      return { success: response.ok, data };
    } catch (error) {
      console.error("Error saving grade:", error);
      return { success: false, error };
    }
  };
  
  // Helper function to delete a grade from API
  const deleteGradeFromAPI = async (gradeId) => {
    try {
      const token = sessionStorage.getItem('token');
      const branchID = sessionStorage.getItem('branchID');
      
      const payload = {
        id: gradeId,
        branchID: branchID || "1",
        percentage: "",
        grade: "",
        remarks: "",
        percentageNo: "",
        action: "delete"
      };
      
      console.log("Deleting grade payload:", payload);
      
      const response = await fetch(buildUrl('/api/gradingcrud'), {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          Authorization: `Bearer ${token}`,
          Accept: 'application/json'
        },
        body: JSON.stringify(payload)
      });
      
      const data = await response.json();
      return { success: response.ok, data };
    } catch (error) {
      console.error("Error deleting grade:", error);
      return { success: false, error };
    }
  };
  
  // Helper function to save a single signature to API
  const saveSignatureToAPI = async (signature) => {
    try {
      const token = sessionStorage.getItem('token');
      const branchID = sessionStorage.getItem('branchID');
      
      const isUpdate = signature.id && typeof signature.id === 'number' && signature.id > 0;
      
      // Handle image - if it's a data URL, we need to send it as is or extract base64
      let signatureValue = signature.img || '';
      // If it's a file upload, we keep the data URL
      
      const payload = {
        id: isUpdate ? signature.id : 0,
        branchID: branchID || "1",
        name: signature.name || '',
        designation: signature.desig || '',
        signature: signatureValue,
        action: isUpdate ? "update" : "insert"
      };
      
      console.log("Saving signature payload:", payload);
      
      const response = await fetch(buildUrl('/api/gradinguploadercrud'), {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          Authorization: `Bearer ${token}`,
          Accept: 'application/json'
        },
        body: JSON.stringify(payload)
      });
      
      const data = await response.json();
      console.log("Signature save response:", data);
      return { success: response.ok, data };
    } catch (error) {
      console.error("Error saving signature:", error);
      return { success: false, error };
    }
  };
  
  // Helper function to delete a signature from API
  const deleteSignatureFromAPI = async (signatureId) => {
    try {
      const token = sessionStorage.getItem('token');
      const branchID = sessionStorage.getItem('branchID');
      
      const payload = {
        id: signatureId,
        branchID: branchID || "1",
        name: "",
        designation: "",
        signature: "",
        action: "delete"
      };
      
      const response = await fetch(buildUrl('/api/gradinguploadercrud'), {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          Authorization: `Bearer ${token}`,
          Accept: 'application/json'
        },
        body: JSON.stringify(payload)
      });
      
      const data = await response.json();
      return { success: response.ok, data };
    } catch (error) {
      console.error("Error deleting signature:", error);
      return { success: false, error };
    }
  };
  
  // Helper function to save a single remark to API
  const saveRemarkToAPI = async (remark) => {
    try {
      const token = sessionStorage.getItem('token');
      const branchID = sessionStorage.getItem('branchID');
      
      // Format percentage based on condition
      let percentage = '';
      switch (remark.cond) {
        case 'gte': percentage = `≥ ${remark.pct}`; break;
        case 'gt': percentage = `> ${remark.pct}`; break;
        case 'lte': percentage = `≤ ${remark.pct}`; break;
        case 'lt': percentage = `< ${remark.pct}`; break;
        case 'eq': percentage = `= ${remark.pct}`; break;
        default: percentage = remark.pct;
      }
      
      const isUpdate = remark.id && typeof remark.id === 'number' && remark.id > 0;
      
      const payload = {
        id: isUpdate ? remark.id : 0,
        branchID: branchID || "1",
        percentage: percentage,
        finalRemarks: remark.text || '',
        action: isUpdate ? "update" : "insert"
      };
      
      console.log("Saving remark payload:", payload);
      
      const response = await fetch(buildUrl('/api/overallgradingcrud'), {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          Authorization: `Bearer ${token}`,
          Accept: 'application/json'
        },
        body: JSON.stringify(payload)
      });
      
      const data = await response.json();
      console.log("Remark save response:", data);
      return { success: response.ok, data };
    } catch (error) {
      console.error("Error saving remark:", error);
      return { success: false, error };
    }
  };
  
  // Helper function to delete a remark from API
  const deleteRemarkFromAPI = async (remarkId) => {
    try {
      const token = sessionStorage.getItem('token');
      const branchID = sessionStorage.getItem('branchID');
      
      const payload = {
        id: remarkId,
        branchID: branchID || "1",
        percentage: "",
        finalRemarks: "",
        action: "delete"
      };
      
      const response = await fetch(buildUrl('/api/overallgradingcrud'), {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          Authorization: `Bearer ${token}`,
          Accept: 'application/json'
        },
        body: JSON.stringify(payload)
      });
      
      const data = await response.json();
      return { success: response.ok, data };
    } catch (error) {
      console.error("Error deleting remark:", error);
      return { success: false, error };
    }
  };

  const submit = async () => {
    // ── Validation (setLoading se PEHLE) — SIRF active tab validate hota hai ────
    // Har tab par uska apna toaster chale: Grade tab par grade, Signature tab par
    // signature, Remarks tab par remarks. Cross-tab toaster nahi. Duplicate check:
    // draft me us key ki count original (DB) se ZYADA ho (user ne naya banaya ho).
    const countBy = (arr, keyFn) => (arr || []).reduce((m, x) => {
      const k = keyFn(x); if (k) m[k] = (m[k] || 0) + 1; return m;
    }, {});
    const findUserDup = (draftArr, origArr, keyFn) => {
      const dCnt = countBy(draftArr, keyFn), oCnt = countBy(origArr, keyFn);
      for (const [key, cnt] of Object.entries(dCnt)) {
        if (cnt >= 2 && cnt > (oCnt[key] || 0)) return key;
      }
      return null;
    };

    if (tab === 'grades') {
      // Grade tab: har row me grade + percentage + comment required.
      const gVal = (g) => String(g.grade || '').trim();
      const gPct = (g) => { const p = String(g.pct ?? '').trim(); return p ? `${g.cond}|${p}` : ''; };
      // Grade tab par duplicate check ABSOLUTE hai: draft me kahin bhi ek grade
      // (ya ek hi percentage band) do baar aaye to error. Pehle sirf "original se
      // zyada" par error aata tha, is liye DB me pehle se maujood duplicate (wahi
      // grade, alag percentage) chup-chaap dobara save hote reh jate the.
      const findDup = (arr, keyFn) => {
        const seen = new Set();
        for (const x of arr || []) {
          const k = keyFn(x);
          if (!k) continue;
          if (seen.has(k)) return k;
          seen.add(k);
        }
        return null;
      };
      const dupVal = findDup(draftGrades, gVal);
      if (dupVal) { toast(`"${dupVal}" is added more than once. Remove the duplicate row before saving.`, 'error'); return; }
      if (findDup(draftGrades, gPct)) { toast('This percentage has already been assigned a grade.', 'error'); return; }
      const bad = (draftGrades || []).some(g =>
        !String(g.grade ?? '').trim() || !String(g.pct ?? '').trim() || !String(g.comment ?? '').trim());
      if (bad) { toast('Grade, percentage and comment cannot be empty.', 'error'); return; }
    } else if (tab === 'signatures') {
      // Signature tab: har row me name + designation + signature (image) required.
      const bad = (draftSigs || []).some(s =>
        !String(s.name ?? '').trim() || !String(s.desig ?? '').trim() || !String(s.img ?? '').trim());
      if (bad) { toast('Signature name, designation and image are required.', 'error'); return; }
    } else if (tab === 'remarks') {
      // Remarks tab: har row me percentage + final remark text required.
      const rPct = (r) => { const p = String(r.pct ?? '').trim(); return p ? `${r.cond}|${p}` : ''; };
      if (findUserDup(draftRemarks, remarks, rPct)) { toast('This percentage has already been assigned a remark.', 'error'); return; }
      const bad = (draftRemarks || []).some(r =>
        !String(r.pct ?? '').trim() || !String(r.text ?? '').trim());
      if (bad) { toast('Final remark cannot be empty.', 'error'); return; }
    }

    setLoading(true);

    // Save ke baad us tab ki fresh (server-side) rows — inme naye row ki asli DB
    // id hoti hai. Yahi rows parent ko jati hain, warna `temp_…` id parent state
    // me reh jati thi aur agla save UPDATE ki jagah dobara INSERT kar deta tha
    // (wahi grade doosri percentage ke saath duplicate ban jata tha).
    let freshGrades = null, freshSigs = null, freshRemarks = null;

    try {
      // SIRF active tab ki API hit ho — grades save karo to sirf grade API, waghera.
      if (tab === 'grades') {
        const newGradeIds = new Set(draftGrades.map(g => g.id).filter(id => typeof id === 'number'));
        // Find deleted grades (present in original but not in new)
        const deletedGrades = grades.filter(g => !newGradeIds.has(g.id));

        // Sirf COMPLETE grade rows save karo (grade + pct + comment).
        const gradesToSave = draftGrades.filter(g =>
          String(g.grade ?? '').trim() && String(g.pct ?? '').trim() && String(g.comment ?? '').trim());
        for (const grade of gradesToSave) {
          await saveGradeToAPI(grade);
        }
        // Delete removed grades
        for (const grade of deletedGrades) {
          if (grade.id && typeof grade.id === 'number') {
            await deleteGradeFromAPI(grade.id);
          }
        }
        freshGrades = await reloadGrades?.();
      }

      if (tab === 'signatures') {
        const newSigIds = new Set(draftSigs.map(s => s.id).filter(id => typeof id === 'number'));
        const deletedSigs = sigs.filter(s => !newSigIds.has(s.id));

        // Sirf COMPLETE signature rows save karo (name + designation + image).
        const sigsToSave = draftSigs.filter(s =>
          String(s.name ?? '').trim() && String(s.desig ?? '').trim() && String(s.img ?? '').trim());
        for (const sig of sigsToSave) {
          await saveSignatureToAPI(sig);
        }
        for (const sig of deletedSigs) {
          if (sig.id && typeof sig.id === 'number') {
            await deleteSignatureFromAPI(sig.id);
          }
        }
        freshSigs = await reloadSigs?.();
      }

      if (tab === 'remarks') {
        const newRemarkIds = new Set(draftRemarks.map(r => r.id).filter(id => typeof id === 'number'));
        const deletedRemarks = remarks.filter(r => !newRemarkIds.has(r.id));

        // Sirf COMPLETE remark rows save karo (percentage + text).
        const remarksToSave = draftRemarks.filter(r => String(r.pct ?? '').trim() && String(r.text ?? '').trim());
        for (const remark of remarksToSave) {
          await saveRemarkToAPI(remark);
        }
        for (const remark of deletedRemarks) {
          if (remark.id && typeof remark.id === 'number') {
            await deleteRemarkFromAPI(remark.id);
          }
        }
        freshRemarks = await reloadRemarks?.();
      }

      toast('Result setup saved successfully!', 'success');

      // Jis tab ko save kiya uske liye server-side rows (asli ids) bhejo; baqi
      // tabs ka draft waise ka waisa. Reload fail/khali ho to draft par fallback.
      const pick = (fresh, draft) => (Array.isArray(fresh) && fresh.length ? fresh : draft);

      // Call onSave to update parent state
      onSave({
        grades: pick(freshGrades, draftGrades),
        sigs: pick(freshSigs, draftSigs),
        remarks: pick(freshRemarks, draftRemarks),
        absentMode: draftAbsent,
      });
      
    } catch (error) {
      console.error("Error saving result setup:", error);
      toast('Error saving result setup', 'error');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="exam-modal-overlay open" onClick={e => { if (e.target === e.currentTarget) onClose(); }}>
      <div className="exam-modal rs-modal">
        <div className="exam-modal-header">
          <div className="exam-modal-header-left">
            <div className="exam-modal-header-icon"><i className="fa-solid fa-pen-to-square"></i></div>
            <div>
              <div className="exam-modal-title">Edit Result Setup</div>
              <div className="exam-modal-sub">Configure grades, signatures, final remarks &amp; absent handling</div>
            </div>
          </div>
          <Tooltip text="Close"><button className="exam-modal-close" onClick={onClose} aria-label="Close"><i className="fa-solid fa-xmark"></i></button></Tooltip>
        </div>

        {/* Modal tabs */}
        <div className="rs-modal-tabs">
          {[
            { k: 'grades', l: 'Grade', icon: 'fa-chart-bar' },
            { k: 'signatures', l: 'Signature', icon: 'fa-signature' },
            { k: 'remarks', l: 'Final Remarks', icon: 'fa-comment-dots' },
            { k: 'absent', l: 'Absent Handling', icon: 'fa-user-xmark' },
          ].map(t => (
            <button key={t.k} className={`rs-modal-tab${tab === t.k ? ' active' : ''}`} onClick={() => setTab(t.k)}>
              <i className={`fa-solid ${t.icon}`}></i> {t.l}
            </button>
          ))}
        </div>

        <div className="exam-modal-body rs-modal-body">
          {/* GRADES */}
          {tab === 'grades' && (
            <>
              {draftGrades.length === 0 ? (
                <div className="rs-empty">No grades configured. Click "Add Grade" to create one.</div>
              ) : (
                draftGrades.map((g, i) => (
                  <div key={g.id} className="rm-grade-row">
                    <div className="rm-sno">{i + 1}</div>
                    <select
                      className="rs-input"
                      value={g.grade || ''}
                      onChange={e => upGrade(g.id, 'grade', e.target.value)}
                    >
                      <option value="" disabled>Grade...</option>
                      {/* Jo grade kisi doosri row me pehle se chuni ja chuki hai wo is
                        dropdown me na aaye — sirf apni current value + baqi baaki bachi
                        grades dikhen (e.g. A+ add ho gaya to next me A+ hidden). */}
                      {RS_GRADE_LIST
                        .filter(opt => opt === g.grade || !draftGrades.some(o => o.id !== g.id && o.grade === opt))
                        .map(opt => <option key={opt} value={opt}>{opt}</option>)}
                    </select>
                    <select className="rs-input" value={g.cond || 'gte'} onChange={e => upGrade(g.id, 'cond', e.target.value)}>
                      {RS_COND_LIST.map(c => <option key={c.v} value={c.v}>{c.l}</option>)}
                    </select>
                    <input
                      className="rs-input"
                      type="number"
                      min={0}
                      max={100}
                      value={g.pct || ''}
                      placeholder="Value"
                      onChange={e => {
                        let v = e.target.value;
                        if (v !== '' && Number(v) > 100) v = '100';
                        if (v !== '' && Number(v) < 0) v = '0';
                        upGrade(g.id, 'pct', v);
                      }}
                    />
                    <CharField
                      value={g.comment || ''}
                      max={28}
                      placeholder="Comment (max 28 chars)"
                      onChange={v => upGrade(g.id, 'comment', v)}
                      toast={toast}
                    />
                    <Tooltip text="Remove this grade band">
                      <button className="rs-del" onClick={() => askDeleteGrade(g)}>
                        <i className="fa-solid fa-trash-can"></i>
                      </button>
                    </Tooltip>
                  </div>
                ))
              )}
              <Tooltip text="Add a new grade band">
                <button className="rs-add" onClick={addGrade}>
                  <i className="fa-solid fa-plus"></i> Add Grade
                </button>
              </Tooltip>
            </>
          )}

          {/* SIGNATURES */}
          {tab === 'signatures' && (
            <>
              {draftSigs.length === 0 ? (
                <div className="rs-empty">No signatures added. Click "Add Signature" to create one.</div>
              ) : (
                draftSigs.map((s, i) => (
                  <div key={s.id} className="rm-sig-row">
                    <div className="rm-sno">{i + 1}</div>
                    <input
                      className="rs-input"
                      value={s.name || ''}
                      placeholder="Name"
                      onChange={e => upSig(s.id, 'name', e.target.value)}
                    />
                    <input
                      className="rs-input"
                      value={s.desig || ''}
                      placeholder="Designation"
                      onChange={e => upSig(s.id, 'desig', e.target.value)}
                    />
                    <label className="rs-sig-upload">
                      <input type="file" accept="image/*" onChange={e => uploadSig(s.id, e.target.files[0])} />
                      {s.img ? (
                        <img src={s.img} alt="" />
                      ) : (
                        <div className="rs-sig-upload-placeholder">
                          <i className="fa-solid fa-plus"></i>
                          <span>{s.img || 'Upload'}</span>
                        </div>
                      )}
                    </label>
                    <Tooltip text="Remove this signatory">
                      <button className="rs-del" onClick={() => askDeleteSig(s)}>
                        <i className="fa-solid fa-trash-can"></i>
                      </button>
                    </Tooltip>
                  </div>
                ))
              )}
              <Tooltip text="Add a new signatory">
                <button className="rs-add" onClick={addSig}>
                  <i className="fa-solid fa-plus"></i> Add Signature
                </button>
              </Tooltip>
            </>
          )}

          {/* REMARKS */}
          {tab === 'remarks' && (
            <>
              {draftRemarks.length === 0 ? (
                <div className="rs-empty">No remarks configured. Click "Add Remark" to create one.</div>
              ) : (
                draftRemarks.map((r, i) => (
                  <div key={r.id} className="rm-remark-row">
                    <div className="rm-remark-top">
                      <div className="rm-sno">{i + 1}</div>
                      <select className="rs-input" value={r.cond || 'gte'} onChange={e => upRemark(r.id, 'cond', e.target.value)}>
                        {RS_COND_LIST.map(c => <option key={c.v} value={c.v}>{c.l}</option>)}
                      </select>
                      <input
                        className="rs-input"
                        type="number"
                        min={0}
                        max={100}
                        value={r.pct || ''}
                        placeholder="Percentage value"
                        onChange={e => {
                          let v = e.target.value;
                          if (v !== '' && Number(v) > 100) v = '100';
                          if (v !== '' && Number(v) < 0) v = '0';
                          upRemark(r.id, 'pct', v);
                        }}
                      />
                      <Tooltip text="Remove this remark">
                        <button className="rs-del" onClick={() => askDeleteRemark(r)}>
                          <i className="fa-solid fa-trash-can"></i>
                        </button>
                      </Tooltip>
                    </div>
                    <div className="rm-remark-bot">
                      <CharField
                        value={r.text || ''}
                        max={200}
                        placeholder="Final Remarks — max 200 characters"
                        multiline
                        onChange={v => upRemark(r.id, 'text', v)}
                        toast={toast}
                      />
                    </div>
                  </div>
                ))
              )}
              <Tooltip text="Add a new remark band">
                <button className="rs-add" onClick={addRemark}>
                  <i className="fa-solid fa-plus"></i> Add Remark
                </button>
              </Tooltip>
            </>
          )}

          {/* ABSENT */}
          {tab === 'absent' && (
            <>
              <div className="rs-abs-intro">
                Choose how absent subjects affect total marks, percentage and grade calculation on the Result Card. Leave both unchecked to hide subjects with 0 marks from the card.
              </div>
              {[
                {
                  v: 'zero',
                  title: 'Count Absent Subjects as Zero Marks',
                  desc: 'Absent subjects are included in the total marks but scored as 0. The student is assessed out of the full total marks.',
                  chips: ['10 subjects = 200 total', '2 absent → still / 200', 'Card shows: AB / 0'],
                  chipStyle: 'amber',
                },
                {
                  v: 'exclude',
                  title: 'Exclude Absent Subjects from Total Marks',
                  desc: 'Absent subjects are removed from the total entirely. The student is only assessed on subjects they attended.',
                  chips: ['10 subjects = 200 total', '2 absent → / 160', 'Card shows: AB'],
                  chipStyle: 'blue',
                },
              ].map(opt => {
                const isSel = draftAbsent === opt.v;
                return (
                  <div
                    key={opt.v}
                    className={`rs-abs-opt${isSel ? ' selected' : ''}`}
                    onClick={() => {
                      const next = draftAbsent === opt.v ? '' : opt.v;
                      setDraftAbsent(next);
                      onAbsentChange?.(next);
                    }}
                  >
                    <div className="rs-abs-radio">
                      <div className="rs-abs-radio-dot" style={{ display: isSel ? 'block' : 'none' }} />
                    </div>
                    <div style={{ flex: 1, minWidth: 0 }}>
                      <div className="rs-abs-opt-title">
                        {opt.title}
                      </div>
                      <div className="rs-abs-opt-desc">{opt.desc}</div>
                      <div className="rs-abs-chips">
                        {opt.chips.map((c, ci) => (
                          <span key={ci} className={`rs-abs-chip ${opt.chipStyle}`}>{c}</span>
                        ))}
                      </div>
                    </div>
                  </div>
                );
              })}
            </>
          )}
        </div>

        <div className="exam-modal-footer">
          <Tooltip text="Cancel and close">
            <button className="exam-cancel-btn" onClick={onClose} disabled={loading}>
              <i className="fa-solid fa-xmark"></i> Cancel
            </button>
          </Tooltip>
          <Tooltip text="Submit">
            <button className="exam-submit-btn" onClick={submit} disabled={loading}>
              {loading ? (
                <><i className="fa-solid fa-spinner fa-spin"></i> Saving...</>
              ) : (
                <><i className="fa-solid fa-floppy-disk"></i> Save</>
              )}
            </button>
          </Tooltip>
        </div>
      </div>

      {/* Nested delete confirmation */}
      {rsConfirm && (
        <div
          className="confirm-overlay open"
          style={{ zIndex: 1100 }}
          onClick={e => { if (e.target === e.currentTarget) setRsConfirm(null); }}
        >
          <div className="confirm-dialog">
            <div className="confirm-glow" style={{ background: 'linear-gradient(90deg,#EF4444,#DC2626,#EF4444)' }} />
            <div className="confirm-hero">
              <div className="confirm-ring">
                <div className="confirm-icon-wrap" style={{ background: 'rgba(220,38,38,.1)', color: '#DC2626' }}>
                  <i className="fa-solid fa-trash-can"></i>
                </div>
              </div>
            </div>
            <div className="confirm-body">
              <div className="confirm-title">{rsConfirm.title}</div>
              <div className="confirm-msg" dangerouslySetInnerHTML={{ __html: rsConfirm.message }} />
              <div className="confirm-hint">
                <i className="fa-solid fa-triangle-exclamation"></i>
                <span>This cannot be undone.</span>
              </div>
            </div>
            <div className="confirm-footer">
              <Tooltip text="Cancel and close">
                <button className="confirm-btn confirm-btn--cancel" onClick={() => setRsConfirm(null)}>Cancel</button>
              </Tooltip>
              <Tooltip text="Yes, Delete (confirm)">
                <button className="confirm-btn confirm-btn--confirm" onClick={runDelete}>Yes, Delete</button>
              </Tooltip>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

function CharField({ value, max, placeholder, multiline = false, onChange, toast }) {
  const warnRef  = useRef(false);
  const limitRef = useRef(false);
  const len = (value || '').length;
  const pct = max > 0 ? len / max : 0;
  const barCol = pct >= 1 ? '#DC2626' : pct >= 0.8 ? '#D97706' : '#1E40AF';
  const cntCol = pct >= 1 ? '#DC2626' : pct >= 0.8 ? '#D97706' : 'var(--text-muted)';
  const bdrCol = pct >= 1 ? '#DC2626' : pct >= 0.8 ? '#D97706' : 'var(--border-light)';
  const barW   = Math.min(100, Math.round(pct * 100));
  const label  = multiline ? 'Final Remarks' : 'Comment';

  const handle = next => {
    const nlen = next.length;
    const npct = max > 0 ? nlen / max : 0;
    if (npct >= 0.8 && npct < 1 && !warnRef.current) {
      warnRef.current  = true;
      limitRef.current = false;
      toast && toast(`${label}: only ${max - nlen} characters remaining.`, 'info');
    }
    if (npct >= 1 && !limitRef.current) {
      limitRef.current = true;
      toast && toast(`${label} limit reached — max ${max} characters.`, 'error');
    }
    if (npct < 0.8) { warnRef.current = false; limitRef.current = false; }
    onChange(next);
  };

  return (
    <div className="rs-cf-wrap">
      {multiline ? (
        <textarea
          className="rs-input rs-input-area"
          maxLength={max}
          placeholder={placeholder}
          value={value || ''}
          onChange={e => handle(e.target.value)}
          style={{ borderColor: bdrCol }}
        />
      ) : (
        <input
          className="rs-input"
          maxLength={max}
          placeholder={placeholder}
          value={value || ''}
          onChange={e => handle(e.target.value)}
          style={{ borderColor: bdrCol }}
        />
      )}
      <div className="rs-cf-meter">
        <div className="rs-cf-bar">
          <div style={{ width: `${barW}%`, background: barCol }} />
        </div>
        <span className="rs-cf-count" style={{ color: cntCol }}>
          {len}/{max}{multiline ? ' chars' : ''}
        </span>
      </div>
    </div>
  );
}

/* ═══════════════════════════════════════════════════════════════════
   RESULT SETUP — REPORT PICKER + BUILDER (A4 portrait)
   ═══════════════════════════════════════════════════════════════════ */
function ResultSetupReportPicker({ grades, sigs, remarks, absentMode, branchSchool, onClose }) {
  return (
    <StandardReportPicker
      open
      title="Result Setup"
      formats={['pdf', 'word', 'excel']}
      onClose={onClose}
      onGenerate={(style, format) => {
        generateResultSetupReport({ grades, sigs, remarks, absentMode, branchSchool }, style === 'color', format);
        onClose();
      }}
    />
  );
}

function generateResultSetupReport({ grades, sigs, remarks, absentMode, branchSchool }, isColor, format = 'pdf') {
  /* Real branch header (name / academic year) from /report-header (branchSchool) — shared report-kit header. */
  const bs         = branchSchool || {};

  const aColor = isColor ? '#1E40AF' : '#374151';
  const aBg    = isColor ? '#EFF6FF' : '#F5F5F5';
  const aBdr   = isColor ? '#BFDBFE' : '#DDD';
  const tMuted = isColor ? '#64748B' : '#666';
  const rowEv  = isColor ? '#F8FAFF' : '#F7F7F7';
  const accLight = isColor ? '#DBEAFE' : '#E5E5E5';

  const sectionCard = (icon, title, sub, body) => `
    <div style="margin-bottom:20px;border:1px solid ${aBdr};border-radius:12px;overflow:hidden;page-break-inside:avoid">
      <div style="display:flex;align-items:center;gap:11px;padding:12px 16px;background:${aBg};border-bottom:1px solid ${aBdr}">
        <div style="width:32px;height:32px;border-radius:8px;background:${accLight};color:${aColor};display:flex;align-items:center;justify-content:center;font-size:14px;flex-shrink:0">
          <i class="fa-solid ${icon}"></i>
        </div>
        <div>
          <div style="font-size:13.5px;font-weight:800;color:#0F172A">${title}</div>
          <div style="font-size:10.5px;color:${tMuted};margin-top:1px">${sub}</div>
        </div>
      </div>
      ${body}
    </div>`;

  // Grades table
  const gradesBody = grades.length ? `
    <table style="width:100%;table-layout:fixed;border-collapse:collapse;font-size:12px">
      <colgroup><col style="width:40px"><col style="width:60px"><col style="width:90px"><col></colgroup>
      <thead>
        <tr style="background:${aBg}">
          <th style="padding:8px 10px;font-size:9.5px;font-weight:700;color:${aColor};text-align:center;text-transform:uppercase;letter-spacing:.5px;border-bottom:1.5px solid ${aBdr}">#</th>
          <th style="padding:8px 10px;font-size:9.5px;font-weight:700;color:${aColor};text-align:center;text-transform:uppercase;letter-spacing:.5px;border-bottom:1.5px solid ${aBdr}">Grade</th>
          <th style="padding:8px 10px;font-size:9.5px;font-weight:700;color:${aColor};text-align:center;text-transform:uppercase;letter-spacing:.5px;border-bottom:1.5px solid ${aBdr}">Percentage</th>
          <th style="padding:8px 10px;font-size:9.5px;font-weight:700;color:${aColor};text-align:left;text-transform:uppercase;letter-spacing:.5px;border-bottom:1.5px solid ${aBdr}">Comment</th>
        </tr>
      </thead>
      <tbody>
        ${grades.map((g, i) => {
          const col = isColor ? (RS_GRADE_COLORS[g.grade] || aColor) : '#555';
          return `
            <tr style="background:${i % 2 === 0 ? '#fff' : rowEv}">
              <td style="padding:8px 10px;border-bottom:1px solid ${aBdr};text-align:center;color:${tMuted};font-weight:700">${i + 1}</td>
              <td style="padding:8px 10px;border-bottom:1px solid ${aBdr};text-align:center">
                <span style="display:inline-flex;min-width:36px;padding:3px 9px;border-radius:6px;background:${col};color:#fff;font-size:11.5px;font-weight:800;justify-content:center">${g.grade}</span>
              </td>
              <td style="padding:8px 10px;border-bottom:1px solid ${aBdr};text-align:center">
                <span style="display:inline-block;padding:2px 9px;border-radius:999px;background:${accLight};color:${aColor};font-size:11px;font-weight:700">${RS_COND_MAP[g.cond] || '≥'} ${g.pct}%</span>
              </td>
              <td style="padding:8px 10px;border-bottom:1px solid ${aBdr};color:#0F172A;font-size:11.5px">${g.comment || '—'}</td>
            </tr>`;
        }).join('')}
      </tbody>
    </table>` : `<div style="padding:16px;text-align:center;font-size:12px;color:${tMuted}">No grades configured</div>`;

  // Sigs table
  const sigsBody = sigs.length ? `
    <table style="width:100%;table-layout:fixed;border-collapse:collapse;font-size:12px">
      <colgroup><col style="width:40px"><col><col><col style="width:110px"></colgroup>
      <thead>
        <tr style="background:${aBg}">
          <th style="padding:8px 10px;font-size:9.5px;font-weight:700;color:${aColor};text-align:center;text-transform:uppercase;letter-spacing:.5px;border-bottom:1.5px solid ${aBdr}">#</th>
          <th style="padding:8px 10px;font-size:9.5px;font-weight:700;color:${aColor};text-align:left;text-transform:uppercase;letter-spacing:.5px;border-bottom:1.5px solid ${aBdr}">Name</th>
          <th style="padding:8px 10px;font-size:9.5px;font-weight:700;color:${aColor};text-align:left;text-transform:uppercase;letter-spacing:.5px;border-bottom:1.5px solid ${aBdr}">Designation</th>
          <th style="padding:8px 10px;font-size:9.5px;font-weight:700;color:${aColor};text-align:center;text-transform:uppercase;letter-spacing:.5px;border-bottom:1.5px solid ${aBdr}">Signature</th>
        </tr>
      </thead>
      <tbody>
        ${sigs.map((s, i) => `
          <tr style="background:${i % 2 === 0 ? '#fff' : rowEv}">
            <td style="padding:8px 10px;border-bottom:1px solid ${aBdr};text-align:center;color:${tMuted};font-weight:700">${i + 1}</td>
            <td style="padding:8px 10px;border-bottom:1px solid ${aBdr};font-size:11.5px;font-weight:700;color:#0F172A">${s.name || '—'}</td>
            <td style="padding:8px 10px;border-bottom:1px solid ${aBdr};font-size:11.5px;color:${tMuted}">${s.desig || '—'}</td>
            <td style="padding:8px 10px;border-bottom:1px solid ${aBdr};text-align:center">
              ${s.img
                ? `<img src="${s.img}" style="max-height:36px;max-width:100px;object-fit:contain" />`
                : `<span style="display:inline-block;padding:3px 9px;border-radius:6px;background:${accLight};color:${aColor};font-size:11px;font-weight:700">—</span>`}
            </td>
          </tr>`).join('')}
      </tbody>
    </table>` : `<div style="padding:16px;text-align:center;font-size:12px;color:${tMuted}">No signatures added</div>`;

  // Remarks table
  const remarksBody = remarks.length ? `
    <table style="width:100%;table-layout:fixed;border-collapse:collapse;font-size:12px">
      <colgroup><col style="width:40px"><col style="width:90px"><col style="width:100px"><col></colgroup>
      <thead>
        <tr style="background:${aBg}">
          <th style="padding:8px 10px;font-size:9.5px;font-weight:700;color:${aColor};text-align:center;text-transform:uppercase;letter-spacing:.5px;border-bottom:1.5px solid ${aBdr}">#</th>
          <th style="padding:8px 10px;font-size:9.5px;font-weight:700;color:${aColor};text-align:left;text-transform:uppercase;letter-spacing:.5px;border-bottom:1.5px solid ${aBdr}">Total Marks</th>
          <th style="padding:8px 10px;font-size:9.5px;font-weight:700;color:${aColor};text-align:center;text-transform:uppercase;letter-spacing:.5px;border-bottom:1.5px solid ${aBdr}">Percentage</th>
          <th style="padding:8px 10px;font-size:9.5px;font-weight:700;color:${aColor};text-align:left;text-transform:uppercase;letter-spacing:.5px;border-bottom:1.5px solid ${aBdr}">Remarks</th>
        </tr>
      </thead>
      <tbody>
        ${remarks.map((r, i) => `
          <tr style="background:${i % 2 === 0 ? '#fff' : rowEv}">
            <td style="padding:8px 10px;border-bottom:1px solid ${aBdr};text-align:center;color:${tMuted};font-weight:700">${i + 1}</td>
            <td style="padding:8px 10px;border-bottom:1px solid ${aBdr};font-size:11.5px;color:#0F172A">Total Marks</td>
            <td style="padding:8px 10px;border-bottom:1px solid ${aBdr};text-align:center">
              <span style="display:inline-block;padding:2px 9px;border-radius:999px;background:${accLight};color:${aColor};font-size:11px;font-weight:700">${RS_COND_MAP[r.cond] || '≥'} ${r.pct}%</span>
            </td>
            <td style="padding:8px 10px;border-bottom:1px solid ${aBdr};font-size:11.5px;color:#0F172A;line-height:1.5">${r.text || '—'}</td>
          </tr>`).join('')}
      </tbody>
    </table>` : `<div style="padding:16px;text-align:center;font-size:12px;color:${tMuted}">No remarks configured</div>`;

  // Absent body
  const isZero = absentMode === 'zero';
  const isExclude = absentMode === 'exclude';
  const absBody = `
    <div style="padding:14px 16px;display:flex;align-items:flex-start;gap:14px">
      <div style="width:34px;height:34px;border-radius:9px;background:${isZero ? 'rgba(217,119,6,.1)' : isExclude ? 'rgba(30,64,175,.1)' : 'rgba(100,116,139,.12)'};color:${isZero ? '#B45309' : isExclude ? aColor : '#475569'};display:flex;align-items:center;justify-content:center;font-size:14px;flex-shrink:0">
        <i class="fa-solid ${isZero ? 'fa-calculator' : isExclude ? 'fa-circle-minus' : 'fa-eye-slash'}"></i>
      </div>
      <div style="flex:1;min-width:0">
        <div style="font-size:12.5px;font-weight:700;color:#0F172A;margin-bottom:4px">
          ${isZero ? 'Count Absent Subjects as Zero Marks' : isExclude ? 'Exclude Absent Subjects from Total Marks' : 'No Absent Handling Selected'}
        </div>
        <div style="font-size:11px;color:${tMuted};line-height:1.6">
          ${isZero
            ? 'Absent subjects are scored as 0 and included in the full total. Card shows <strong>AB / 0</strong>.'
            : isExclude
              ? 'Absent subjects are removed from the total. Student is assessed on attended subjects only. Card shows <strong>AB</strong>.'
              : 'Subjects with <strong>0 marks</strong> are hidden from the Result Card.'}
        </div>
      </div>
      <span style="font-size:10.5px;font-weight:700;padding:3px 10px;border-radius:999px;background:${isZero ? 'rgba(217,119,6,.1)' : isExclude ? 'rgba(30,64,175,.1)' : 'rgba(100,116,139,.12)'};color:${isZero ? '#B45309' : isExclude ? aColor : '#475569'};border:1px solid ${isZero ? 'rgba(217,119,6,.25)' : isExclude ? 'rgba(30,64,175,.25)' : 'rgba(100,116,139,.25)'};white-space:nowrap">${isZero ? 'AB / 0' : isExclude ? 'AB' : 'Hidden'}</span>
    </div>`;

  const bodyHtml = `${EXAM_KIT_TABLE_CSS}
    ${sectionCard('fa-chart-bar', 'Grades Setup', `${grades.length} grade rule${grades.length !== 1 ? 's' : ''} configured`, gradesBody)}
    ${sectionCard('fa-signature', 'Signatures', `${sigs.length} signature${sigs.length !== 1 ? 's' : ''}`, sigsBody)}
    ${sectionCard('fa-comment-dots', 'Final Remarks', `${remarks.length} remark${remarks.length !== 1 ? 's' : ''} configured`, remarksBody)}
    ${sectionCard('fa-user-xmark', 'Absent Subject Handling', isZero ? 'Mode: Count as Zero' : isExclude ? 'Mode: Exclude from Total' : 'Mode: Hide 0-mark subjects', absBody)}`;

  const html = buildStandardReportHtml({
    title: 'Result Setup Report',
    format,
    isColor,
    bodyHtml,
    schoolName: examKitSchool(bs),
  });
  examDeliverReport('Result Setup Report', format, html, { width: 960, height: 820 });
}

/* ═══════════════════════════════════════════════════════════════════
   EXAM SETUP REPORT — header/footer/logo/toolbar chrome now comes from the
   shared reportKit (PDF + Word + Excel). Only the row-shaping (exam
   name/classes/status/dates) stays here, since that part is genuinely
   Exam-Setup-specific.
   ═══════════════════════════════════════════════════════════════════ */
function examSetupReportRows(list, isColor, fmtDate) {
  const p = reportPalette(isColor);
  return list.map((ex, i) => {
    const st  = getExamStatus(ex);
    const dur = calcDuration(ex.from, ex.to);
    const classLabels = (ex.classes || []).map(c => (typeof c === 'string'
      ? c
      : `${c.gradeName || ''}${c.sectionName ? ' - ' + c.sectionName : ''}`.trim() || (c.className || '')));
    const pillsHtml = classLabels.map(label =>
      `<span style="display:inline-block;padding:2px 8px;border-radius:99px;background:${isColor ? '#EFF6FF' : '#EEE'};color:${p.accent};font-size:10px;font-weight:600;border:1px solid ${p.border};margin:2px 3px 2px 0">${examKitEsc(label)}</span>`
    ).join('');
    const statusTone = st.cls === 'current' ? 'green' : st.cls === 'upcoming' ? 'amber' : 'gray';
    return {
      i: i + 1,
      nameHtml: `<div style="font-weight:800;color:${p.accent};font-size:12px">${ex.name}</div><div style="font-size:10.5px;color:${p.textM};margin-top:3px">${pillsHtml}</div>`,
      statusHtml: reportStatusPill(st.label, statusTone, p),
      from: fmtDate(ex.from), to: fmtDate(ex.to), duration: dur,
      name: ex.name, classes: classLabels.join(', '), status: st.label,
    };
  });
}

function generateExamReport(ctx, isColor, format = 'pdf') {
  const { req, exams, term, target, branchSchool } = ctx;
  /* `exams` already holds only the currently-loaded term's exams (getExamsByTerm
     replaces it on each term switch), and the API gives termName not term — so the
     "all" report uses the full list rather than a (mismatching) e.term filter. */
  const list = req.scope === 'all' ? (exams || []) : [target].filter(Boolean);
  /* Local date formatter (module-level fn can't reach the component-scoped one) —
     strips the time part and renders DD/MM/YYYY. */
  const fmtDate = (s) => {
    if (!s) return '—';
    let d;
    if (typeof s === 'string' && s.includes('-')) {
      const [y, m, day] = s.split('T')[0].split('-');
      d = new Date(Number(y), Number(m) - 1, Number(day));
    } else if (typeof s === 'string' && s.includes('/')) {
      const [day, m, y] = s.split('/');
      d = new Date(Number(y), Number(m) - 1, Number(day));
    } else { d = new Date(s); }
    if (isNaN(d.getTime())) return '—';
    const dd = String(d.getDate()).padStart(2, '0');
    const mm = String(d.getMonth() + 1).padStart(2, '0');
    return `${dd}/${mm}/${d.getFullYear()}`;
  };
  const isAll      = req.scope === 'all';
  const scopeTitle = isAll ? `${term} Term — All Exams` : (target ? target.name : '');
  const scopeLbl   = isAll ? 'All Exams (' + list.length + ')' : 'Single Exam';
  const reportName = `Exam Report - ${target?.name || (isAll ? 'All Exams' : '')}`;
  const rows = examSetupReportRows(list, isColor, fmtDate);

  if (format === 'excel') {
    downloadReportExcel({
      title: 'Examination Report', subtitle: scopeTitle,
      metaLine: `Scope: ${scopeLbl}  ·  Term: ${term}`,
      columns: [
        { key: 'i', label: '#', align: 'center' }, { key: 'name', label: 'Exam Name' }, { key: 'classes', label: 'Classes' },
        { key: 'status', label: 'Status', align: 'center' }, { key: 'from', label: 'Start', align: 'center' },
        { key: 'to', label: 'End', align: 'center' }, { key: 'duration', label: 'Duration', align: 'center' },
      ],
      rows, filename: `${reportFileName(reportName.replace(/\s*-\s*/g, ' '))}.xlsx`, isColor,
    });
    return;
  }

  const bodyHtml = buildReportTableHtml({
    columns: [
      { key: 'i', label: '#', align: 'center', width: '38px' },
      { key: 'nameHtml', label: 'Exam Name & Classes' },
      { key: 'statusHtml', label: 'Status', align: 'center', width: '110px' },
      { key: 'from', label: 'Start', align: 'center', width: '76px' },
      { key: 'to', label: 'End', align: 'center', width: '76px' },
      { key: 'duration', label: 'Duration', align: 'center', width: '70px' },
    ],
    rows, isColor, emptyText: 'No exams in this term.',
  });
  const html = buildStandardReportHtml({
    title: 'Examination Report',
    subtitleLine: examKitSub(branchSchool, examKitEsc(scopeTitle), `Term: ${examKitEsc(term)}`, `Scope: ${scopeLbl}`),
    schoolName: examKitSchool(branchSchool),
    format, isColor, bodyHtml, orientation: 'portrait',
  });
  // PDF → print preview; Word → wahi preview "Save as Word" button ke saath (deliverReport).
  deliverReport(reportName, format, html);
}
